);
const CrownIcon = () => (
  <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 24 24" fill="currentColor">
    <path d="M5 16L3 5l5.5 5L12 4l3.5 6L21 5l-2 11H5zm14 3c0 .55-.45 1-1 1H6c-.55 0-1-.45-1-1v-1h14v1z"></path>
  </svg>
);
const TrashIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
        <path fillRule="evenodd" d="M9 2a1 1 0 00-.894.553L7.382 4H4a1 1 0 000 2v10a2 2 0 002 2h8a2 2 0 002-2V6a1 1 0 100-2h-3.382l-.724-1.447A1 1 0 0011 2H9zM7 8a1 1 0 012 0v6a1 1 0 11-2 0V8zm4 0a1 1 0 012 0v6a1 1 0 11-2 0V8z" clipRule="evenodd" />
    </svg>
);
const UndoIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
        <path fillRule="evenodd" d="M9.707 14.707a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414l4-4a1 1 0 011.414 1.414L7.414 9H15a1 1 0 110 2H7.414l2.293 2.293a1 1 0 010 1.414z" clipRule="evenodd" />
    </svg>
);

export default App;

import React from 'react';
import { NUMBER_COLORS } from '../constants';

interface NumberGridProps {
  onNumberSelect: (num: number) => void;
  disabled: boolean;
}

const colorClasses = {
  red: 'bg-roulette-red hover:bg-red-700 active:bg-red-900 text-white',
  black: 'bg-roulette-black hover:bg-gray-700 active:bg-black text-white',
  green: 'bg-roulette-green hover:bg-green-700 active:bg-green-900 text-white',
};

export const NumberGrid: React.FC<NumberGridProps> = ({ onNumberSelect, disabled }) => {
  return (
    <div className={`flex gap-1.5 md:gap-3 transition-opacity duration-300 ${disabled ? 'opacity-50 cursor-not-allowed' : ''}`}>
      {/* Zero Button */}
      <button 
        onClick={() => onNumberSelect(0)} 
        disabled={disabled}
        className={`${colorClasses.green} font-bold text-2xl md:text-3xl rounded-md transition-all transform active:scale-95 hover:scale-[1.02] flex-shrink-0 flex items-center justify-center w-12 md:w-16 self-stretch shadow-md touch-manipulation`}
        aria-label="Number 0"
      >
        0
      </button>

      {/* Numbers 1-36 */}
      <div className="flex-grow grid grid-cols-12 gap-1 md:gap-1.5">
        {Array.from({ length: 12 }).map((_, colIndex) => (
          <div key={colIndex} className="flex flex-col-reverse gap-1 md:gap-1.5">
            {Array.from({ length: 3 }).map((_, rowIndex) => {
