export const FinalNumberMatrix: React.FC<FinalNumberMatrixProps> = ({ history }) => {
  // Sequence as requested: 1, 2, 3, 4, 5, 6, 7, 8, 9, 0
  const digits = [1, 2, 3, 4, 5, 6, 7, 8, 9, 0];
