interface SeriesTrackerProps {
  history: number[];
}

const SeriesColumnIcon: React.FC<{ series: SeriesType }> = ({ series }) => {
    const baseClasses = "w-8 h-8 rounded-full flex items-center justify-center font-bold border-2";

    switch (series) {
        case 'voisins':
            return <div title="Voisins" className={`${baseClasses} border-blue-400 bg-blue-400/20`}><svg viewBox="0 0 100 85" className="w-4 h-4 text-blue-400" fill="currentColor"><polygon points="50,0 100,85 0,85" /></svg></div>;
        case 'orphelins':
            return <div title="Orphelins" className={`${baseClasses} border-purple-400 bg-purple-400/20`}><div className="w-4 h-4 bg-purple-400 rounded-sm"></div></div>;
        case 'tiers':
            return <div title="Tiers" className={`${baseClasses} border-yellow-400 bg-yellow-400/20`}><svg viewBox="0 0 100 85" className="w-4 h-4 text-yellow-400" fill="currentColor"><polygon points="0,0 100,0 50,85" /></svg></div>;
        default:
            return null;
    }
