export default App;

import { VOISINS_SERIES, ORPHELINS_SERIES, TIERS_SERIES, EUROPEAN_WHEEL_ORDER } from '../constants';
import type { SeriesType } from '../types';

export const getSeriesType = (num: number): SeriesType => {
    if (VOISINS_SERIES.includes(num)) return 'voisins';
    if (ORPHELINS_SERIES.includes(num)) return 'orphelins';
    if (TIERS_SERIES.includes(num)) return 'tiers';
    return 'none';
};

/**
 * Gets a number and its neighbours on the European wheel.
 * @param num The center number
 * @param depth Number of neighbours on each side (1 for N3, 2 for N5)
 * @returns Array of numbers including center and neighbours
 */
export const getNeighbours = (num: number, depth: number = 1): number[] => {
    const index = EUROPEAN_WHEEL_ORDER.indexOf(num);
    if (index === -1) return [];

    const result: number[] = [];
    for (let i = -depth; i <= depth; i++) {
        const targetIndex = (index + i + EUROPEAN_WHEEL_ORDER.length) % EUROPEAN_WHEEL_ORDER.length;
        result.push(EUROPEAN_WHEEL_ORDER[targetIndex]);
    }
    return result;
};

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { NumberGrid } from './components/NumberGrid';
import { SpinHistory } from './components/SpinHistory';
import { BettingChart } from './components/BettingChart';
import { ToastContainer } from './components/Toast';
import { VipPage } from './components/VipPage';
import { ConfirmationModal } from './components/ConfirmationModal';
import type { ToastData, SeriesType } from './types';
import { getNeighbours, getSeriesType } from './utils/roulette';
import { PredictionDisplay } from './components/PredictionDisplay';

const MIN_SPINS_FOR_PATTERNS = 6;
const SESSION_STORAGE_KEY = 'rouletteSession';
const INPUT_THROTTLE_MS = 400;

const App: React.FC = () => {
  const [theme, setTheme] = useState<'light' | 'dark'>('dark');
  const [spinHistory, setSpinHistory] = useState<number[]>([]);
  const [alerts, setAlerts] = useState<ToastData[]>([]);
  const [alertsEnabled, setAlertsEnabled] = useState<boolean>(true);
  const [currentPage, setCurrentPage] = useState<'main' | 'vip'>('main');
  const [showClearConfirmation, setShowClearConfirmation] = useState<boolean>(false);
  const [bettingMap, setBettingMap] = useState<Map<number, number>>(new Map());
  const [balance, setBalance] = useState<number>(0);
  const [showRestoreConfirmation, setShowRestoreConfirmation] = useState<boolean>(false);
  const [savedSession, setSavedSession] = useState<{ history: number[], alerts: ToastData[] } | null>(null);

  // Throttling ref to prevent double-tap errors on mobile
  const lastInputTime = useRef<number>(0);

  // New state for betting controls
  const [isStrategyEnabled, setIsStrategyEnabled] = useState<boolean>(true);
  const [unitMultiplier, setUnitMultiplier] = useState<number>(1);
  const [unitMultiplierInput, setUnitMultiplierInput] = useState<string>('1');
  const [betStrategyMode, setBetStrategyMode] = useState<'235' | '123' | '111'>('235');
  const [neighbourDepth, setNeighbourDepth] = useState<3 | 5>(3);

  useEffect(() => {
    const savedData = localStorage.getItem(SESSION_STORAGE_KEY);
    if (savedData) {
        try {
            const parsedData = JSON.parse(savedData);
            if (Array.isArray(parsedData.history) && parsedData.history.length > 0 && Array.isArray(parsedData.alerts)) {
                setSavedSession(parsedData);
                setShowRestoreConfirmation(true);
            }
        } catch (error) {
            console.error("Failed to parse saved session:", error);
            localStorage.removeItem(SESSION_STORAGE_KEY);
        }
    }
  }, []);

  useEffect(() => {
    if (spinHistory.length > 0) {
        const sessionData = {
            history: spinHistory,
            alerts: alerts,
        };
        localStorage.setItem(SESSION_STORAGE_KEY, JSON.stringify(sessionData));
    } else {
        localStorage.removeItem(SESSION_STORAGE_KEY);
    }
  }, [spinHistory, alerts]);

  const calculateBets = useCallback((history: number[], mode: '235' | '123' | '111', depth: 3 | 5): Map<number, number> => {
    const newBettingMap = new Map<number, number>();
    const uniqueHistoryByRecency = [...new Set([...history].reverse())];

    if (uniqueHistoryByRecency.length < 2) {
      return newBettingMap;
    }

    const masterCandidatePool: number[] = [];
    uniqueHistoryByRecency.forEach(num => {
      if (num !== -1) {
        // depth 3 means 1 neighbor on each side (depth=1), depth 5 means 2 (depth=2)
        const depthVal = depth === 5 ? 2 : 1;
        masterCandidatePool.push(...getNeighbours(num, depthVal));
      }
    });

    const finalCandidates = [...new Set(masterCandidatePool)].filter(n => n !== -1);

    if (mode === '111') {
        finalCandidates.slice(0, 20).forEach(candidate => {
            newBettingMap.set(candidate, 1);
        });
        return newBettingMap;
    }

    const bet5 = new Set<number>();
    const bet3 = new Set<number>();
    const bet2 = new Set<number>();
    const alreadyBetOn = new Set<number>();

    for (const candidate of finalCandidates) {
      if (alreadyBetOn.has(candidate)) continue;
      if (bet5.size < 4) bet5.add(candidate);
      else if (bet3.size < 6) bet3.add(candidate);
      else if (bet2.size < 10) bet2.add(candidate);
      alreadyBetOn.add(candidate);
      if (bet2.size >= 10) break;
    }

    const units = mode === '235' ? [5, 3, 2] : [3, 2, 1];
    bet5.forEach(num => newBettingMap.set(num, units[0]));
    bet3.forEach(num => newBettingMap.set(num, units[1]));
    bet2.forEach(num => newBettingMap.set(num, units[2]));

    return newBettingMap;
  }, []);

  useEffect(() => {
      if (spinHistory.length > 0) {
          setBettingMap(calculateBets(spinHistory, betStrategyMode, neighbourDepth));
      } else {
          setBettingMap(new Map());
      }
  }, [spinHistory, betStrategyMode, neighbourDepth, calculateBets]);

  const totalBaseBetUnits = useMemo(() => {
    let total = 0;
    for (const unit of bettingMap.values()) {
      total += unit;
    }
    return total;
  }, [bettingMap]);

  useEffect(() => {
    if (!isStrategyEnabled) {
        setBalance(0);
        return;
    }

    let cumulativeBaseBalance = 0;
    for (let i = 8; i < spinHistory.length; i++) {
        const historySliceForBetting = spinHistory.slice(0, i);
        const winningNumber = spinHistory[i];

        const betsForThisRound = calculateBets(historySliceForBetting, betStrategyMode, neighbourDepth);
        const totalBaseBetForThisRound = (Array.from(betsForThisRound.values()) as number[]).reduce((sum, val) => sum + val, 0);

        if (totalBaseBetForThisRound > 0) {
            const betOnWinningNumber = betsForThisRound.get(winningNumber) || 0;
            const profitOrLoss = betOnWinningNumber > 0 
                ? (betOnWinningNumber * 36) - totalBaseBetForThisRound 
                : -totalBaseBetForThisRound;
            cumulativeBaseBalance += profitOrLoss;
        }
    }
    setBalance(cumulativeBaseBalance * unitMultiplier);

  }, [spinHistory, calculateBets, isStrategyEnabled, unitMultiplier, betStrategyMode, neighbourDepth]);

  useEffect(() => {
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prevTheme => (prevTheme === 'light' ? 'dark' : 'light'));
  };

  const checkForAlerts = useCallback((history: number[]): Omit<ToastData, 'id'>[] => {
    if (history.length < MIN_SPINS_FOR_PATTERNS || !alertsEnabled) return [];
    const newAlerts: Omit<ToastData, 'id'>[] = [];
    const lastSpin = history[history.length - 1];
    const predictions = new Map<string, number[]>();
    for (let i = 0; i <= history.length - 3; i++) {
      if (history[i] === lastSpin) {
        const prediction = [history[i + 1], history[i + 2]];
        predictions.set(prediction.join(','), prediction);
      }
    }
     for (let i = 0; i <= history.length - 2; i++) {
        if (history[i] === lastSpin) {
            if (history.length > i + 1 && !predictions.has(`${history[i+1]}`)) {
                 const prediction = [history[i+1]];
                 if(!Array.from(predictions.values()).some(p => p.length === 2 && p[0] === prediction[0])) {
                     predictions.set(prediction.join(','), prediction);
                 }
            }
        }
    }
    if (predictions.size > 0) newAlerts.push({ trigger: [lastSpin], predictions: Array.from(predictions.values()) });
    if (history.length > 1) {
      const lastTwoSpins = history.slice(-2);
      const twoSpinPredictions = new Map<string, number[]>();
      for (let i = 0; i <= history.length - 3; i++) {
        if (history[i] === lastTwoSpins[0] && history[i + 1] === lastTwoSpins[1]) {
          const prediction = [history[i + 2]];
          twoSpinPredictions.set(prediction.join(','), prediction);
        }
      }
      if(twoSpinPredictions.size > 0) newAlerts.push({ trigger: lastTwoSpins, predictions: Array.from(twoSpinPredictions.values()) });
    }
    return newAlerts;
  }, [alertsEnabled]);

  const handleAddSpin = useCallback((num: number) => {
    const now = Date.now();
    if (now - lastInputTime.current < INPUT_THROTTLE_MS) return;
    lastInputTime.current = now;

    // Optional haptic feedback for mobile
    if ('vibrate' in navigator) {
        navigator.vibrate(20);
    }

    const newHistory = [...spinHistory, num];
    setSpinHistory(newHistory);
    if (newHistory.length >= MIN_SPINS_FOR_PATTERNS) {
        const alertsFromCheck = checkForAlerts(newHistory);
        if (alertsFromCheck.length > 0) {
            const freshAlerts = alertsFromCheck.map((alert, index) => ({ ...alert, id: Date.now() + index })).reverse();
            setAlerts(currentAlerts => [...freshAlerts, ...currentAlerts].slice(0, 5));
        }
    }
  }, [spinHistory, checkForAlerts]);

  const handleRemoveLastSpin = useCallback(() => {
    if (spinHistory.length === 0) return;
    const now = Date.now();
    if (now - lastInputTime.current < INPUT_THROTTLE_MS) return;
    lastInputTime.current = now;

    const newHistory = spinHistory.slice(0, -1);
    const lastSpin = spinHistory[spinHistory.length - 1];
    const secondLastSpin = spinHistory.length > 1 ? spinHistory[spinHistory.length - 2] : null;
    setSpinHistory(newHistory);
    setAlerts(currentAlerts => currentAlerts.filter(alert => {
        const { trigger } = alert;
        if (trigger.length === 1 && trigger[0] === lastSpin) return false;
        if (trigger.length === 2 && secondLastSpin !== null && trigger[0] === secondLastSpin && trigger[1] === lastSpin) return false;
        return true;
    }));
  }, [spinHistory]);

  const handleRemoveAlert = (id: number) => setAlerts(currentAlerts => currentAlerts.filter(alert => alert.id !== id));

  const handleClearSession = () => {
    setSpinHistory([]);
    setAlerts([]);
    localStorage.removeItem(SESSION_STORAGE_KEY);
    setShowClearConfirmation(false);
  };

  const handleRestoreSession = useCallback(() => {
    if (savedSession) {
        setSpinHistory(savedSession.history);
        setAlerts(savedSession.alerts);
    }
    setShowRestoreConfirmation(false);
  }, [savedSession]);

  const handleStartNewSession = () => {
      localStorage.removeItem(SESSION_STORAGE_KEY);
      setSpinHistory([]);
      setAlerts([]);
      setShowRestoreConfirmation(false);
  };

  const prediction = useMemo<SeriesType | null>(() => {
    if (spinHistory.length < 4) return null;
    const seriesHistory = spinHistory.map(getSeriesType);
    if (seriesHistory.length < 3) return null;
    const triggerPattern = seriesHistory.slice(-3);

    for (let i = seriesHistory.length - 4; i >= 0; i--) {
        const historicalPattern = seriesHistory.slice(i, i + 3);
        if (historicalPattern.every((val, index) => val === triggerPattern[index])) {
            const prediction = seriesHistory[i + 3];
            return prediction === 'none' ? null : prediction;
        }
    }
    return null;
  }, [spinHistory]);

  return (
    <div className="min-h-screen text-gray-800 dark:text-gray-200 font-sans selection:bg-gold/30">
      <header className="bg-white/80 dark:bg-gray-900/80 backdrop-blur-sm sticky top-0 z-20 shadow-md">
        <div className="container mx-auto px-4 py-3 flex justify-between items-center">
          <h1 className="text-xl md:text-2xl font-bold text-gray-900 dark:text-white" style={{fontFamily: "'Playfair Display', serif"}}>
            Roulette <span className="text-gold">Pattern Tracker</span>
          </h1>
          <div className="flex items-center space-x-2 sm:space-x-4">
            <button 
              type="button" 
              onClick={() => setCurrentPage(currentPage === 'main' ? 'vip' : 'main')} 
              title="VIP Dashboard" 
              className="p-1.5 sm:p-2 rounded-lg text-gold hover:bg-gray-200 dark:hover:bg-gray-700 transition-colors flex items-center space-x-1 border border-gold/20"
            >
              <CrownIcon />
              <span className="text-[10px] sm:text-xs font-black uppercase tracking-tighter">VIP Dashboard</span>
            </button>
            <button onClick={toggleTheme} className="p-2 rounded-full text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-700">
              {theme === 'light' ? <MoonIcon /> : <SunIcon />}
            </button>
          </div>
        </div>
      </header>

      <main className="container mx-auto p-4 max-w-5xl">
        {currentPage === 'main' ? (
          <div className="flex flex-col gap-4">
            <div className="w-full bg-white dark:bg-gray-800 p-4 rounded-lg shadow-lg border border-gray-200 dark:border-gray-700">
                <h2 className="text-lg font-semibold mb-3 text-gray-700 dark:text-gray-300">Enter Spin</h2>
                <NumberGrid onNumberSelect={handleAddSpin} disabled={false} />
            </div>

            <div className="bg-white dark:bg-gray-800 p-4 rounded-lg shadow-lg border border-gray-200 dark:border-gray-700">
                <div className="flex justify-between items-center gap-x-4 mb-3">
                    <h2 className="text-sm font-semibold text-gray-700 dark:text-gray-300 whitespace-nowrap">Neighbour Number Strategy</h2>
                    <div className="flex flex-wrap items-center justify-end gap-x-2 sm:gap-x-3 gap-y-2">
                        <button id="strategy-toggle" onClick={() => setIsStrategyEnabled(!isStrategyEnabled)} className={`relative inline-flex items-center h-5 rounded-full w-9 transition-colors flex-shrink-0 ${isStrategyEnabled ? 'bg-roulette-green' : 'bg-gray-400 dark:bg-gray-600'}`} aria-pressed={isStrategyEnabled} aria-label="Toggle betting strategy">
                            <span className={`inline-block w-3 h-3 transform bg-white rounded-full transition-transform ${isStrategyEnabled ? 'translate-x-5' : 'translate-x-1'}`} />
                        </button>
                        <div className="flex items-center gap-1">
                            <label htmlFor="unit-multiplier" className="text-xs font-medium text-gray-500 dark:text-gray-400">Unit</label>
                            <input
                                type="number"
                                id="unit-multiplier"
                                value={unitMultiplierInput}
                                onChange={(e) => {
                                    const value = e.target.value;
                                    setUnitMultiplierInput(value);
                                    const num = parseInt(value, 10);
                                    if (!isNaN(num) && num > 0) {
                                        setUnitMultiplier(num);
                                    }
                                }}
                                onBlur={(e) => {
                                    const num = parseInt(e.target.value, 10);
                                    if (isNaN(num) || num < 1) {
                                        setUnitMultiplierInput('1');
                                        setUnitMultiplier(1);
                                    }
                                }}
                                disabled={!isStrategyEnabled}
                                className="w-12 bg-gray-100 dark:bg-gray-700 rounded py-1 px-1.5 text-center font-semibold text-xs focus:ring-1 focus:ring-gold outline-none disabled:opacity-50"
                            />
                        </div>
                        <div className="flex items-center gap-1.5">
                            <span className="text-[10px] font-bold text-gray-400 dark:text-gray-500 uppercase">Mode:</span>
                            <div className="flex items-center bg-gray-200 dark:bg-gray-700 rounded-md p-0.5">
                                <button 
                                    onClick={() => setNeighbourDepth(3)}
                                    disabled={!isStrategyEnabled}
                                    className={`px-2 py-0.5 text-[10px] font-black rounded transition-all ${neighbourDepth === 3 ? 'bg-gold text-black shadow-sm' : 'text-gray-500'}`}
                                >
                                    N3
                                </button>
                                <button 
                                    onClick={() => setNeighbourDepth(5)}
                                    disabled={!isStrategyEnabled}
                                    className={`px-2 py-0.5 text-[10px] font-black rounded transition-all ${neighbourDepth === 5 ? 'bg-gold text-black shadow-sm' : 'text-gray-500'}`}
                                >
                                    N5
                                </button>
                            </div>
                            <button 
                                onClick={() => setBetStrategyMode(m => m === '235' ? '123' : m === '123' ? '111' : '235')}
                                disabled={!isStrategyEnabled} 
                                className={`px-2 py-0.5 text-xs font-semibold rounded-md transition-colors disabled:opacity-40 flex-shrink-0 ${
                                    betStrategyMode === '235' ? 'bg-green-300 text-green-900 hover:bg-green-400 dark:bg-green-700 dark:text-green-100 dark:hover:bg-green-600' :
                                    betStrategyMode === '123' ? 'bg-yellow-300 text-yellow-900 hover:bg-yellow-400 dark:bg-yellow-700 dark:text-yellow-100 dark:hover:bg-yellow-600' :
                                    'bg-blue-300 text-blue-900 hover:bg-blue-400 dark:bg-blue-700 dark:text-blue-100 dark:hover:bg-blue-600'
                                }`}
                                title="Change Weighting Mode"
                            >
                                {betStrategyMode}
                            </button>
                        </div>
                    </div>
                </div>

                {isStrategyEnabled && (
                    <div className="animate-fade-in">
                        {spinHistory.length >= 8 ? (
                            <>
                                <div className="flex justify-end items-center gap-4 mb-3 border-t border-gray-200 dark:border-gray-700 pt-3">
                                    <div className="text-sm">
                                        <span className="font-semibold text-gray-500 dark:text-gray-400">Balance: </span>
                                        <span className={`font-bold ${balance >= 0 ? 'text-green-500' : 'text-red-500'}`}>
                                            {balance >= 0 ? '+' : ''}{balance.toLocaleString()} units
                                        </span>
                                    </div>
                                    {bettingMap.size > 0 && (
                                        <div className="text-sm font-semibold text-gray-600 dark:text-gray-400">
                                            Next Bet: <span className="text-gold font-bold text-base">{totalBaseBetUnits * unitMultiplier}</span>
                                        </div>
                                    )}
                                </div>
                                <BettingChart bettingMap={bettingMap} />
                            </>
                        ) : (
                            <div className="border-t border-gray-200 dark:border-gray-700 pt-3 mt-3">
                                <p className="text-center text-gray-500 dark:text-gray-400">
                                    Spin {8 - spinHistory.length} more time{spinHistory.length === 7 ? '' : 's'} to start strategy.
                                </p>
                            </div>
                        )}
                    </div>
                )}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mt-4">
                <div className="bg-white dark:bg-gray-800 p-4 rounded-lg shadow-lg border border-gray-200 dark:border-gray-700">
                    <div className="flex justify-between items-center mb-3">
                        <h2 className="text-lg font-semibold text-gray-700 dark:text-gray-300">Spin History ({spinHistory.length})</h2>
                        <PredictionDisplay prediction={prediction} />
                    </div>
                    {spinHistory.length > 0 ? <SpinHistory history={spinHistory} /> : <p className="text-gray-500 dark:text-gray-400 text-center py-4">No spins recorded yet.</p>}
                </div>
                <div className="bg-white dark:bg-gray-800 p-4 rounded-lg shadow-lg border border-gray-200 dark:border-gray-700">
                    <h2 className="text-lg font-semibold mb-3 text-gray-700 dark:text-gray-300">Active Alerts</h2>
                    <ToastContainer toasts={alerts} onRemoveToast={handleRemoveAlert} />
                </div>
            </div>

            <div className="bg-white dark:bg-gray-800 p-3 rounded-lg shadow-lg mt-4 border border-gray-200 dark:border-gray-700">
                <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
                    <h2 className="text-base font-semibold text-gray-700 dark:text-gray-300 sr-only md:not-sr-only">Controls</h2>
                    <div className="flex items-center justify-between bg-gray-100 dark:bg-gray-700 p-2 rounded-md flex-1 max-w-xs">
                        <label htmlFor="alerts" className="font-medium text-sm">Enable Alerts</label>
                        <button onClick={() => setAlertsEnabled(!alertsEnabled)} className={`relative inline-flex items-center h-6 rounded-full w-11 transition-colors ${alertsEnabled ? 'bg-roulette-green' : 'bg-gray-400 dark:bg-gray-600'}`}>
                            <span className={`inline-block w-4 h-4 transform bg-white rounded-full transition-transform ${alertsEnabled ? 'translate-x-6' : 'translate-x-1'}`}/>
                        </button>
                    </div>
                     <div className="grid grid-cols-2 gap-2 flex-1 max-w-xs">
                        <button onClick={handleRemoveLastSpin} disabled={spinHistory.length === 0} className="w-full bg-yellow-500 text-white font-semibold py-2 px-2 rounded-md hover:bg-yellow-600 transition-colors duration-200 flex items-center justify-center space-x-2 disabled:bg-gray-500 dark:disabled:bg-gray-600 disabled:cursor-not-allowed text-sm active:scale-95 touch-manipulation">
                            <UndoIcon />
                            <span>Remove<span className="hidden sm:inline"> Last</span></span>
                        </button>
                        <button onClick={() => setShowClearConfirmation(true)} className="w-full bg-roulette-red text-white font-semibold py-2 px-2 rounded-md hover:bg-red-700 transition-colors duration-200 flex items-center justify-center space-x-2 text-sm active:scale-95 touch-manipulation">
                            <TrashIcon />
                            <span>Clear<span className="hidden sm:inline"> Session</span></span>
                        </button>
                    </div>
                </div>
            </div>
          </div>
        ) : (
          <VipPage spinHistory={spinHistory} onBack={() => setCurrentPage('main')} prediction={prediction} />
        )}
      </main>
      <ConfirmationModal
        isOpen={showClearConfirmation}
        onClose={() => setShowClearConfirmation(false)}
        onConfirm={handleClearSession}
        title="Confirm to remove all record"
        message="This will clear all spin history and detected patterns. This action cannot be undone."
      />
      <ConfirmationModal
        isOpen={showRestoreConfirmation}
        onClose={handleStartNewSession}
        onConfirm={handleRestoreSession}
        title="Restore Previous Session?"
        message="We found a saved session. Would you like to restore your progress or start a new session?"
        confirmText="Restore"
        cancelText="New Session"
        confirmButtonClass="bg-roulette-green text-white hover:bg-green-700"
        cancelButtonClass="bg-gray-500 text-white hover:bg-gray-600"
      />
    </div>
  );
};

const SunIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 sm:h-6 sm:w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z" />
    </svg>
);
const MoonIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 sm:h-6 sm:w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z" />
    </svg>
);
const CrownIcon = () => (
  <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 sm:h-5 sm:w-5" viewBox="0 0 24 24" fill="currentColor">
    <path d="M5 16L3 5l5.5 5L12 4l3.5 6L21 5l-2 11H5zm14 3c0 .55-.45 1-1 1H6c-.55 0-1-.45-1-1v-1h14v1z"></path>
  </svg>
);
const TrashIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
        <path fillRule="evenodd" d="M9 2a1 1 0 00-.894.553L7.382 4H4a1 1 0 000 2v10a2 2 0 002 2h8a2 2 0 002-2V6a1 1 0 100-2h-3.382l-.724-1.447A1 1 0 0011 2H9zM7 8a1 1 0 012 0v6a1 1 0 11-2 0V8zm4 0a1 1 0 012 0v6a1 1 0 11-2 0V8z" clipRule="evenodd" />
    </svg>
);
const UndoIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
        <path fillRule="evenodd" d="M9.707 14.707a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414l4-4a1 1 0 011.414 1.414L7.414 9H15a1 1 0 110 2H7.414l2.293 2.293a1 1 0 010 1.414z" clipRule="evenodd" />
    </svg>
);

export default App;

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { NumberGrid } from './components/NumberGrid';
import { SpinHistory } from './components/SpinHistory';
import { BettingChart } from './components/BettingChart';
import { ToastContainer } from './components/Toast';
import { VipPage } from './components/VipPage';
import { ConfirmationModal } from './components/ConfirmationModal';
import type { ToastData, SeriesType } from './types';
import { getNeighbours, getSeriesType } from './utils/roulette';
import { PredictionDisplay } from './components/PredictionDisplay';

const MIN_SPINS_FOR_PATTERNS = 6;
const SESSION_STORAGE_KEY = 'rouletteSession';
const INPUT_THROTTLE_MS = 400;

const App: React.FC = () => {
  const [theme, setTheme] = useState<'light' | 'dark'>('dark');
  const [spinHistory, setSpinHistory] = useState<number[]>([]);
  const [alerts, setAlerts] = useState<ToastData[]>([]);
  const [alertsEnabled, setAlertsEnabled] = useState<boolean>(true);
  const [currentPage, setCurrentPage] = useState<'main' | 'vip'>('main');
  const [showClearConfirmation, setShowClearConfirmation] = useState<boolean>(false);
  const [bettingMap, setBettingMap] = useState<Map<number, number>>(new Map());
  const [balance, setBalance] = useState<number>(0);
  const [showRestoreConfirmation, setShowRestoreConfirmation] = useState<boolean>(false);
  const [savedSession, setSavedSession] = useState<{ history: number[], alerts: ToastData[] } | null>(null);

  // Throttling ref to prevent double-tap errors on mobile
  const lastInputTime = useRef<number>(0);

  // New state for betting controls
  const [isStrategyEnabled, setIsStrategyEnabled] = useState<boolean>(true);
  const [unitMultiplier, setUnitMultiplier] = useState<number>(1);
  const [unitMultiplierInput, setUnitMultiplierInput] = useState<string>('1');
  const [betStrategyMode, setBetStrategyMode] = useState<'235' | '123' | '111'>('235');
  const [neighbourDepth, setNeighbourDepth] = useState<3 | 5>(3);

  useEffect(() => {
    const savedData = localStorage.getItem(SESSION_STORAGE_KEY);
    if (savedData) {
        try {
            const parsedData = JSON.parse(savedData);
            if (Array.isArray(parsedData.history) && parsedData.history.length > 0 && Array.isArray(parsedData.alerts)) {
                setSavedSession(parsedData);
                setShowRestoreConfirmation(true);
            }
        } catch (error) {
            console.error("Failed to parse saved session:", error);
            localStorage.removeItem(SESSION_STORAGE_KEY);
        }
    }
  }, []);

  useEffect(() => {
    if (spinHistory.length > 0) {
        const sessionData = {
            history: spinHistory,
            alerts: alerts,
        };
        localStorage.setItem(SESSION_STORAGE_KEY, JSON.stringify(sessionData));
    } else {
        localStorage.removeItem(SESSION_STORAGE_KEY);
    }
  }, [spinHistory, alerts]);

  const calculateBets = useCallback((history: number[], mode: '235' | '123' | '111', depth: 3 | 5): Map<number, number> => {
    const newBettingMap = new Map<number, number>();
    const uniqueHistoryByRecency = [...new Set([...history].reverse())];

    if (uniqueHistoryByRecency.length < 2) {
      return newBettingMap;
    }

    const masterCandidatePool: number[] = [];
    uniqueHistoryByRecency.forEach(num => {
      if (num !== -1) {
        // depth 3 means 1 neighbor on each side (depth=1), depth 5 means 2 (depth=2)
        const depthVal = depth === 5 ? 2 : 1;
        masterCandidatePool.push(...getNeighbours(num, depthVal));
      }
    });

    const finalCandidates = [...new Set(masterCandidatePool)].filter(n => n !== -1);

    if (mode === '111') {
        finalCandidates.slice(0, 20).forEach(candidate => {
            newBettingMap.set(candidate, 1);
        });
        return newBettingMap;
    }

    const bet5 = new Set<number>();
    const bet3 = new Set<number>();
    const bet2 = new Set<number>();
    const alreadyBetOn = new Set<number>();

    for (const candidate of finalCandidates) {
      if (alreadyBetOn.has(candidate)) continue;
      if (bet5.size < 4) bet5.add(candidate);
      else if (bet3.size < 6) bet3.add(candidate);
      else if (bet2.size < 10) bet2.add(candidate);
      alreadyBetOn.add(candidate);
      if (bet2.size >= 10) break;
    }

    const units = mode === '235' ? [5, 3, 2] : [3, 2, 1];
    bet5.forEach(num => newBettingMap.set(num, units[0]));
    bet3.forEach(num => newBettingMap.set(num, units[1]));
    bet2.forEach(num => newBettingMap.set(num, units[2]));

    return newBettingMap;
  }, []);

  useEffect(() => {
      if (spinHistory.length > 0) {
          setBettingMap(calculateBets(spinHistory, betStrategyMode, neighbourDepth));
      } else {
          setBettingMap(new Map());
      }
  }, [spinHistory, betStrategyMode, neighbourDepth, calculateBets]);

  const totalBaseBetUnits = useMemo(() => {
    let total = 0;
    for (const unit of bettingMap.values()) {
      total += unit;
    }
    return total;
  }, [bettingMap]);

  useEffect(() => {
    if (!isStrategyEnabled) {
        setBalance(0);
        return;
    }

    let cumulativeBaseBalance = 0;
    for (let i = 8; i < spinHistory.length; i++) {
        const historySliceForBetting = spinHistory.slice(0, i);
        const winningNumber = spinHistory[i];

        const betsForThisRound = calculateBets(historySliceForBetting, betStrategyMode, neighbourDepth);
        const totalBaseBetForThisRound = (Array.from(betsForThisRound.values()) as number[]).reduce((sum, val) => sum + val, 0);

        if (totalBaseBetForThisRound > 0) {
            const betOnWinningNumber = betsForThisRound.get(winningNumber) || 0;
            const profitOrLoss = betOnWinningNumber > 0 
                ? (betOnWinningNumber * 36) - totalBaseBetForThisRound 
                : -totalBaseBetForThisRound;
            cumulativeBaseBalance += profitOrLoss;
        }
    }
    setBalance(cumulativeBaseBalance * unitMultiplier);

  }, [spinHistory, calculateBets, isStrategyEnabled, unitMultiplier, betStrategyMode, neighbourDepth]);

  useEffect(() => {
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prevTheme => (prevTheme === 'light' ? 'dark' : 'light'));
  };

  const checkForAlerts = useCallback((history: number[]): Omit<ToastData, 'id'>[] => {
    if (history.length < MIN_SPINS_FOR_PATTERNS || !alertsEnabled) return [];
    const newAlerts: Omit<ToastData, 'id'>[] = [];
    const lastSpin = history[history.length - 1];
    const predictions = new Map<string, number[]>();
    for (let i = 0; i <= history.length - 3; i++) {
      if (history[i] === lastSpin) {
        const prediction = [history[i + 1], history[i + 2]];
        predictions.set(prediction.join(','), prediction);
      }
    }
     for (let i = 0; i <= history.length - 2; i++) {
        if (history[i] === lastSpin) {
            if (history.length > i + 1 && !predictions.has(`${history[i+1]}`)) {
                 const prediction = [history[i+1]];
                 if(!Array.from(predictions.values()).some(p => p.length === 2 && p[0] === prediction[0])) {
                     predictions.set(prediction.join(','), prediction);
                 }
            }
        }
    }
    if (predictions.size > 0) newAlerts.push({ trigger: [lastSpin], predictions: Array.from(predictions.values()) });
    if (history.length > 1) {
      const lastTwoSpins = history.slice(-2);
      const twoSpinPredictions = new Map<string, number[]>();
      for (let i = 0; i <= history.length - 3; i++) {
        if (history[i] === lastTwoSpins[0] && history[i + 1] === lastTwoSpins[1]) {
          const prediction = [history[i + 2]];
          twoSpinPredictions.set(prediction.join(','), prediction);
        }
      }
      if(twoSpinPredictions.size > 0) newAlerts.push({ trigger: lastTwoSpins, predictions: Array.from(twoSpinPredictions.values()) });
    }
    return newAlerts;
  }, [alertsEnabled]);

  const handleAddSpin = useCallback((num: number) => {
    const now = Date.now();
    if (now - lastInputTime.current < INPUT_THROTTLE_MS) return;
    lastInputTime.current = now;

    // Optional haptic feedback for mobile
    if ('vibrate' in navigator) {
        navigator.vibrate(20);
    }

    const newHistory = [...spinHistory, num];
    setSpinHistory(newHistory);
    if (newHistory.length >= MIN_SPINS_FOR_PATTERNS) {
        const alertsFromCheck = checkForAlerts(newHistory);
        if (alertsFromCheck.length > 0) {
            const freshAlerts = alertsFromCheck.map((alert, index) => ({ ...alert, id: Date.now() + index })).reverse();
            setAlerts(currentAlerts => [...freshAlerts, ...currentAlerts].slice(0, 5));
        }
    }
  }, [spinHistory, checkForAlerts]);

  const handleRemoveLastSpin = useCallback(() => {
    if (spinHistory.length === 0) return;
    const now = Date.now();
    if (now - lastInputTime.current < INPUT_THROTTLE_MS) return;
    lastInputTime.current = now;

    const newHistory = spinHistory.slice(0, -1);
    const lastSpin = spinHistory[spinHistory.length - 1];
    const secondLastSpin = spinHistory.length > 1 ? spinHistory[spinHistory.length - 2] : null;
    setSpinHistory(newHistory);
    setAlerts(currentAlerts => currentAlerts.filter(alert => {
        const { trigger } = alert;
        if (trigger.length === 1 && trigger[0] === lastSpin) return false;
        if (trigger.length === 2 && secondLastSpin !== null && trigger[0] === secondLastSpin && trigger[1] === lastSpin) return false;
        return true;
    }));
  }, [spinHistory]);

  const handleRemoveAlert = (id: number) => setAlerts(currentAlerts => currentAlerts.filter(alert => alert.id !== id));

  const handleClearSession = () => {
    setSpinHistory([]);
    setAlerts([]);
    localStorage.removeItem(SESSION_STORAGE_KEY);
    setShowClearConfirmation(false);
  };

  const handleRestoreSession = useCallback(() => {
    if (savedSession) {
        setSpinHistory(savedSession.history);
        setAlerts(savedSession.alerts);
    }
    setShowRestoreConfirmation(false);
  }, [savedSession]);

  const handleStartNewSession = () => {
      localStorage.removeItem(SESSION_STORAGE_KEY);
      setSpinHistory([]);
      setAlerts([]);
      setShowRestoreConfirmation(false);
  };

  const prediction = useMemo<SeriesType | null>(() => {
    if (spinHistory.length < 4) return null;
    const seriesHistory = spinHistory.map(getSeriesType);
    if (seriesHistory.length < 3) return null;
    const triggerPattern = seriesHistory.slice(-3);

    for (let i = seriesHistory.length - 4; i >= 0; i--) {
        const historicalPattern = seriesHistory.slice(i, i + 3);
        if (historicalPattern.every((val, index) => val === triggerPattern[index])) {
            const prediction = seriesHistory[i + 3];
            return prediction === 'none' ? null : prediction;
        }
    }
    return null;
  }, [spinHistory]);

  return (
    <div className="min-h-screen text-gray-800 dark:text-gray-200 font-sans selection:bg-gold/30">
      <header className="bg-white/80 dark:bg-gray-900/80 backdrop-blur-sm sticky top-0 z-20 shadow-md">
        <div className="container mx-auto px-4 py-3 flex justify-between items-center">
          <h1 className="text-xl md:text-2xl font-bold text-gray-900 dark:text-white" style={{fontFamily: "'Playfair Display', serif"}}>
            Roulette <span className="text-gold">Pattern Tracker</span>
          </h1>
          <div className="flex items-center space-x-2 sm:space-x-4">
            <button 
              type="button" 
              onClick={() => setCurrentPage(currentPage === 'main' ? 'vip' : 'main')} 
              title="VIP Dashboard" 
              className="p-1.5 sm:p-2 rounded-lg text-gold hover:bg-gray-200 dark:hover:bg-gray-700 transition-colors flex items-center space-x-1 border border-gold/20"
            >
              <CrownIcon />
              <span className="text-[10px] sm:text-xs font-black uppercase tracking-tighter">VIP Dashboard</span>
            </button>
            <button onClick={toggleTheme} className="p-2 rounded-full text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-700">
              {theme === 'light' ? <MoonIcon /> : <SunIcon />}
            </button>
          </div>
        </div>
      </header>

      <main className="container mx-auto p-4 max-w-5xl">
        {currentPage === 'main' ? (
          <div className="flex flex-col gap-4">
            <div className="w-full bg-white dark:bg-gray-800 p-4 rounded-lg shadow-lg border border-gray-200 dark:border-gray-700">
                <h2 className="text-lg font-semibold mb-3 text-gray-700 dark:text-gray-300">Enter Spin</h2>
                <NumberGrid onNumberSelect={handleAddSpin} disabled={false} />
            </div>

            <div className="bg-white dark:bg-gray-800 p-4 rounded-lg shadow-lg border border-gray-200 dark:border-gray-700">
                <div className="flex justify-between items-center gap-x-4 mb-3">
                    <h2 className="text-sm font-semibold text-gray-700 dark:text-gray-300 whitespace-nowrap">Neighbour Number Strategy</h2>
                    <div className="flex flex-wrap items-center justify-end gap-x-2 sm:gap-x-3 gap-y-2">
                        <button id="strategy-toggle" onClick={() => setIsStrategyEnabled(!isStrategyEnabled)} className={`relative inline-flex items-center h-5 rounded-full w-9 transition-colors flex-shrink-0 ${isStrategyEnabled ? 'bg-roulette-green' : 'bg-gray-400 dark:bg-gray-600'}`} aria-pressed={isStrategyEnabled} aria-label="Toggle betting strategy">
                            <span className={`inline-block w-3 h-3 transform bg-white rounded-full transition-transform ${isStrategyEnabled ? 'translate-x-5' : 'translate-x-1'}`} />
                        </button>
                        <div className="flex items-center gap-1">
                            <label htmlFor="unit-multiplier" className="text-xs font-medium text-gray-500 dark:text-gray-400">Unit</label>
                            <input
                                type="number"
                                id="unit-multiplier"
                                value={unitMultiplierInput}
                                onChange={(e) => {
                                    const value = e.target.value;
                                    setUnitMultiplierInput(value);
                                    const num = parseInt(value, 10);
                                    if (!isNaN(num) && num > 0) {
                                        setUnitMultiplier(num);
                                    }
                                }}
                                onBlur={(e) => {
                                    const num = parseInt(e.target.value, 10);
                                    if (isNaN(num) || num < 1) {
                                        setUnitMultiplierInput('1');
                                        setUnitMultiplier(1);
                                    }
                                }}
                                disabled={!isStrategyEnabled}
                                className="w-12 bg-gray-100 dark:bg-gray-700 rounded py-1 px-1.5 text-center font-semibold text-xs focus:ring-1 focus:ring-gold outline-none disabled:opacity-50"
                            />
                        </div>
                        <div className="flex items-center gap-1.5">
                            <span className="text-[10px] font-bold text-gray-400 dark:text-gray-500 uppercase">Range:</span>
                            <div className="flex items-center bg-gray-200 dark:bg-gray-700 rounded-md p-0.5">
                                <button 
                                    onClick={() => setNeighbourDepth(3)}
                                    disabled={!isStrategyEnabled}
                                    className={`px-2 py-0.5 text-[10px] font-black rounded transition-all ${neighbourDepth === 3 ? 'bg-gold text-black shadow-sm' : 'text-gray-500'}`}
                                >
                                    N3
                                </button>
                                <button 
                                    onClick={() => setNeighbourDepth(5)}
                                    disabled={!isStrategyEnabled}
                                    className={`px-2 py-0.5 text-[10px] font-black rounded transition-all ${neighbourDepth === 5 ? 'bg-gold text-black shadow-sm' : 'text-gray-500'}`}
                                >
                                    N5
                                </button>
                            </div>
                            <span className="text-[10px] font-bold text-gray-400 dark:text-gray-500 uppercase">Mode:</span>
                            <button 
                                onClick={() => setBetStrategyMode(m => m === '235' ? '123' : m === '123' ? '111' : '235')}
                                disabled={!isStrategyEnabled} 
                                className={`px-2 py-0.5 text-xs font-semibold rounded-md transition-colors disabled:opacity-40 flex-shrink-0 ${
                                    betStrategyMode === '235' ? 'bg-green-300 text-green-900 hover:bg-green-400 dark:bg-green-700 dark:text-green-100 dark:hover:bg-green-600' :
                                    betStrategyMode === '123' ? 'bg-yellow-300 text-yellow-900 hover:bg-yellow-400 dark:bg-yellow-700 dark:text-yellow-100 dark:hover:bg-yellow-600' :
                                    'bg-blue-300 text-blue-900 hover:bg-blue-400 dark:bg-blue-700 dark:text-blue-100 dark:hover:bg-blue-600'
                                }`}
                                title="Change Weighting Mode"
                            >
                                {betStrategyMode}
                            </button>
                        </div>
                    </div>
                </div>

                {isStrategyEnabled && (
                    <div className="animate-fade-in">
                        {spinHistory.length >= 8 ? (
                            <>
                                <div className="flex justify-end items-center gap-4 mb-3 border-t border-gray-200 dark:border-gray-700 pt-3">
                                    <div className="text-sm">
                                        <span className="font-semibold text-gray-500 dark:text-gray-400">Balance: </span>
                                        <span className={`font-bold ${balance >= 0 ? 'text-green-500' : 'text-red-500'}`}>
                                            {balance >= 0 ? '+' : ''}{balance.toLocaleString()} units
                                        </span>
                                    </div>
                                    {bettingMap.size > 0 && (
                                        <div className="text-sm font-semibold text-gray-600 dark:text-gray-400">
                                            Next Bet: <span className="text-gold font-bold text-base">{totalBaseBetUnits * unitMultiplier}</span>
                                        </div>
                                    )}
                                </div>
                                <BettingChart bettingMap={bettingMap} />
                            </>
                        ) : (
                            <div className="border-t border-gray-200 dark:border-gray-700 pt-3 mt-3">
                                <p className="text-center text-gray-500 dark:text-gray-400">
                                    Spin {8 - spinHistory.length} more time{spinHistory.length === 7 ? '' : 's'} to start strategy.
                                </p>
                            </div>
                        )}
                    </div>
                )}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mt-4">
                <div className="bg-white dark:bg-gray-800 p-4 rounded-lg shadow-lg border border-gray-200 dark:border-gray-700">
                    <div className="flex justify-between items-center mb-3">
                        <h2 className="text-lg font-semibold text-gray-700 dark:text-gray-300">Spin History ({spinHistory.length})</h2>
                        <PredictionDisplay prediction={prediction} />
                    </div>
                    {spinHistory.length > 0 ? <SpinHistory history={spinHistory} /> : <p className="text-gray-500 dark:text-gray-400 text-center py-4">No spins recorded yet.</p>}
                </div>
                <div className="bg-white dark:bg-gray-800 p-4 rounded-lg shadow-lg border border-gray-200 dark:border-gray-700">
                    <h2 className="text-lg font-semibold mb-3 text-gray-700 dark:text-gray-300">Active Alerts</h2>
                    <ToastContainer toasts={alerts} onRemoveToast={handleRemoveAlert} />
                </div>
            </div>

            <div className="bg-white dark:bg-gray-800 p-3 rounded-lg shadow-lg mt-4 border border-gray-200 dark:border-gray-700">
                <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
                    <h2 className="text-base font-semibold text-gray-700 dark:text-gray-300 sr-only md:not-sr-only">Controls</h2>
                    <div className="flex items-center justify-between bg-gray-100 dark:bg-gray-700 p-2 rounded-md flex-1 max-w-xs">
                        <label htmlFor="alerts" className="font-medium text-sm">Enable Alerts</label>
                        <button onClick={() => setAlertsEnabled(!alertsEnabled)} className={`relative inline-flex items-center h-6 rounded-full w-11 transition-colors ${alertsEnabled ? 'bg-roulette-green' : 'bg-gray-400 dark:bg-gray-600'}`}>
                            <span className={`inline-block w-4 h-4 transform bg-white rounded-full transition-transform ${alertsEnabled ? 'translate-x-6' : 'translate-x-1'}`}/>
                        </button>
                    </div>
                     <div className="grid grid-cols-2 gap-2 flex-1 max-w-xs">
                        <button onClick={handleRemoveLastSpin} disabled={spinHistory.length === 0} className="w-full bg-yellow-500 text-white font-semibold py-2 px-2 rounded-md hover:bg-yellow-600 transition-colors duration-200 flex items-center justify-center space-x-2 disabled:bg-gray-500 dark:disabled:bg-gray-600 disabled:cursor-not-allowed text-sm active:scale-95 touch-manipulation">
                            <UndoIcon />
                            <span>Remove<span className="hidden sm:inline"> Last</span></span>
                        </button>
                        <button onClick={() => setShowClearConfirmation(true)} className="w-full bg-roulette-red text-white font-semibold py-2 px-2 rounded-md hover:bg-red-700 transition-colors duration-200 flex items-center justify-center space-x-2 text-sm active:scale-95 touch-manipulation">
                            <TrashIcon />
                            <span>Clear<span className="hidden sm:inline"> Session</span></span>
                        </button>
                    </div>
                </div>
            </div>
          </div>
        ) : (
          <VipPage spinHistory={spinHistory} onBack={() => setCurrentPage('main')} prediction={prediction} />
        )}
      </main>
      <ConfirmationModal
        isOpen={showClearConfirmation}
        onClose={() => setShowClearConfirmation(false)}
        onConfirm={handleClearSession}
        title="Confirm to remove all record"
        message="This will clear all spin history and detected patterns. This action cannot be undone."
      />
      <ConfirmationModal
        isOpen={showRestoreConfirmation}
        onClose={handleStartNewSession}
        onConfirm={handleRestoreSession}
        title="Restore Previous Session?"
        message="We found a saved session. Would you like to restore your progress or start a new session?"
        confirmText="Restore"
        cancelText="New Session"
        confirmButtonClass="bg-roulette-green text-white hover:bg-green-700"
        cancelButtonClass="bg-gray-500 text-white hover:bg-gray-600"
      />
    </div>
  );
};

const SunIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 sm:h-6 sm:w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z" />
    </svg>
);
const MoonIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 sm:h-6 sm:w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z" />
    </svg>
);
const CrownIcon = () => (
  <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 sm:h-5 sm:w-5" viewBox="0 0 24 24" fill="currentColor">
    <path d="M5 16L3 5l5.5 5L12 4l3.5 6L21 5l-2 11H5zm14 3c0 .55-.45 1-1 1H6c-.55 0-1-.45-1-1v-1h14v1z"></path>
  </svg>
);
const TrashIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
        <path fillRule="evenodd" d="M9 2a1 1 0 00-.894.553L7.382 4H4a1 1 0 000 2v10a2 2 0 002 2h8a2 2 0 002-2V6a1 1 0 100-2h-3.382l-.724-1.447A1 1 0 0011 2H9zM7 8a1 1 0 012 0v6a1 1 0 11-2 0V8zm4 0a1 1 0 012 0v6a1 1 0 11-2 0V8z" clipRule="evenodd" />
    </svg>
);
const UndoIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
        <path fillRule="evenodd" d="M9.707 14.707a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414l4-4a1 1 0 011.414 1.414L7.414 9H15a1 1 0 110 2H7.414l2.293 2.293a1 1 0 010 1.414z" clipRule="evenodd" />
    </svg>
);

export default App;

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { NumberGrid } from './components/NumberGrid';
import { SpinHistory } from './components/SpinHistory';
import { BettingChart } from './components/BettingChart';
import { ToastContainer } from './components/Toast';
import { VipPage } from './components/VipPage';
import { ConfirmationModal } from './components/ConfirmationModal';
import type { ToastData, SeriesType } from './types';
import { getNeighbours, getSeriesType } from './utils/roulette';
import { PredictionDisplay } from './components/PredictionDisplay';

const MIN_SPINS_FOR_PATTERNS = 6;
const SESSION_STORAGE_KEY = 'rouletteSession';
const INPUT_THROTTLE_MS = 400;

const App: React.FC = () => {
  const [theme, setTheme] = useState<'light' | 'dark'>('dark');
  const [spinHistory, setSpinHistory] = useState<number[]>([]);
  const [alerts, setAlerts] = useState<ToastData[]>([]);
  const [alertsEnabled, setAlertsEnabled] = useState<boolean>(true);
  const [currentPage, setCurrentPage] = useState<'main' | 'vip'>('main');
  const [showClearConfirmation, setShowClearConfirmation] = useState<boolean>(false);
  const [bettingMap, setBettingMap] = useState<Map<number, number>>(new Map());
  const [balance, setBalance] = useState<number>(0);
  const [showRestoreConfirmation, setShowRestoreConfirmation] = useState<boolean>(false);
  const [savedSession, setSavedSession] = useState<{ history: number[], alerts: ToastData[] } | null>(null);

  // Throttling ref to prevent double-tap errors on mobile
  const lastInputTime = useRef<number>(0);

  // New state for betting controls
  const [isStrategyEnabled, setIsStrategyEnabled] = useState<boolean>(true);
  const [unitMultiplier, setUnitMultiplier] = useState<number>(1);
  const [unitMultiplierInput, setUnitMultiplierInput] = useState<string>('1');
  const [betStrategyMode, setBetStrategyMode] = useState<'235' | '123' | '111'>('235');
  const [neighbourDepth, setNeighbourDepth] = useState<3 | 5>(3);

  useEffect(() => {
    const savedData = localStorage.getItem(SESSION_STORAGE_KEY);
    if (savedData) {
        try {
            const parsedData = JSON.parse(savedData);
            if (Array.isArray(parsedData.history) && parsedData.history.length > 0 && Array.isArray(parsedData.alerts)) {
                setSavedSession(parsedData);
                setShowRestoreConfirmation(true);
            }
        } catch (error) {
            console.error("Failed to parse saved session:", error);
            localStorage.removeItem(SESSION_STORAGE_KEY);
        }
    }
  }, []);

  useEffect(() => {
    if (spinHistory.length > 0) {
        const sessionData = {
            history: spinHistory,
            alerts: alerts,
        };
        localStorage.setItem(SESSION_STORAGE_KEY, JSON.stringify(sessionData));
    } else {
        localStorage.removeItem(SESSION_STORAGE_KEY);
    }
  }, [spinHistory, alerts]);

  const calculateBets = useCallback((history: number[], mode: '235' | '123' | '111', depth: 3 | 5): Map<number, number> => {
    const newBettingMap = new Map<number, number>();
    const uniqueHistoryByRecency = [...new Set([...history].reverse())];

    if (uniqueHistoryByRecency.length < 2) {
      return newBettingMap;
    }

    const masterCandidatePool: number[] = [];
    uniqueHistoryByRecency.forEach(num => {
      if (num !== -1) {
        const depthVal = depth === 5 ? 2 : 1;
        masterCandidatePool.push(...getNeighbours(num, depthVal));
      }
    });

    const finalCandidates = [...new Set(masterCandidatePool)].filter(n => n !== -1);

    if (mode === '111') {
        finalCandidates.slice(0, 20).forEach(candidate => {
            newBettingMap.set(candidate, 1);
        });
        return newBettingMap;
    }

    const bet5 = new Set<number>();
    const bet3 = new Set<number>();
    const bet2 = new Set<number>();
    const alreadyBetOn = new Set<number>();

    for (const candidate of finalCandidates) {
      if (alreadyBetOn.has(candidate)) continue;
      if (bet5.size < 4) bet5.add(candidate);
      else if (bet3.size < 6) bet3.add(candidate);
      else if (bet2.size < 10) bet2.add(candidate);
      alreadyBetOn.add(candidate);
      if (bet2.size >= 10) break;
    }

    const units = mode === '235' ? [5, 3, 2] : [3, 2, 1];
    bet5.forEach(num => newBettingMap.set(num, units[0]));
    bet3.forEach(num => newBettingMap.set(num, units[1]));
    bet2.forEach(num => newBettingMap.set(num, units[2]));

    return newBettingMap;
  }, []);

  useEffect(() => {
      if (spinHistory.length > 0) {
          setBettingMap(calculateBets(spinHistory, betStrategyMode, neighbourDepth));
      } else {
          setBettingMap(new Map());
      }
  }, [spinHistory, betStrategyMode, neighbourDepth, calculateBets]);

  const totalBaseBetUnits = useMemo(() => {
    let total = 0;
    for (const unit of bettingMap.values()) {
      total += unit;
    }
    return total;
  }, [bettingMap]);

  useEffect(() => {
    if (!isStrategyEnabled) {
        setBalance(0);
        return;
    }

    let cumulativeBaseBalance = 0;
    for (let i = 8; i < spinHistory.length; i++) {
        const historySliceForBetting = spinHistory.slice(0, i);
        const winningNumber = spinHistory[i];

        const betsForThisRound = calculateBets(historySliceForBetting, betStrategyMode, neighbourDepth);
        const totalBaseBetForThisRound = (Array.from(betsForThisRound.values()) as number[]).reduce((sum, val) => sum + val, 0);

        if (totalBaseBetForThisRound > 0) {
            const betOnWinningNumber = betsForThisRound.get(winningNumber) || 0;
            const profitOrLoss = betOnWinningNumber > 0 
                ? (betOnWinningNumber * 36) - totalBaseBetForThisRound 
                : -totalBaseBetForThisRound;
            cumulativeBaseBalance += profitOrLoss;
        }
    }
    setBalance(cumulativeBaseBalance * unitMultiplier);

  }, [spinHistory, calculateBets, isStrategyEnabled, unitMultiplier, betStrategyMode, neighbourDepth]);

  useEffect(() => {
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prevTheme => (prevTheme === 'light' ? 'dark' : 'light'));
  };

  const checkForAlerts = useCallback((history: number[]): Omit<ToastData, 'id'>[] => {
    if (history.length < MIN_SPINS_FOR_PATTERNS || !alertsEnabled) return [];
    const newAlerts: Omit<ToastData, 'id'>[] = [];
    const lastSpin = history[history.length - 1];
    const predictions = new Map<string, number[]>();
    for (let i = 0; i <= history.length - 3; i++) {
      if (history[i] === lastSpin) {
        const prediction = [history[i + 1], history[i + 2]];
        predictions.set(prediction.join(','), prediction);
      }
    }
     for (let i = 0; i <= history.length - 2; i++) {
        if (history[i] === lastSpin) {
            if (history.length > i + 1 && !predictions.has(`${history[i+1]}`)) {
                 const prediction = [history[i+1]];
                 if(!Array.from(predictions.values()).some(p => p.length === 2 && p[0] === prediction[0])) {
                     predictions.set(prediction.join(','), prediction);
                 }
            }
        }
    }
    if (predictions.size > 0) newAlerts.push({ trigger: [lastSpin], predictions: Array.from(predictions.values()) });
    if (history.length > 1) {
      const lastTwoSpins = history.slice(-2);
      const twoSpinPredictions = new Map<string, number[]>();
      for (let i = 0; i <= history.length - 3; i++) {
        if (history[i] === lastTwoSpins[0] && history[i + 1] === lastTwoSpins[1]) {
          const prediction = [history[i + 2]];
          twoSpinPredictions.set(prediction.join(','), prediction);
        }
      }
      if(twoSpinPredictions.size > 0) newAlerts.push({ trigger: lastTwoSpins, predictions: Array.from(twoSpinPredictions.values()) });
    }
    return newAlerts;
  }, [alertsEnabled]);

  const handleAddSpin = useCallback((num: number) => {
    const now = Date.now();
    if (now - lastInputTime.current < INPUT_THROTTLE_MS) return;
    lastInputTime.current = now;
    if ('vibrate' in navigator) navigator.vibrate(20);
    const newHistory = [...spinHistory, num];
    setSpinHistory(newHistory);
    if (newHistory.length >= MIN_SPINS_FOR_PATTERNS) {
        const alertsFromCheck = checkForAlerts(newHistory);
        if (alertsFromCheck.length > 0) {
            const freshAlerts = alertsFromCheck.map((alert, index) => ({ ...alert, id: Date.now() + index })).reverse();
            setAlerts(currentAlerts => [...freshAlerts, ...currentAlerts].slice(0, 5));
        }
    }
  }, [spinHistory, checkForAlerts]);

  const handleRemoveLastSpin = useCallback(() => {
    if (spinHistory.length === 0) return;
    const now = Date.now();
    if (now - lastInputTime.current < INPUT_THROTTLE_MS) return;
    lastInputTime.current = now;
    const newHistory = spinHistory.slice(0, -1);
    const lastSpin = spinHistory[spinHistory.length - 1];
    const secondLastSpin = spinHistory.length > 1 ? spinHistory[spinHistory.length - 2] : null;
    setSpinHistory(newHistory);
    setAlerts(currentAlerts => currentAlerts.filter(alert => {
        const { trigger } = alert;
        if (trigger.length === 1 && trigger[0] === lastSpin) return false;
        if (trigger.length === 2 && secondLastSpin !== null && trigger[0] === secondLastSpin && trigger[1] === lastSpin) return false;
        return true;
    }));
  }, [spinHistory]);

  const handleRemoveAlert = (id: number) => setAlerts(currentAlerts => currentAlerts.filter(alert => alert.id !== id));

  const handleClearSession = () => {
    setSpinHistory([]);
    setAlerts([]);
    localStorage.removeItem(SESSION_STORAGE_KEY);
    setShowClearConfirmation(false);
  };

  const handleRestoreSession = useCallback(() => {
    if (savedSession) {
        setSpinHistory(savedSession.history);
        setAlerts(savedSession.alerts);
    }
    setShowRestoreConfirmation(false);
  }, [savedSession]);

  const handleStartNewSession = () => {
      localStorage.removeItem(SESSION_STORAGE_KEY);
      setSpinHistory([]);
      setAlerts([]);
      setShowRestoreConfirmation(false);
  };

  const prediction = useMemo<SeriesType | null>(() => {
    if (spinHistory.length < 4) return null;
    const seriesHistory = spinHistory.map(getSeriesType);
    if (seriesHistory.length < 3) return null;
    const triggerPattern = seriesHistory.slice(-3);
    for (let i = seriesHistory.length - 4; i >= 0; i--) {
        const historicalPattern = seriesHistory.slice(i, i + 3);
        if (historicalPattern.every((val, index) => val === triggerPattern[index])) {
            const prediction = seriesHistory[i + 3];
            return prediction === 'none' ? null : prediction;
        }
    }
    return null;
  }, [spinHistory]);

  return (
    <div className="min-h-screen text-gray-800 dark:text-gray-200 font-sans selection:bg-gold/30">
      <header className="bg-white/80 dark:bg-gray-900/80 backdrop-blur-sm sticky top-0 z-20 shadow-md">
        <div className="container mx-auto px-4 py-2 flex justify-between items-center">
          <h1 className="text-lg md:text-xl font-bold text-gray-900 dark:text-white" style={{fontFamily: "'Playfair Display', serif"}}>
            Roulette <span className="text-gold">Tracker</span>
          </h1>
          <div className="flex items-center space-x-2">
            <button 
              type="button" 
              onClick={() => setCurrentPage(currentPage === 'main' ? 'vip' : 'main')} 
              className="p-1.5 rounded-lg text-gold hover:bg-gray-200 dark:hover:bg-gray-700 transition-colors flex items-center space-x-1 border border-gold/20"
            >
              <CrownIcon />
              <span className="text-[10px] font-black uppercase tracking-tighter">VIP</span>
            </button>
            <button onClick={toggleTheme} className="p-1.5 rounded-full text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-700">
              {theme === 'light' ? <MoonIcon /> : <SunIcon />}
            </button>
          </div>
        </div>
      </header>

      <main className="container mx-auto px-2 py-3 max-w-5xl">
        {currentPage === 'main' ? (
          <div className="flex flex-col gap-3">
            <div className="w-full bg-white dark:bg-gray-800 p-3 rounded-lg shadow-md border border-gray-200 dark:border-gray-700">
                <NumberGrid onNumberSelect={handleAddSpin} disabled={false} />
            </div>

            <div className="bg-white dark:bg-gray-800 p-2 rounded-lg shadow-md border border-gray-200 dark:border-gray-700">
                <div className="flex flex-wrap items-center justify-between gap-1 mb-1.5">
                    <h2 className="text-[11px] font-bold text-gray-600 dark:text-gray-400 uppercase tracking-tight">Strategy</h2>
                    <div className="flex items-center gap-1.5">
                        <button onClick={() => setIsStrategyEnabled(!isStrategyEnabled)} className={`relative inline-flex items-center h-4 rounded-full w-8 transition-colors ${isStrategyEnabled ? 'bg-roulette-green' : 'bg-gray-400 dark:bg-gray-600'}`}>
                            <span className={`inline-block w-2.5 h-2.5 transform bg-white rounded-full transition-transform ${isStrategyEnabled ? 'translate-x-4.5' : 'translate-x-1'}`} />
                        </button>
                        <div className="flex items-center gap-0.5">
                            <span className="text-[10px] text-gray-500 uppercase">Unit:</span>
                            <input
                                type="number"
                                value={unitMultiplierInput}
                                onChange={(e) => {
                                    setUnitMultiplierInput(e.target.value);
                                    const num = parseInt(e.target.value, 10);
                                    if (!isNaN(num) && num > 0) setUnitMultiplier(num);
                                }}
                                onBlur={() => {
                                    const num = parseInt(unitMultiplierInput, 10);
                                    if (isNaN(num) || num < 1) { setUnitMultiplierInput('1'); setUnitMultiplier(1); }
                                }}
                                disabled={!isStrategyEnabled}
                                className="w-9 bg-gray-100 dark:bg-gray-700 rounded py-0.5 px-1 text-center font-bold text-[10px] outline-none disabled:opacity-40"
                            />
                        </div>
                        <div className="flex items-center bg-gray-200 dark:bg-gray-700 rounded p-0.5 gap-0.5">
                            <span className="text-[9px] font-bold text-gray-500 uppercase px-0.5">Rng:</span>
                            <button onClick={() => setNeighbourDepth(3)} disabled={!isStrategyEnabled} className={`px-1.5 py-0.5 text-[9px] font-black rounded ${neighbourDepth === 3 ? 'bg-gold text-black shadow-sm' : 'text-gray-500 disabled:opacity-30'}`}>N3</button>
                            <button onClick={() => setNeighbourDepth(5)} disabled={!isStrategyEnabled} className={`px-1.5 py-0.5 text-[9px] font-black rounded ${neighbourDepth === 5 ? 'bg-gold text-black shadow-sm' : 'text-gray-500 disabled:opacity-30'}`}>N5</button>
                        </div>
                        <div className="flex items-center bg-gray-200 dark:bg-gray-700 rounded p-0.5 gap-0.5">
                            <span className="text-[9px] font-bold text-gray-500 uppercase px-0.5">Mod:</span>
                            <button 
                                onClick={() => setBetStrategyMode(m => m === '235' ? '123' : m === '123' ? '111' : '235')}
                                disabled={!isStrategyEnabled} 
                                className={`px-1.5 py-0.5 text-[9px] font-bold rounded transition-colors ${
                                    betStrategyMode === '235' ? 'bg-green-500 text-white' :
                                    betStrategyMode === '123' ? 'bg-yellow-500 text-black' :
                                    'bg-blue-500 text-white'
                                } disabled:opacity-30`}
                            >
                                {betStrategyMode}
                            </button>
                        </div>
                    </div>
                </div>

                {isStrategyEnabled && (
                    <div className="animate-fade-in">
                        {spinHistory.length >= 8 ? (
                            <>
                                <div className="flex justify-between items-center mb-1.5 pt-1 border-t border-gray-200 dark:border-gray-700">
                                    <div className="text-[11px] font-bold">
                                        <span className="text-gray-500">Bal: </span>
                                        <span className={balance >= 0 ? 'text-green-500' : 'text-red-500'}>{balance >= 0 ? '+' : ''}{balance}</span>
                                    </div>
                                    {bettingMap.size > 0 && (
                                        <div className="text-[11px] font-bold text-gray-600 dark:text-gray-400">
                                            Bet: <span className="text-gold text-sm">{totalBaseBetUnits * unitMultiplier}</span>
                                        </div>
                                    )}
                                </div>
                                <BettingChart bettingMap={bettingMap} />
                            </>
                        ) : (
                            <div className="border-t border-gray-200 dark:border-gray-700 pt-1 mt-1 text-center">
                                <p className="text-[10px] text-gray-500">Need {8 - spinHistory.length} more spins.</p>
                            </div>
                        )}
                    </div>
                )}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                <div className="bg-white dark:bg-gray-800 p-3 rounded-lg shadow-md border border-gray-200 dark:border-gray-700">
                    <div className="flex justify-between items-center mb-2">
                        <h2 className="text-xs font-bold uppercase text-gray-500">History ({spinHistory.length})</h2>
                        <PredictionDisplay prediction={prediction} />
                    </div>
                    {spinHistory.length > 0 ? <SpinHistory history={spinHistory} /> : <p className="text-gray-500 text-center py-2 text-xs">No spins.</p>}
                </div>
                <div className="bg-white dark:bg-gray-800 p-3 rounded-lg shadow-md border border-gray-200 dark:border-gray-700">
                    <h2 className="text-xs font-bold uppercase text-gray-500 mb-2">Alerts</h2>
                    <ToastContainer toasts={alerts} onRemoveToast={handleRemoveAlert} />
                </div>
            </div>

            <div className="bg-white dark:bg-gray-800 p-2 rounded-lg shadow-md border border-gray-200 dark:border-gray-700">
                <div className="flex items-center justify-between gap-2">
                    <div className="flex items-center gap-2 bg-gray-100 dark:bg-gray-700 p-1.5 rounded flex-1">
                        <span className="text-[10px] font-bold uppercase">Alerts</span>
                        <button onClick={() => setAlertsEnabled(!alertsEnabled)} className={`relative inline-flex items-center h-4 rounded-full w-8 transition-colors ${alertsEnabled ? 'bg-roulette-green' : 'bg-gray-400 dark:bg-gray-600'}`}>
                            <span className={`inline-block w-2.5 h-2.5 transform bg-white rounded-full transition-transform ${alertsEnabled ? 'translate-x-4.5' : 'translate-x-1'}`}/>
                        </button>
                    </div>
                    <div className="flex gap-2 flex-1">
                        <button onClick={handleRemoveLastSpin} disabled={spinHistory.length === 0} className="flex-1 bg-yellow-500 text-white font-bold py-1.5 rounded hover:bg-yellow-600 disabled:opacity-40 text-[10px] uppercase transition-all active:scale-95">Undo</button>
                        <button onClick={() => setShowClearConfirmation(true)} className="flex-1 bg-roulette-red text-white font-bold py-1.5 rounded hover:bg-red-700 text-[10px] uppercase transition-all active:scale-95">Clear</button>
                    </div>
                </div>
            </div>
          </div>
        ) : (
          <VipPage spinHistory={spinHistory} onBack={() => setCurrentPage('main')} prediction={prediction} />
        )}
      </main>
      <ConfirmationModal
        isOpen={showClearConfirmation}
        onClose={() => setShowClearConfirmation(false)}
        onConfirm={handleClearSession}
        title="Clear Records"
        message="This will clear all history and patterns. Continue?"
      />
      <ConfirmationModal
        isOpen={showRestoreConfirmation}
        onClose={handleStartNewSession}
        onConfirm={handleRestoreSession}
        title="Restore Session?"
        message="Found a previous session. Restore it?"
        confirmText="Restore"
        cancelText="New"
      />
    </div>
  );
};

const SunIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z" />
    </svg>
);
const MoonIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z" />
    </svg>
);
const CrownIcon = () => (
  <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 24 24" fill="currentColor">
    <path d="M5 16L3 5l5.5 5L12 4l3.5 6L21 5l-2 11H5zm14 3c0 .55-.45 1-1 1H6c-.55 0-1-.45-1-1v-1h14v1z"></path>
  </svg>
);

export default App;

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { NumberGrid } from './components/NumberGrid';
import { SpinHistory } from './components/SpinHistory';
import { BettingChart } from './components/BettingChart';
import { ToastContainer } from './components/Toast';
import { VipPage } from './components/VipPage';
import { IntroductionPage } from './components/IntroductionPage';
import { ConfirmationModal } from './components/ConfirmationModal';
import type { ToastData, SeriesType } from './types';
import { getNeighbours, getSeriesType } from './utils/roulette';
import { PredictionDisplay } from './components/PredictionDisplay';

const MIN_SPINS_FOR_PATTERNS = 6;
const SESSION_STORAGE_KEY = 'rouletteSession';
const INPUT_THROTTLE_MS = 400;

type PageType = 'main' | 'vip' | 'info';

const App: React.FC = () => {
  const [theme, setTheme] = useState<'light' | 'dark'>('dark');
  const [spinHistory, setSpinHistory] = useState<number[]>([]);
  const [alerts, setAlerts] = useState<ToastData[]>([]);
  const [alertsEnabled, setAlertsEnabled] = useState<boolean>(true);
  const [currentPage, setCurrentPage] = useState<PageType>('main');
  const [showClearConfirmation, setShowClearConfirmation] = useState<boolean>(false);
  const [bettingMap, setBettingMap] = useState<Map<number, number>>(new Map());
  const [balance, setBalance] = useState<number>(0);
  const [showRestoreConfirmation, setShowRestoreConfirmation] = useState<boolean>(false);
  const [savedSession, setSavedSession] = useState<{ history: number[], alerts: ToastData[] } | null>(null);

  // Throttling ref to prevent double-tap errors on mobile
  const lastInputTime = useRef<number>(0);

  // State for betting controls
  const [isStrategyEnabled, setIsStrategyEnabled] = useState<boolean>(true);
  const [unitMultiplier, setUnitMultiplier] = useState<number>(1);
  const [unitMultiplierInput, setUnitMultiplierInput] = useState<string>('1');
  const [betStrategyMode, setBetStrategyMode] = useState<'235' | '123' | '111'>('235');
  const [neighbourDepth, setNeighbourDepth] = useState<3 | 5>(3);

  useEffect(() => {
    const savedData = localStorage.getItem(SESSION_STORAGE_KEY);
    if (savedData) {
        try {
            const parsedData = JSON.parse(savedData);
            if (Array.isArray(parsedData.history) && parsedData.history.length > 0 && Array.isArray(parsedData.alerts)) {
                setSavedSession(parsedData);
                setShowRestoreConfirmation(true);
            }
        } catch (error) {
            console.error("Failed to parse saved session:", error);
            localStorage.removeItem(SESSION_STORAGE_KEY);
        }
    }
  }, []);

  useEffect(() => {
    if (spinHistory.length > 0) {
        const sessionData = {
            history: spinHistory,
            alerts: alerts,
        };
        localStorage.setItem(SESSION_STORAGE_KEY, JSON.stringify(sessionData));
    } else {
        localStorage.removeItem(SESSION_STORAGE_KEY);
    }
  }, [spinHistory, alerts]);

  const calculateBets = useCallback((history: number[], mode: '235' | '123' | '111', depth: 3 | 5): Map<number, number> => {
    const newBettingMap = new Map<number, number>();
    const uniqueHistoryByRecency = [...new Set([...history].reverse())];

    if (uniqueHistoryByRecency.length < 2) {
      return newBettingMap;
    }

    const masterCandidatePool: number[] = [];
    uniqueHistoryByRecency.forEach(num => {
      if (num !== -1) {
        const depthVal = depth === 5 ? 2 : 1;
        masterCandidatePool.push(...getNeighbours(num, depthVal));
      }
    });

    const finalCandidates = [...new Set(masterCandidatePool)].filter(n => n !== -1);

    if (mode === '111') {
        finalCandidates.slice(0, 20).forEach(candidate => {
            newBettingMap.set(candidate, 1);
        });
        return newBettingMap;
    }

    const bet5 = new Set<number>();
    const bet3 = new Set<number>();
    const bet2 = new Set<number>();
    const alreadyBetOn = new Set<number>();

    for (const candidate of finalCandidates) {
      if (alreadyBetOn.has(candidate)) continue;
      if (bet5.size < 4) bet5.add(candidate);
      else if (bet3.size < 6) bet3.add(candidate);
      else if (bet2.size < 10) bet2.add(candidate);
      alreadyBetOn.add(candidate);
      if (bet2.size >= 10) break;
    }

    const units = mode === '235' ? [5, 3, 2] : [3, 2, 1];
    bet5.forEach(num => newBettingMap.set(num, units[0]));
    bet3.forEach(num => newBettingMap.set(num, units[1]));
    bet2.forEach(num => newBettingMap.set(num, units[2]));

    return newBettingMap;
  }, []);

  useEffect(() => {
      if (spinHistory.length > 0) {
          setBettingMap(calculateBets(spinHistory, betStrategyMode, neighbourDepth));
      } else {
          setBettingMap(new Map());
      }
  }, [spinHistory, betStrategyMode, neighbourDepth, calculateBets]);

  const totalBaseBetUnits = useMemo(() => {
    let total = 0;
    for (const unit of bettingMap.values()) {
      total += unit;
    }
    return total;
  }, [bettingMap]);

  useEffect(() => {
    if (!isStrategyEnabled) {
        setBalance(0);
        return;
    }

    let cumulativeBaseBalance = 0;
    for (let i = 8; i < spinHistory.length; i++) {
        const historySliceForBetting = spinHistory.slice(0, i);
        const winningNumber = spinHistory[i];

        const betsForThisRound = calculateBets(historySliceForBetting, betStrategyMode, neighbourDepth);
        const totalBaseBetForThisRound = (Array.from(betsForThisRound.values()) as number[]).reduce((sum, val) => sum + val, 0);

        if (totalBaseBetForThisRound > 0) {
            const betOnWinningNumber = betsForThisRound.get(winningNumber) || 0;
            const profitOrLoss = betOnWinningNumber > 0 
                ? (betOnWinningNumber * 36) - totalBaseBetForThisRound 
                : -totalBaseBetForThisRound;
            cumulativeBaseBalance += profitOrLoss;
        }
    }
    setBalance(cumulativeBaseBalance * unitMultiplier);

  }, [spinHistory, calculateBets, isStrategyEnabled, unitMultiplier, betStrategyMode, neighbourDepth]);

  useEffect(() => {
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prevTheme => (prevTheme === 'light' ? 'dark' : 'light'));
  };

  const checkForAlerts = useCallback((history: number[]): Omit<ToastData, 'id'>[] => {
    if (history.length < MIN_SPINS_FOR_PATTERNS || !alertsEnabled) return [];
    const newAlerts: Omit<ToastData, 'id'>[] = [];
    const lastSpin = history[history.length - 1];
    const predictions = new Map<string, number[]>();
    for (let i = 0; i <= history.length - 3; i++) {
      if (history[i] === lastSpin) {
        const prediction = [history[i + 1], history[i + 2]];
        predictions.set(prediction.join(','), prediction);
      }
    }
     for (let i = 0; i <= history.length - 2; i++) {
        if (history[i] === lastSpin) {
            if (history.length > i + 1 && !predictions.has(`${history[i+1]}`)) {
                 const prediction = [history[i+1]];
                 if(!Array.from(predictions.values()).some(p => p.length === 2 && p[0] === prediction[0])) {
                     predictions.set(prediction.join(','), prediction);
                 }
            }
        }
    }
    if (predictions.size > 0) newAlerts.push({ trigger: [lastSpin], predictions: Array.from(predictions.values()) });
    if (history.length > 1) {
      const lastTwoSpins = history.slice(-2);
      const twoSpinPredictions = new Map<string, number[]>();
      for (let i = 0; i <= history.length - 3; i++) {
        if (history[i] === lastTwoSpins[0] && history[i + 1] === lastTwoSpins[1]) {
          const prediction = [history[i + 2]];
          twoSpinPredictions.set(prediction.join(','), prediction);
        }
      }
      if(twoSpinPredictions.size > 0) newAlerts.push({ trigger: lastTwoSpins, predictions: Array.from(twoSpinPredictions.values()) });
    }
    return newAlerts;
  }, [alertsEnabled]);

  const handleAddSpin = useCallback((num: number) => {
    const now = Date.now();
    if (now - lastInputTime.current < INPUT_THROTTLE_MS) return;
    lastInputTime.current = now;
    if ('vibrate' in navigator) navigator.vibrate(20);
    const newHistory = [...spinHistory, num];
    setSpinHistory(newHistory);
    if (newHistory.length >= MIN_SPINS_FOR_PATTERNS) {
        const alertsFromCheck = checkForAlerts(newHistory);
        if (alertsFromCheck.length > 0) {
            const freshAlerts = alertsFromCheck.map((alert, index) => ({ ...alert, id: Date.now() + index })).reverse();
            setAlerts(currentAlerts => [...freshAlerts, ...currentAlerts].slice(0, 5));
        }
    }
  }, [spinHistory, checkForAlerts]);

  const handleRemoveLastSpin = useCallback(() => {
    if (spinHistory.length === 0) return;
    const now = Date.now();
    if (now - lastInputTime.current < INPUT_THROTTLE_MS) return;
    lastInputTime.current = now;
    const newHistory = spinHistory.slice(0, -1);
    const lastSpin = spinHistory[spinHistory.length - 1];
    const secondLastSpin = spinHistory.length > 1 ? spinHistory[spinHistory.length - 2] : null;
    setSpinHistory(newHistory);
    setAlerts(currentAlerts => currentAlerts.filter(alert => {
        const { trigger } = alert;
        if (trigger.length === 1 && trigger[0] === lastSpin) return false;
        if (trigger.length === 2 && secondLastSpin !== null && trigger[0] === secondLastSpin && trigger[1] === lastSpin) return false;
        return true;
    }));
  }, [spinHistory]);

  const handleRemoveAlert = (id: number) => setAlerts(currentAlerts => currentAlerts.filter(alert => alert.id !== id));

  const handleClearSession = () => {
    setSpinHistory([]);
    setAlerts([]);
    localStorage.removeItem(SESSION_STORAGE_KEY);
    setShowClearConfirmation(false);
  };

  const handleRestoreSession = useCallback(() => {
    if (savedSession) {
        setSpinHistory(savedSession.history);
        setAlerts(savedSession.alerts);
    }
    setShowRestoreConfirmation(false);
  }, [savedSession]);

  const handleStartNewSession = () => {
      localStorage.removeItem(SESSION_STORAGE_KEY);
      setSpinHistory([]);
      setAlerts([]);
      setShowRestoreConfirmation(false);
  };

  const prediction = useMemo<SeriesType | null>(() => {
    if (spinHistory.length < 4) return null;
    const seriesHistory = spinHistory.map(getSeriesType);
    if (seriesHistory.length < 3) return null;
    const triggerPattern = seriesHistory.slice(-3);
    for (let i = seriesHistory.length - 4; i >= 0; i--) {
        const historicalPattern = seriesHistory.slice(i, i + 3);
        if (historicalPattern.every((val, index) => val === triggerPattern[index])) {
            const prediction = seriesHistory[i + 3];
            return prediction === 'none' ? null : prediction;
        }
    }
    return null;
  }, [spinHistory]);

  return (
    <div className="min-h-screen text-gray-800 dark:text-gray-200 font-sans selection:bg-gold/30">
      <header className="bg-white/80 dark:bg-gray-900/80 backdrop-blur-sm sticky top-0 z-20 shadow-md">
        <div className="container mx-auto px-4 py-2 flex justify-between items-center">
          <h1 className="text-lg md:text-xl font-bold text-gray-900 dark:text-white" style={{fontFamily: "'Playfair Display', serif"}}>
            Roulette <span className="text-gold">Tracker</span>
          </h1>
          <div className="flex items-center space-x-2">
            <button 
              type="button" 
              onClick={() => setCurrentPage('info')} 
              className="p-1.5 rounded-lg text-gray-500 hover:text-gray-900 dark:text-gray-400 dark:hover:text-white transition-colors flex items-center justify-center border border-gray-300 dark:border-gray-700"
              title="Help & Info"
            >
              <InfoIcon />
            </button>
            <button 
              type="button" 
              onClick={() => setCurrentPage(currentPage === 'vip' ? 'main' : 'vip')} 
              className="p-1.5 rounded-lg text-gold hover:bg-gray-200 dark:hover:bg-gray-700 transition-colors flex items-center space-x-1 border border-gold/20"
            >
              <CrownIcon />
              <span className="text-[10px] font-black uppercase tracking-tighter">VIP</span>
            </button>
            <button onClick={toggleTheme} className="p-1.5 rounded-full text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-700">
              {theme === 'light' ? <MoonIcon /> : <SunIcon />}
            </button>
          </div>
        </div>
      </header>

      <main className="container mx-auto px-2 py-3 max-w-5xl">
        {currentPage === 'main' ? (
          <div className="flex flex-col gap-3">
            <div className="w-full bg-white dark:bg-gray-800 p-3 rounded-lg shadow-md border border-gray-200 dark:border-gray-700">
                <NumberGrid onNumberSelect={handleAddSpin} disabled={false} />
            </div>

            <div className="bg-white dark:bg-gray-800 p-2 rounded-lg shadow-md border border-gray-200 dark:border-gray-700">
                <div className="flex flex-wrap items-center justify-between gap-1 mb-1.5">
                    <h2 className="text-[11px] font-bold text-gray-600 dark:text-gray-400 uppercase tracking-tight">Strategy</h2>
                    <div className="flex items-center gap-1.5">
                        <button onClick={() => setIsStrategyEnabled(!isStrategyEnabled)} className={`relative inline-flex items-center h-4 rounded-full w-8 transition-colors ${isStrategyEnabled ? 'bg-roulette-green' : 'bg-gray-400 dark:bg-gray-600'}`}>
                            <span className={`inline-block w-2.5 h-2.5 transform bg-white rounded-full transition-transform ${isStrategyEnabled ? 'translate-x-4.5' : 'translate-x-1'}`} />
                        </button>
                        <div className="flex items-center gap-0.5">
                            <span className="text-[10px] text-gray-500 uppercase">Unit:</span>
                            <input
                                type="number"
                                value={unitMultiplierInput}
                                onChange={(e) => {
                                    setUnitMultiplierInput(e.target.value);
                                    const num = parseInt(e.target.value, 10);
                                    if (!isNaN(num) && num > 0) setUnitMultiplier(num);
                                }}
                                onBlur={() => {
                                    const num = parseInt(unitMultiplierInput, 10);
                                    if (isNaN(num) || num < 1) { setUnitMultiplierInput('1'); setUnitMultiplier(1); }
                                }}
                                disabled={!isStrategyEnabled}
                                className="w-9 bg-gray-100 dark:bg-gray-700 rounded py-0.5 px-1 text-center font-bold text-[10px] outline-none disabled:opacity-40"
                            />
                        </div>
                        <div className="flex items-center bg-gray-200 dark:bg-gray-700 rounded p-0.5 gap-0.5">
                            <span className="text-[9px] font-bold text-gray-500 uppercase px-0.5">Rng:</span>
                            <button onClick={() => setNeighbourDepth(3)} disabled={!isStrategyEnabled} className={`px-1.5 py-0.5 text-[9px] font-black rounded ${neighbourDepth === 3 ? 'bg-gold text-black shadow-sm' : 'text-gray-500 disabled:opacity-30'}`}>N3</button>
                            <button onClick={() => setNeighbourDepth(5)} disabled={!isStrategyEnabled} className={`px-1.5 py-0.5 text-[9px] font-black rounded ${neighbourDepth === 5 ? 'bg-gold text-black shadow-sm' : 'text-gray-500 disabled:opacity-30'}`}>N5</button>
                        </div>
                        <div className="flex items-center bg-gray-200 dark:bg-gray-700 rounded p-0.5 gap-0.5">
                            <span className="text-[9px] font-bold text-gray-500 uppercase px-0.5">Mod:</span>
                            <button 
                                onClick={() => setBetStrategyMode(m => m === '235' ? '123' : m === '123' ? '111' : '235')}
                                disabled={!isStrategyEnabled} 
                                className={`px-1.5 py-0.5 text-[9px] font-bold rounded transition-colors ${
                                    betStrategyMode === '235' ? 'bg-green-500 text-white' :
                                    betStrategyMode === '123' ? 'bg-yellow-500 text-black' :
                                    'bg-blue-500 text-white'
                                } disabled:opacity-30`}
                            >
                                {betStrategyMode}
                            </button>
                        </div>
                    </div>
                </div>

                {isStrategyEnabled && (
                    <div className="animate-fade-in">
                        {spinHistory.length >= 8 ? (
                            <>
                                <div className="flex justify-between items-center mb-1.5 pt-1 border-t border-gray-200 dark:border-gray-700">
                                    <div className="text-[11px] font-bold">
                                        <span className="text-gray-500">Bal: </span>
                                        <span className={balance >= 0 ? 'text-green-500' : 'text-red-500'}>{balance >= 0 ? '+' : ''}{balance}</span>
                                    </div>
                                    {bettingMap.size > 0 && (
                                        <div className="text-[11px] font-bold text-gray-600 dark:text-gray-400">
                                            Bet: <span className="text-gold text-sm">{totalBaseBetUnits * unitMultiplier}</span>
                                        </div>
                                    )}
                                </div>
                                <BettingChart bettingMap={bettingMap} />
                            </>
                        ) : (
                            <div className="border-t border-gray-200 dark:border-gray-700 pt-1 mt-1 text-center">
                                <p className="text-[10px] text-gray-500">Need {8 - spinHistory.length} more spins.</p>
                            </div>
                        )}
                    </div>
                )}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                <div className="bg-white dark:bg-gray-800 p-3 rounded-lg shadow-md border border-gray-200 dark:border-gray-700">
                    <div className="flex justify-between items-center mb-2">
                        <h2 className="text-xs font-bold uppercase text-gray-500">History ({spinHistory.length})</h2>
                        <PredictionDisplay prediction={prediction} />
                    </div>
                    {spinHistory.length > 0 ? <SpinHistory history={spinHistory} /> : <p className="text-gray-500 text-center py-2 text-xs">No spins.</p>}
                </div>
                <div className="bg-white dark:bg-gray-800 p-3 rounded-lg shadow-md border border-gray-200 dark:border-gray-700">
                    <h2 className="text-xs font-bold uppercase text-gray-500 mb-2">Alerts</h2>
                    <ToastContainer toasts={alerts} onRemoveToast={handleRemoveAlert} />
                </div>
            </div>

            <div className="bg-white dark:bg-gray-800 p-2 rounded-lg shadow-md border border-gray-200 dark:border-gray-700">
                <div className="flex items-center justify-between gap-2">
                    <div className="flex items-center gap-2 bg-gray-100 dark:bg-gray-700 p-1.5 rounded flex-1">
                        <span className="text-[10px] font-bold uppercase">Alerts</span>
                        <button onClick={() => setAlertsEnabled(!alertsEnabled)} className={`relative inline-flex items-center h-4 rounded-full w-8 transition-colors ${alertsEnabled ? 'bg-roulette-green' : 'bg-gray-400 dark:bg-gray-600'}`}>
                            <span className={`inline-block w-2.5 h-2.5 transform bg-white rounded-full transition-transform ${alertsEnabled ? 'translate-x-4.5' : 'translate-x-1'}`}/>
                        </button>
                    </div>
                    <div className="flex gap-2 flex-1">
                        <button onClick={handleRemoveLastSpin} disabled={spinHistory.length === 0} className="flex-1 bg-yellow-500 text-white font-bold py-1.5 rounded hover:bg-yellow-600 disabled:opacity-40 text-[10px] uppercase transition-all active:scale-95">Undo</button>
                        <button onClick={() => setShowClearConfirmation(true)} className="flex-1 bg-roulette-red text-white font-bold py-1.5 rounded hover:bg-red-700 text-[10px] uppercase transition-all active:scale-95">Clear</button>
                    </div>
                </div>
            </div>
          </div>
        ) : currentPage === 'vip' ? (
          <VipPage spinHistory={spinHistory} onBack={() => setCurrentPage('main')} prediction={prediction} />
        ) : (
          <IntroductionPage onBack={() => setCurrentPage('main')} />
        )}
      </main>
      <ConfirmationModal
        isOpen={showClearConfirmation}
        onClose={() => setShowClearConfirmation(false)}
        onConfirm={handleClearSession}
        title="Clear Records"
        message="This will clear all history and patterns. Continue?"
      />
      <ConfirmationModal
        isOpen={showRestoreConfirmation}
        onClose={handleStartNewSession}
        onConfirm={handleRestoreSession}
        title="Restore Session?"
        message="Found a previous session. Restore it?"
        confirmText="Restore"
        cancelText="New"
      />
    </div>
  );
};

const SunIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z" />
    </svg>
);
const MoonIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z" />
    </svg>
);
const CrownIcon = () => (
  <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 24 24" fill="currentColor">
    <path d="M5 16L3 5l5.5 5L12 4l3.5 6L21 5l-2 11H5zm14 3c0 .55-.45 1-1 1H6c-.55 0-1-.45-1-1v-1h14v1z"></path>
  </svg>
);
const InfoIcon = () => (
    <div className="w-4 h-4 rounded-sm border-2 border-current flex items-center justify-center font-black text-[10px]">
        i
    </div>
);

export default App;

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { NumberGrid } from './components/NumberGrid';
import { SpinHistory } from './components/SpinHistory';
import { BettingChart } from './components/BettingChart';
import { ToastContainer } from './components/Toast';
import { VipPage } from './components/VipPage';
import { IntroductionPage } from './components/IntroductionPage';
import { ConfirmationModal } from './components/ConfirmationModal';
import type { ToastData, SeriesType } from './types';
import { getNeighbours, getSeriesType } from './utils/roulette';
import { PredictionDisplay } from './components/PredictionDisplay';

const MIN_SPINS_FOR_PATTERNS = 6;
const SESSION_STORAGE_KEY = 'rouletteSession';
const INPUT_THROTTLE_MS = 400;

type PageType = 'main' | 'vip' | 'info';

const App: React.FC = () => {
  const [theme, setTheme] = useState<'light' | 'dark'>('dark');
  const [spinHistory, setSpinHistory] = useState<number[]>([]);
  const [alerts, setAlerts] = useState<ToastData[]>([]);
  const [alertsEnabled, setAlertsEnabled] = useState<boolean>(true);
  const [currentPage, setCurrentPage] = useState<PageType>('main');
  const [showClearConfirmation, setShowClearConfirmation] = useState<boolean>(false);
  const [bettingMap, setBettingMap] = useState<Map<number, number>>(new Map());
  const [balance, setBalance] = useState<number>(0);
  const [showRestoreConfirmation, setShowRestoreConfirmation] = useState<boolean>(false);
  const [savedSession, setSavedSession] = useState<{ history: number[], alerts: ToastData[] } | null>(null);

  // Throttling ref to prevent double-tap errors on mobile
  const lastInputTime = useRef<number>(0);

  // State for betting controls
  const [isStrategyEnabled, setIsStrategyEnabled] = useState<boolean>(true);
  const [unitMultiplier, setUnitMultiplier] = useState<number>(1);
  const [unitMultiplierInput, setUnitMultiplierInput] = useState<string>('1');
  const [betStrategyMode, setBetStrategyMode] = useState<'235' | '123' | '111'>('235');
  const [neighbourDepth, setNeighbourDepth] = useState<3 | 5>(3);

  useEffect(() => {
    const savedData = localStorage.getItem(SESSION_STORAGE_KEY);
    if (savedData) {
        try {
            const parsedData = JSON.parse(savedData);
            if (Array.isArray(parsedData.history) && parsedData.history.length > 0 && Array.isArray(parsedData.alerts)) {
                setSavedSession(parsedData);
                setShowRestoreConfirmation(true);
            }
        } catch (error) {
            console.error("Failed to parse saved session:", error);
            localStorage.removeItem(SESSION_STORAGE_KEY);
        }
    }
  }, []);

  useEffect(() => {
    if (spinHistory.length > 0) {
        const sessionData = {
            history: spinHistory,
            alerts: alerts,
        };
        localStorage.setItem(SESSION_STORAGE_KEY, JSON.stringify(sessionData));
    } else {
        localStorage.removeItem(SESSION_STORAGE_KEY);
    }
  }, [spinHistory, alerts]);

  const calculateBets = useCallback((history: number[], mode: '235' | '123' | '111', depth: 3 | 5): Map<number, number> => {
    const newBettingMap = new Map<number, number>();
    const uniqueHistoryByRecency = [...new Set([...history].reverse())];

    if (uniqueHistoryByRecency.length < 2) {
      return newBettingMap;
    }

    const masterCandidatePool: number[] = [];
    uniqueHistoryByRecency.forEach(num => {
      if (num !== -1) {
        const depthVal = depth === 5 ? 2 : 1;
        masterCandidatePool.push(...getNeighbours(num, depthVal));
      }
    });

    const finalCandidates = [...new Set(masterCandidatePool)].filter(n => n !== -1);

    if (mode === '111') {
        finalCandidates.slice(0, 20).forEach(candidate => {
            newBettingMap.set(candidate, 1);
        });
        return newBettingMap;
    }

    const bet5 = new Set<number>();
    const bet3 = new Set<number>();
    const bet2 = new Set<number>();
    const alreadyBetOn = new Set<number>();

    for (const candidate of finalCandidates) {
      if (alreadyBetOn.has(candidate)) continue;
      if (bet5.size < 4) bet5.add(candidate);
      else if (bet3.size < 6) bet3.add(candidate);
      else if (bet2.size < 10) bet2.add(candidate);
      alreadyBetOn.add(candidate);
      if (bet2.size >= 10) break;
    }

    const units = mode === '235' ? [5, 3, 2] : [3, 2, 1];
    bet5.forEach(num => newBettingMap.set(num, units[0]));
    bet3.forEach(num => newBettingMap.set(num, units[1]));
    bet2.forEach(num => newBettingMap.set(num, units[2]));

    return newBettingMap;
  }, []);

  useEffect(() => {
      if (spinHistory.length > 0) {
          setBettingMap(calculateBets(spinHistory, betStrategyMode, neighbourDepth));
      } else {
          setBettingMap(new Map());
      }
  }, [spinHistory, betStrategyMode, neighbourDepth, calculateBets]);

  const totalBaseBetUnits = useMemo(() => {
    let total = 0;
    for (const unit of bettingMap.values()) {
      total += unit;
    }
    return total;
  }, [bettingMap]);

  useEffect(() => {
    if (!isStrategyEnabled) {
        setBalance(0);
        return;
    }

    let cumulativeBaseBalance = 0;
    for (let i = 8; i < spinHistory.length; i++) {
        const historySliceForBetting = spinHistory.slice(0, i);
        const winningNumber = spinHistory[i];

        const betsForThisRound = calculateBets(historySliceForBetting, betStrategyMode, neighbourDepth);
        const totalBaseBetForThisRound = (Array.from(betsForThisRound.values()) as number[]).reduce((sum, val) => sum + val, 0);

        if (totalBaseBetForThisRound > 0) {
            const betOnWinningNumber = betsForThisRound.get(winningNumber) || 0;
            const profitOrLoss = betOnWinningNumber > 0 
                ? (betOnWinningNumber * 36) - totalBaseBetForThisRound 
                : -totalBaseBetForThisRound;
            cumulativeBaseBalance += profitOrLoss;
        }
    }
    setBalance(cumulativeBaseBalance * unitMultiplier);

  }, [spinHistory, calculateBets, isStrategyEnabled, unitMultiplier, betStrategyMode, neighbourDepth]);

  useEffect(() => {
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prevTheme => (prevTheme === 'light' ? 'dark' : 'light'));
  };

  const checkForAlerts = useCallback((history: number[]): Omit<ToastData, 'id'>[] => {
    if (history.length < MIN_SPINS_FOR_PATTERNS || !alertsEnabled) return [];
    const newAlerts: Omit<ToastData, 'id'>[] = [];
    const lastSpin = history[history.length - 1];
    const predictions = new Map<string, number[]>();
    for (let i = 0; i <= history.length - 3; i++) {
      if (history[i] === lastSpin) {
        const prediction = [history[i + 1], history[i + 2]];
        predictions.set(prediction.join(','), prediction);
      }
    }
     for (let i = 0; i <= history.length - 2; i++) {
        if (history[i] === lastSpin) {
            if (history.length > i + 1 && !predictions.has(`${history[i+1]}`)) {
                 const prediction = [history[i+1]];
                 if(!Array.from(predictions.values()).some(p => p.length === 2 && p[0] === prediction[0])) {
                     predictions.set(prediction.join(','), prediction);
                 }
            }
        }
    }
    if (predictions.size > 0) newAlerts.push({ trigger: [lastSpin], predictions: Array.from(predictions.values()) });
    if (history.length > 1) {
      const lastTwoSpins = history.slice(-2);
      const twoSpinPredictions = new Map<string, number[]>();
      for (let i = 0; i <= history.length - 3; i++) {
        if (history[i] === lastTwoSpins[0] && history[i + 1] === lastTwoSpins[1]) {
          const prediction = [history[i + 2]];
          twoSpinPredictions.set(prediction.join(','), prediction);
        }
      }
      if(twoSpinPredictions.size > 0) newAlerts.push({ trigger: lastTwoSpins, predictions: Array.from(twoSpinPredictions.values()) });
    }
    return newAlerts;
  }, [alertsEnabled]);

  const handleAddSpin = useCallback((num: number) => {
    const now = Date.now();
    if (now - lastInputTime.current < INPUT_THROTTLE_MS) return;
    lastInputTime.current = now;
    if ('vibrate' in navigator) navigator.vibrate(20);
    const newHistory = [...spinHistory, num];
    setSpinHistory(newHistory);
    if (newHistory.length >= MIN_SPINS_FOR_PATTERNS) {
        const alertsFromCheck = checkForAlerts(newHistory);
        if (alertsFromCheck.length > 0) {
            const freshAlerts = alertsFromCheck.map((alert, index) => ({ ...alert, id: Date.now() + index })).reverse();
            setAlerts(currentAlerts => [...freshAlerts, ...currentAlerts].slice(0, 5));
        }
    }
  }, [spinHistory, checkForAlerts]);

  const handleRemoveLastSpin = useCallback(() => {
    if (spinHistory.length === 0) return;
    const now = Date.now();
    if (now - lastInputTime.current < INPUT_THROTTLE_MS) return;
    lastInputTime.current = now;
    const newHistory = spinHistory.slice(0, -1);
    const lastSpin = spinHistory[spinHistory.length - 1];
    const secondLastSpin = spinHistory.length > 1 ? spinHistory[spinHistory.length - 2] : null;
    setSpinHistory(newHistory);
    setAlerts(currentAlerts => currentAlerts.filter(alert => {
        const { trigger } = alert;
        if (trigger.length === 1 && trigger[0] === lastSpin) return false;
        if (trigger.length === 2 && secondLastSpin !== null && trigger[0] === secondLastSpin && trigger[1] === lastSpin) return false;
        return true;
    }));
  }, [spinHistory]);

  const handleRemoveAlert = (id: number) => setAlerts(currentAlerts => currentAlerts.filter(alert => alert.id !== id));

  const handleClearSession = () => {
    setSpinHistory([]);
    setAlerts([]);
    localStorage.removeItem(SESSION_STORAGE_KEY);
    setShowClearConfirmation(false);
  };

  const handleRestoreSession = useCallback(() => {
    if (savedSession) {
        setSpinHistory(savedSession.history);
        setAlerts(savedSession.alerts);
    }
    setShowRestoreConfirmation(false);
  }, [savedSession]);

  const handleStartNewSession = () => {
      localStorage.removeItem(SESSION_STORAGE_KEY);
      setSpinHistory([]);
      setAlerts([]);
      setShowRestoreConfirmation(false);
  };

  const prediction = useMemo<SeriesType | null>(() => {
    const seriesHistory = spinHistory.map(getSeriesType);
    if (seriesHistory.length < 6) return null;
    const triggerPattern = seriesHistory.slice(-5);
    for (let i = seriesHistory.length - 6; i >= 0; i--) {
        const historicalPattern = seriesHistory.slice(i, i + 5);
        if (historicalPattern.every((val, index) => val === triggerPattern[index])) {
            const prediction = seriesHistory[i + 5];
            return prediction === 'none' ? null : prediction;
        }
    }
    return null;
  }, [spinHistory]);

  return (
    <div className="min-h-screen text-gray-800 dark:text-gray-200 font-sans selection:bg-gold/30">
      <header className="bg-white/80 dark:bg-gray-900/80 backdrop-blur-sm sticky top-0 z-20 shadow-md">
        <div className="container mx-auto px-4 py-2 flex justify-between items-center">
          <h1 className="text-lg md:text-xl font-bold text-gray-900 dark:text-white" style={{fontFamily: "'Playfair Display', serif"}}>
            Roulette <span className="text-gold">Tracker</span>
          </h1>
          <div className="flex items-center space-x-2">
            <button 
              type="button" 
              onClick={() => setCurrentPage('info')} 
              className="p-1.5 rounded-lg text-gray-500 hover:text-gray-900 dark:text-gray-400 dark:hover:text-white transition-colors flex items-center justify-center border border-gray-300 dark:border-gray-700"
              title="Help & Info"
            >
              <InfoIcon />
            </button>
            <button 
              type="button" 
              onClick={() => setCurrentPage(currentPage === 'vip' ? 'main' : 'vip')} 
              className="p-1.5 rounded-lg text-gold hover:bg-gray-200 dark:hover:bg-gray-700 transition-colors flex items-center space-x-1 border border-gold/20"
            >
              <CrownIcon />
              <span className="text-[10px] font-black uppercase tracking-tighter">VIP</span>
            </button>
            <button onClick={toggleTheme} className="p-1.5 rounded-full text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-700">
              {theme === 'light' ? <MoonIcon /> : <SunIcon />}
            </button>
          </div>
        </div>
      </header>

      <main className="container mx-auto px-2 py-3 max-w-5xl">
        {currentPage === 'main' ? (
          <div className="flex flex-col gap-3">
            <div className="w-full bg-white dark:bg-gray-800 p-3 rounded-lg shadow-md border border-gray-200 dark:border-gray-700">
                <NumberGrid onNumberSelect={handleAddSpin} disabled={false} />
            </div>

            <div className="bg-white dark:bg-gray-800 p-2 rounded-lg shadow-md border border-gray-200 dark:border-gray-700">
                <div className="flex flex-wrap items-center justify-between gap-1 mb-1.5">
                    <h2 className="text-[11px] font-bold text-gray-600 dark:text-gray-400 uppercase tracking-tight">Strategy</h2>
                    <div className="flex items-center gap-1.5">
                        <button onClick={() => setIsStrategyEnabled(!isStrategyEnabled)} className={`relative inline-flex items-center h-4 rounded-full w-8 transition-colors ${isStrategyEnabled ? 'bg-roulette-green' : 'bg-gray-400 dark:bg-gray-600'}`}>
                            <span className={`inline-block w-2.5 h-2.5 transform bg-white rounded-full transition-transform ${isStrategyEnabled ? 'translate-x-4.5' : 'translate-x-1'}`} />
                        </button>
                        <div className="flex items-center gap-0.5">
                            <span className="text-[10px] text-gray-500 uppercase">Unit:</span>
                            <input
                                type="number"
                                value={unitMultiplierInput}
                                onChange={(e) => {
                                    setUnitMultiplierInput(e.target.value);
                                    const num = parseInt(e.target.value, 10);
