type PageType = 'main' | 'vip' | 'info';

const App: React.FC = () => {
  const [theme, setTheme] = useState<'light' | 'dark'>('dark');
  const [spinHistory, setSpinHistory] = useState<number[]>([]);
  const [alerts, setAlerts] = useState<ToastData[]>([]);
