const SeriesLargeIcon: React.FC<{ series: SeriesType | null }> = ({ series }) => {
    const iconClasses = "w-12 h-12 text-gold animate-pulse";
    const containerClasses = "w-16 h-16 flex items-center justify-center bg-gray-200 dark:bg-gray-700 rounded-lg shadow-inner";

    if (!series) return (
        <div className={containerClasses}>
            <span className="text-gray-400 font-bold text-2xl">?</span>
        </div>
    );

    switch (series) {
        case 'voisins':
            return <div className={containerClasses} title="Voisins"><svg viewBox="0 0 100 85" className={iconClasses} fill="currentColor"><polygon points="50,0 100,85 0,85" /></svg></div>;
        case 'orphelins':
            return <div className={containerClasses} title="Orphelins"><div className="w-10 h-10 bg-gold rounded-sm animate-pulse"></div></div>;
        case 'tiers':
            return <div className={containerClasses} title="Tiers"><svg viewBox="0 0 100 85" className={iconClasses} fill="currentColor"><polygon points="0,0 100,0 50,85" /></svg></div>;
        default:
            return null;
    }
};

// --- SUB-COMPONENTS ---

const HotNumbers: React.FC<{ history: number[] }> = ({ history }) => {
    const hotNumbers = useMemo(() => {
        if (history.length === 0) return [];
        const counts = new Map<number, number>();
        history.forEach(num => counts.set(num, (counts.get(num) || 0) + 1));
        return Array.from(counts.entries()).sort((a, b) => b[1] - a[1]).slice(0, 5);
    }, [history]);

    if (hotNumbers.length === 0) {
        return <div className="flex items-center justify-center h-16"><p className="text-center text-gray-500 dark:text-gray-400">Spin to find hot numbers.</p></div>;
    }

    const colorClasses = {
        red: 'bg-roulette-red text-white',
        black: 'bg-roulette-black text-white',
        green: 'bg-roulette-green text-white',
    };

    return (
        <div className="flex justify-start items-start text-center gap-3 sm:gap-4 py-1">
            {hotNumbers.map(([num, count], index) => (
                <div key={num} className="flex flex-col items-center">
                    <span className="font-bold text-[10px] text-gold mb-1">#{index + 1}</span>
                    <div className={`w-7 h-7 sm:w-8 sm:h-8 rounded-full flex items-center justify-center font-bold text-xs sm:text-sm shadow-lg ${colorClasses[NUMBER_COLORS[num]]}`}>
                        {num}
                    </div>
                    <div className="mt-1 text-[10px] sm:text-xs font-semibold text-gray-700 dark:text-gray-300">{count}x</div>
                </div>
            ))}
        </div>
    );
};

// --- VIP PAGE MAIN COMPONENT ---
interface VipPageProps {
    spinHistory: number[];
    onBack: () => void;
    prediction: ComplexPrediction | null;
}

export const VipPage: React.FC<VipPageProps> = ({ spinHistory, onBack, prediction }) => {
    const trendStats = useMemo(() => {
        const stats = { offered: 0, wins: 0, losses: 0 };
        if (spinHistory.length < 6) return stats;

        const seriesHistory = spinHistory.map(getSeriesType);

        // Iterate through history to simulate predictions at each step
        for (let j = 5; j < seriesHistory.length; j++) {
            const historyBefore = seriesHistory.slice(0, j);
            const actualOutcome = seriesHistory[j];
            if (actualOutcome === 'none') continue;

            let simulatedPrediction: SeriesType | null = null;

            // Try length 5
            if (historyBefore.length >= 5) {
                const trigger5 = historyBefore.slice(-5);
                for (let i = historyBefore.length - 6; i >= 0; i--) {
                    const pattern = seriesHistory.slice(i, i + 5);
                    if (pattern.every((v, idx) => v === trigger5[idx])) {
                        const next = seriesHistory[i + 5];
                        if (next !== 'none') {
                            simulatedPrediction = next;
                            break;
                        }
                    }
                }
            }

            // Fallback to length 4 if length 5 didn't yield a prediction
            if (!simulatedPrediction && historyBefore.length >= 4) {
                const trigger4 = historyBefore.slice(-4);
                for (let i = historyBefore.length - 5; i >= 0; i--) {
                    const pattern = seriesHistory.slice(i, i + 4);
                    if (pattern.every((v, idx) => v === trigger4[idx])) {
                        const next = seriesHistory[i + 4];
                        if (next !== 'none') {
                            simulatedPrediction = next;
                            break;
                        }
                    }
                }
            }

            if (simulatedPrediction) {
                stats.offered++;
                if (simulatedPrediction === actualOutcome) {
                    stats.wins++;
                } else {
                    stats.losses++;
                }
            }
        }
        return stats;
    }, [spinHistory]);


    return (
        <div className="animate-fade-in pb-10">
            <div className="flex items-center mb-4">
                <button onClick={onBack} className="p-2 rounded-full hover:bg-gray-200 dark:hover:bg-gray-700 mr-2" aria-label="Back to main page">
                    <BackIcon />
                </button>
                <h2 className="text-xl sm:text-2xl font-bold" style={{fontFamily: "'Playfair Display', serif"}}>
                    VIP <span className="text-gold">Dashboard</span>
                </h2>
            </div>

            <div className="flex flex-col gap-4 sm:gap-6">

                {/* TOP ROW: Series Road */}
                <div className="bg-white dark:bg-gray-800 p-4 rounded-lg shadow-lg">
                    <h3 className="text-lg font-semibold text-gray-700 dark:text-gray-300 mb-2">Series Road</h3>
                    <div className="h-60 sm:h-80">
                        <SeriesTracker history={spinHistory} />
                    </div>
                </div>

                {/* MIDDLE ROW: Final Number Matrix */}
                <div className="bg-white dark:bg-gray-800 p-3 sm:p-4 rounded-lg shadow-lg">
                    <h3 className="text-lg font-semibold text-gray-700 dark:text-gray-300 mb-3">Final Number Matrix (0-9)</h3>
                    <FinalNumberMatrix history={spinHistory} />
                </div>

                {/* BOTTOM ROW: Consolidated Analysis */}
                <div className="bg-white dark:bg-gray-800 p-4 rounded-lg shadow-lg">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        {/* Left Side: Hot Numbers */}
                        <div className="md:pr-6 md:border-r md:border-gray-200 md:dark:border-gray-700">
                            <h3 className="text-lg font-semibold text-gray-700 dark:text-gray-300 mb-3">Hot Numbers Analysis</h3>
                            <HotNumbers history={spinHistory} />
                        </div>

                        {/* Right Side: Next Trend Prediction & Stats */}
                        <div className="flex flex-col">
                            <h3 className="text-lg font-semibold text-gray-700 dark:text-gray-300 mb-4">Next Trend Analysis</h3>
                            <div className="flex items-center gap-6">
                                <div className="flex flex-col items-center">
                                    <SeriesLargeIcon series={prediction?.series || null} />
                                    <span className="text-[10px] font-bold uppercase mt-2 text-gray-400">Predicted Series</span>
                                </div>
                                <div className="flex-grow grid grid-cols-3 gap-2">
                                    <div className="bg-gray-100 dark:bg-gray-700/50 p-3 rounded-md text-center border border-gray-200 dark:border-gray-600">
                                        <div className="text-xl font-black text-gold">{trendStats.offered}</div>
                                        <div className="text-[9px] font-bold uppercase text-gray-500">Offered</div>
                                    </div>
                                    <div className="bg-green-500/10 p-3 rounded-md text-center border border-green-500/20">
                                        <div className="text-xl font-black text-green-500">{trendStats.wins}</div>
                                        <div className="text-[9px] font-bold uppercase text-green-600">Wins</div>
                                    </div>
                                    <div className="bg-red-500/10 p-3 rounded-md text-center border border-red-500/20">
                                        <div className="text-xl font-black text-red-500">{trendStats.losses}</div>
                                        <div className="text-[9px] font-bold uppercase text-red-600">Losses</div>
                                    </div>
                                </div>
                            </div>
                            {spinHistory.length < 10 && (
                                <p className="text-[10px] text-gray-400 mt-4 italic">* Need 10+ spins for historical trend accuracy mapping.</p>
                            )}
                        </div>
                    </div>
                </div>

            </div>
        </div>
    );
};

