interface SeriesTrackerProps {
  history: number[];
}

const SeriesColumnIcon: React.FC<{ series: SeriesType }> = ({ series }) => {
    const baseClasses = "w-8 h-8 rounded-full flex items-center justify-center font-bold border-2";

    switch (series) {
        case 'Top':
            return <div title="Top" className={`${baseClasses} border-blue-400 bg-blue-400/20`}><svg viewBox="0 0 100 85" className="w-4 h-4 text-blue-400" fill="currentColor"><polygon points="50,0 100,85 0,85" /></svg></div>;
        case 'Middle':
            return <div title="Middle" className={`${baseClasses} border-purple-400 bg-purple-400/20`}><div className="w-4 h-4 bg-purple-400 rounded-sm"></div></div>;
        case 'Small':
            return <div title="Small" className={`${baseClasses} border-yellow-400 bg-yellow-400/20`}><svg viewBox="0 0 100 85" className="w-4 h-4 text-yellow-400" fill="currentColor"><polygon points="0,0 100,0 50,85" /></svg></div>;
        default:
            return null;
    }
};

interface HistoryItemWithStatus {
    num: number;
    status: 'correct' | 'wrong' | 'none';
}

export const SeriesTracker: React.FC<SeriesTrackerProps> = ({ history }) => {
    const scrollContainerRef = useRef<HTMLDivElement>(null);

    const columns = useMemo(() => {
        if (history.length === 0) return [];

        const seriesHistory = history.map(getSeriesType);
        const processedHistory: HistoryItemWithStatus[] = history.map((num, idx) => {
            let status: 'correct' | 'wrong' | 'none' = 'none';

            if (idx >= 6) {
                const historyBefore = seriesHistory.slice(0, idx);
                const triggerPattern = historyBefore.slice(-5);
                let predictedSeries: SeriesType | null = null;

                for (let j = idx - 6; j >= 0; j--) {
                    const historicalPattern = seriesHistory.slice(j, j + 5);
                    if (historicalPattern.every((val, index) => val === triggerPattern[index])) {
                        const pred = seriesHistory[j + 5];
                        if (pred !== 'none') {
                            predictedSeries = pred;
                        }
                        break;
                    }
                }

                if (predictedSeries) {
                    const actualSeries = seriesHistory[idx];
                    status = (predictedSeries === actualSeries) ? 'correct' : 'wrong';
                }
            }

            return { num, status };
        });

        const cols: { series: SeriesType; items: HistoryItemWithStatus[] }[] = [];
        let currentCol: { series: SeriesType; items: HistoryItemWithStatus[] } | null = null;

        for (const item of processedHistory) {
            const series = getSeriesType(item.num);
            if (series === 'none') continue;

            if (currentCol && currentCol.series === series) {
                currentCol.items.push(item);
            } else {
                currentCol = { series, items: [item] };
                cols.push(currentCol);
            }
        }
        return cols;
    }, [history]);

    useEffect(() => {
        if (scrollContainerRef.current) {
            scrollContainerRef.current.scrollLeft = scrollContainerRef.current.scrollWidth;
        }
    }, [columns]);

    if (columns.length === 0) {
        return <div className="h-full flex items-center justify-center"><p className="text-center text-gray-500 dark:text-gray-400">No series data to display.</p></div>;
    }

    return (
        <div className="flex flex-col h-full gap-2">
            <div ref={scrollContainerRef} className="flex flex-row gap-1.5 p-2 bg-gray-100 dark:bg-gray-700 rounded-md overflow-x-auto h-full w-full custom-scrollbar">
                {columns.map((col, colIndex) => (
                    <div key={colIndex} className="flex flex-col items-center gap-1 flex-shrink-0">
                        <SeriesColumnIcon series={col.series} />
                        <div className="flex flex-col gap-1 mt-1">
                            {col.items.map((item, itemIndex) => (
                                <SeriesIconDisplay 
                                    key={`${item.num}-${itemIndex}-${colIndex}`} 
                                    num={item.num} 
                                    predictionStatus={item.status}
                                />
                            ))}
                        </div>
                    </div>
                ))}
            </div>
            <div className="flex justify-center items-center gap-4 text-[10px] font-bold uppercase text-gray-400">
                <div className="flex items-center gap-1">
                    <div className="w-2 h-2 bg-blue-500 rounded-full"></div>
                    <span>Win</span>
                </div>
                <div className="flex items-center gap-1">
                    <div className="w-2 h-2 bg-yellow-400 rounded-full"></div>
                    <span>Loss</span>
                </div>
            </div>
        </div>
    );
};

