interface VipPageProps {
    spinHistory: number[];
    onBack: () => void;
    prediction: ComplexPrediction | null;
}

export const VipPage: React.FC<VipPageProps> = ({ spinHistory, onBack, prediction }) => {
    const reportStats = useMemo(() => {
        const stats = {
            color: { offered: 0, wins: 0 },
            final: { offered: 0, wins: 0 },
            series: { offered: 0, wins: 0 },
            top: { offered: 0, wins: 0 }
        };

        if (spinHistory.length < 10) return stats;

        for (let j = 8; j < spinHistory.length; j++) {
            const h = spinHistory.slice(0, j);
            const winner = spinHistory[j];
            const winnerColor = NUMBER_COLORS[winner];
            const winnerFinal = winner % 10;
            const winnerSeries = getSeriesType(winner);

            const colorHistory = h.map(n => NUMBER_COLORS[n]);
            const seriesHistory = h.map(getSeriesType);
            const lastNum = h[h.length - 1];
            const lastFinal = lastNum % 10;
            const lastSeries = seriesHistory[seriesHistory.length - 1];

            // 1. Color Logic simulation
            const colorMatches: Map<RouletteColor, number> = new Map();
            if (colorHistory.length >= 4) {
                const trigger3 = colorHistory.slice(-3);
                for (let i = 0; i <= colorHistory.length - 4; i++) {
                    if (colorHistory.slice(i, i + 3).every((c, idx) => c === trigger3[idx])) {
                        const pred = colorHistory[i + 3];
                        colorMatches.set(pred, (colorMatches.get(pred) || 0) + 15);
                    }
                }
            }
            const sortedColors = Array.from(colorMatches.entries()).sort((a, b) => b[1] - a[1]);
            const predColor = sortedColors.length > 0 ? sortedColors[0][0] : null;
            if (predColor) {
                stats.color.offered++;
                if (predColor === winnerColor) stats.color.wins++;
            }

            // 2. Final Digit simulation
            const digitCounts: Map<number, number> = new Map();
            for (let i = 0; i < h.length - 1; i++) {
                if (h[i] % 10 === lastFinal) {
                    const nextDigit = h[i + 1] % 10;
                    digitCounts.set(nextDigit, (digitCounts.get(nextDigit) || 0) + 1);
                }
            }
            const predFinals = Array.from(digitCounts.entries())
                .filter(([_, count]) => count >= 2)
                .sort((a, b) => b[1] - a[1])
                .slice(0, 3)
                .map(([digit]) => digit);

            if (predFinals.length > 0) {
                stats.final.offered++;
                if (predFinals.includes(winnerFinal)) stats.final.wins++;
            }

            // 3. Series simulation
            const seriesVotes: Map<SeriesType, number> = new Map();
            seriesHistory.slice(-12).forEach(s => { if (s !== 'none') seriesVotes.set(s, (seriesVotes.get(s) || 0) + 1); });
            for (let i = 0; i < seriesHistory.length - 1; i++) {
                if (seriesHistory[i] === lastSeries) {
                    const next = seriesHistory[i + 1];
                    if (next !== 'none') seriesVotes.set(next, (seriesVotes.get(next) || 0) + 2);
                }
            }
            const sortedSeries = Array.from(seriesVotes.entries()).sort((a, b) => b[1] - a[1]);
            const predSeries = sortedSeries.length > 0 ? sortedSeries[0][0] : null;
            if (predSeries && predSeries !== 'none') {
                stats.series.offered++;
                if (predSeries === winnerSeries) stats.series.wins++;
            }

            // 4. Top Numbers simulation
            const scores: Map<number, number> = new Map();
            ROULETTE_NUMBERS.forEach(n => {
                let s = 0;
                if (predColor && NUMBER_COLORS[n] === predColor) s += 12;
                if (predFinals.includes(n % 10)) s += 14;
                if (predSeries && getSeriesType(n) === predSeries) s += 15;
                const lastTwo = h.slice(-2);
                for (let k = 0; k <= h.length - 3; k++) {
                    if (h[k] === lastTwo[0] && h[k+1] === lastTwo[1] && h[k+2] === n) s += 30;
                }
                scores.set(n, s);
            });
            const predTops = Array.from(scores.entries())
                .sort((a, b) => b[1] - a[1])
                .slice(0, 3)
                .map(([num]) => num);

            stats.top.offered++;
            if (predTops.includes(winner)) stats.top.wins++;
        }
        return stats;
    }, [spinHistory]);

    return (
        <div className="animate-fade-in pb-10">
            <div className="flex items-center mb-4">
                <button onClick={onBack} className="p-2 rounded-full hover:bg-gray-200 dark:hover:bg-gray-700 mr-2" aria-label="Back to main page">
                    <BackIcon />
                </button>
                <h2 className="text-xl sm:text-2xl font-bold" style={{fontFamily: "'Playfair Display', serif"}}>
                    VIP <span className="text-gold">Dashboard</span>
                </h2>
            </div>

            <div className="flex flex-col gap-4 sm:gap-6">

                <div className="bg-white dark:bg-gray-800 p-4 rounded-lg shadow-lg">
                    <h3 className="text-lg font-semibold text-gray-700 dark:text-gray-300 mb-2">Series Road</h3>
                    <div className="h-60 sm:h-80">
                        <SeriesTracker history={spinHistory} />
                    </div>
                </div>

                <div className="bg-white dark:bg-gray-800 p-3 sm:p-4 rounded-lg shadow-lg">
                    <h3 className="text-lg font-semibold text-gray-700 dark:text-gray-300 mb-3">Final Number Matrix (0-9)</h3>
                    <FinalNumberMatrix history={spinHistory} />
                </div>

                <div className="bg-white dark:bg-gray-800 p-4 rounded-lg shadow-lg">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div className="md:pr-6 md:border-r md:border-gray-200 md:dark:border-gray-700">
                            <h3 className="text-lg font-semibold text-gray-700 dark:text-gray-300 mb-3">Hot Numbers Analysis</h3>
                            <HotNumbers history={spinHistory} />
                        </div>

                        <div className="flex flex-col">
                            <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-widest mb-3 flex items-center gap-2">
                                Prediction Accuracy Report
                                <div className="h-[1px] flex-1 bg-gray-100 dark:bg-gray-700"></div>
                            </h3>

                            <div className="grid grid-cols-2 gap-2">
                                <StatReportCard label="Color" wins={reportStats.color.wins} total={reportStats.color.offered} />
                                <StatReportCard label="Final" wins={reportStats.final.wins} total={reportStats.final.offered} />
                                <StatReportCard label="Series" wins={reportStats.series.wins} total={reportStats.series.offered} />
                                <StatReportCard label="Top Numbers" wins={reportStats.top.wins} total={reportStats.top.offered} />
                            </div>

                            {spinHistory.length < 10 && (
                                <div className="mt-4 bg-gray-50 dark:bg-gray-900/50 p-2 rounded border border-dashed border-gray-200 dark:border-gray-700">
                                    <p className="text-[10px] text-gray-400 italic text-center">
                                        Analyzing patterns... accuracy data activates after 10 spins.
                                    </p>
                                </div>
                            )}
                        </div>
                    </div>
                </div>

            </div>
        </div>
    );
};

