const CACHE_NAME = 'roulette-tracker-v2';
const ASSETS_TO_CACHE = [
  '/',
  '/index.html',
  '/index.tsx',
  '/manifest.json',
  'https://cdn.tailwindcss.com',
  'https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Playfair+Display:wght@700&display=swap',
  // Pre-cache CDN imports from importmap
  'https://aistudiocdn.com/react@^19.2.0',
  'https://aistudiocdn.com/react-dom@^19.2.0/',
  'https://aistudiocdn.com/recharts@^3.3.0'
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) => {
      return cache.addAll(ASSETS_TO_CACHE);
    })
  );
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((cacheNames) => {
      return Promise.all(
        cacheNames.map((cacheName) => {
          if (cacheName !== CACHE_NAME) {
            return caches.delete(cacheName);
          }
        })
      );
    })
  );
  self.clients.claim();
});

self.addEventListener('fetch', (event) => {
  // Strategy: Cache First, then Network
  event.respondWith(
    caches.match(event.request).then((response) => {
      if (response) {
        return response;
      }
      return fetch(event.request).then((networkResponse) => {
        // Only cache successful GET requests
        if (networkResponse.ok && event.request.method === 'GET') {
          const responseToCache = networkResponse.clone();
          caches.open(CACHE_NAME).then((cache) => {
            cache.put(event.request, responseToCache);
          });
        }
        return networkResponse;
      });
    }).catch(() => {
      // Offline fallback
      if (event.request.mode === 'navigate') {
        return caches.match('/index.html');
      }
    })
  );
});

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { NumberGrid } from './components/NumberGrid';
import { SpinHistory } from './components/SpinHistory';
import { BettingChart } from './components/BettingChart';
import { ToastContainer } from './components/Toast';
import { VipPage } from './components/VipPage';
import { IntroductionPage } from './components/IntroductionPage';
import { ConfirmationModal } from './components/ConfirmationModal';
import type { ToastData, SeriesType, ComplexPrediction, RouletteColor } from './types';
import { getNeighbours, getSeriesType } from './utils/roulette';
import { PredictionDisplay } from './components/PredictionDisplay';
import { NUMBER_COLORS, ROULETTE_NUMBERS } from './constants';

const MIN_SPINS_FOR_PATTERNS = 6;
const SESSION_STORAGE_KEY = 'rouletteSession_v2';
const INPUT_THROTTLE_MS = 400;

type PageType = 'main' | 'vip' | 'info';

const App: React.FC = () => {
  const [theme, setTheme] = useState<'light' | 'dark'>('dark');
  const [spinHistory, setSpinHistory] = useState<number[]>([]);
  const [alerts, setAlerts] = useState<ToastData[]>([]);
  const [alertsEnabled, setAlertsEnabled] = useState<boolean>(true);
  const [currentPage, setCurrentPage] = useState<PageType>('main');
  const [showClearConfirmation, setShowClearConfirmation] = useState<boolean>(false);
  const [bettingMap, setBettingMap] = useState<Map<number, number>>(new Map());
  const [balance, setBalance] = useState<number>(0);

  const lastInputTime = useRef<number>(0);

  const [isStrategyEnabled, setIsStrategyEnabled] = useState<boolean>(true);
  const [unitMultiplier, setUnitMultiplier] = useState<number>(1);
  const [unitMultiplierInput, setUnitMultiplierInput] = useState<string>('1');
  const [betStrategyMode, setBetStrategyMode] = useState<'235' | '123' | '111'>('235');
  const [neighbourDepth, setNeighbourDepth] = useState<3 | 5>(3);

  // Native-style Haptics
  const triggerHaptic = (type: 'light' | 'medium' | 'heavy' | 'error') => {
    if (!('vibrate' in navigator)) return;
    switch (type) {
      case 'light': navigator.vibrate(10); break;
      case 'medium': navigator.vibrate(25); break;
      case 'heavy': navigator.vibrate(50); break;
      case 'error': navigator.vibrate([40, 30, 40]); break;
    }
  };

  useEffect(() => {
    const savedData = localStorage.getItem(SESSION_STORAGE_KEY);
    if (savedData) {
        try {
            const parsed = JSON.parse(savedData);
            if (parsed.history) setSpinHistory(parsed.history);
            if (parsed.alerts) setAlerts(parsed.alerts);
            if (parsed.multiplier) {
                setUnitMultiplier(parsed.multiplier);
                setUnitMultiplierInput(parsed.multiplier.toString());
            }
            if (parsed.strategyMode) setBetStrategyMode(parsed.strategyMode);
            if (parsed.depth) setNeighbourDepth(parsed.depth);
            if (parsed.strategyEnabled !== undefined) setIsStrategyEnabled(parsed.strategyEnabled);
            if (parsed.theme) setTheme(parsed.theme);
        } catch (error) {
            console.error("Failed to restore session:", error);
        }
    }
  }, []);

  useEffect(() => {
    const sessionData = {
        history: spinHistory,
        alerts: alerts,
        multiplier: unitMultiplier,
        strategyMode: betStrategyMode,
        depth: neighbourDepth,
        strategyEnabled: isStrategyEnabled,
        theme: theme
    };
    localStorage.setItem(SESSION_STORAGE_KEY, JSON.stringify(sessionData));
  }, [spinHistory, alerts, unitMultiplier, betStrategyMode, neighbourDepth, isStrategyEnabled, theme]);

  const calculateBets = useCallback((history: number[], mode: '235' | '123' | '111', depth: 3 | 5): Map<number, number> => {
    const newBettingMap = new Map<number, number>();
    const uniqueHistoryByRecency = [...new Set([...history].reverse())];
    if (uniqueHistoryByRecency.length < 2) return newBettingMap;
    const masterCandidatePool: number[] = [];
    uniqueHistoryByRecency.forEach(num => {
      if (num !== -1) {
        const depthVal = depth === 5 ? 2 : 1;
        masterCandidatePool.push(...getNeighbours(num, depthVal));
      }
    });
    const finalCandidates = [...new Set(masterCandidatePool)].filter(n => n !== -1);
    if (mode === '111') {
        finalCandidates.slice(0, 20).forEach(candidate => newBettingMap.set(candidate, 1));
        return newBettingMap;
    }
    const bet5 = new Set<number>();
    const bet3 = new Set<number>();
    const bet2 = new Set<number>();
    const alreadyBetOn = new Set<number>();
    for (const candidate of finalCandidates) {
      if (alreadyBetOn.has(candidate)) continue;
      if (bet5.size < 4) bet5.add(candidate);
      else if (bet3.size < 6) bet3.add(candidate);
      else if (bet2.size < 10) bet2.add(candidate);
      alreadyBetOn.add(candidate);
      if (bet2.size >= 10) break;
    }
    const units = mode === '235' ? [5, 3, 2] : [3, 2, 1];
    bet5.forEach(num => newBettingMap.set(num, units[0]));
    bet3.forEach(num => newBettingMap.set(num, units[1]));
    bet2.forEach(num => newBettingMap.set(num, units[2]));
    return newBettingMap;
  }, []);

  useEffect(() => {
      if (spinHistory.length > 0) {
          setBettingMap(calculateBets(spinHistory, betStrategyMode, neighbourDepth));
      } else {
          setBettingMap(new Map());
      }
  }, [spinHistory, betStrategyMode, neighbourDepth, calculateBets]);

  const totalBaseBetUnits = useMemo(() => {
    let total = 0;
    for (const unit of bettingMap.values()) total += unit;
    return total;
  }, [bettingMap]);

  useEffect(() => {
    if (!isStrategyEnabled) {
        setBalance(0);
        return;
    }
    let cumulativeBaseBalance = 0;
    for (let i = 8; i < spinHistory.length; i++) {
        const historySliceForBetting = spinHistory.slice(0, i);
        const winningNumber = spinHistory[i];
        const betsForThisRound = calculateBets(historySliceForBetting, betStrategyMode, neighbourDepth);
        const totalBaseBetForThisRound = (Array.from(betsForThisRound.values()) as number[]).reduce((sum, val) => sum + val, 0);
        if (totalBaseBetForThisRound > 0) {
            const betOnWinningNumber = betsForThisRound.get(winningNumber) || 0;
            const profitOrLoss = betOnWinningNumber > 0 
                ? (betOnWinningNumber * 36) - totalBaseBetForThisRound 
                : -totalBaseBetForThisRound;
            cumulativeBaseBalance += profitOrLoss;
        }
    }
    setBalance(cumulativeBaseBalance * unitMultiplier);
  }, [spinHistory, calculateBets, isStrategyEnabled, unitMultiplier, betStrategyMode, neighbourDepth]);

  useEffect(() => {
    if (theme === 'dark') document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
  }, [theme]);

  const toggleTheme = () => {
    triggerHaptic('light');
    setTheme(prevTheme => (prevTheme === 'light' ? 'dark' : 'light'));
  };

  const checkForAlerts = useCallback((history: number[]): Omit<ToastData, 'id'>[] => {
    if (history.length < MIN_SPINS_FOR_PATTERNS || !alertsEnabled) return [];
    const newAlerts: Omit<ToastData, 'id'>[] = [];
    const lastSpin = history[history.length - 1];
    const predictions = new Map<string, number[]>();
    for (let i = 0; i <= history.length - 3; i++) {
      if (history[i] === lastSpin) {
        const prediction = [history[i + 1], history[i + 2]];
        predictions.set(prediction.join(','), prediction);
      }
    }
     for (let i = 0; i <= history.length - 2; i++) {
        if (history[i] === lastSpin) {
            if (history.length > i + 1 && !predictions.has(`${history[i+1]}`)) {
                 const prediction = [history[i+1]];
                 if(!Array.from(predictions.values()).some(p => p.length === 2 && p[0] === prediction[0])) {
                     predictions.set(prediction.join(','), prediction);
                 }
            }
        }
    }
    if (predictions.size > 0) newAlerts.push({ trigger: [lastSpin], predictions: Array.from(predictions.values()) });
    if (history.length > 1) {
      const lastTwoSpins = history.slice(-2);
      const twoSpinPredictions = new Map<string, number[]>();
      for (let i = 0; i <= history.length - 3; i++) {
        if (history[i] === lastTwoSpins[0] && history[i + 1] === lastTwoSpins[1]) {
          const prediction = [history[i + 2]];
          twoSpinPredictions.set(prediction.join(','), prediction);
        }
      }
      if(twoSpinPredictions.size > 0) newAlerts.push({ trigger: lastTwoSpins, predictions: Array.from(twoSpinPredictions.values()) });
    }
    return newAlerts;
  }, [alertsEnabled]);

  const handleAddSpin = useCallback((num: number) => {
    const now = Date.now();
    if (now - lastInputTime.current < INPUT_THROTTLE_MS) return;
    lastInputTime.current = now;
    triggerHaptic('medium');
    const newHistory = [...spinHistory, num];
    setSpinHistory(newHistory);
    if (newHistory.length >= MIN_SPINS_FOR_PATTERNS) {
        const alertsFromCheck = checkForAlerts(newHistory);
        if (alertsFromCheck.length > 0) {
            const freshAlerts = alertsFromCheck.map((alert, index) => ({ ...alert, id: Date.now() + index })).reverse();
            setAlerts(currentAlerts => [...freshAlerts, ...currentAlerts].slice(0, 5));
        }
    }
  }, [spinHistory, checkForAlerts]);

  const handleRemoveLastSpin = useCallback(() => {
    if (spinHistory.length === 0) return;
    const now = Date.now();
    if (now - lastInputTime.current < INPUT_THROTTLE_MS) return;
    lastInputTime.current = now;
    triggerHaptic('light');
    const newHistory = spinHistory.slice(0, -1);
    setSpinHistory(newHistory);
    setAlerts(currentAlerts => currentAlerts.filter(alert => {
        const lastSpin = spinHistory[spinHistory.length - 1];
        const trigger = alert.trigger;
        if (trigger.length === 1 && trigger[0] === lastSpin) return false;
        if (trigger.length === 2 && trigger[1] === lastSpin) return false;
        return true;
    }));
  }, [spinHistory]);

  const handleRemoveAlert = (id: number) => {
    triggerHaptic('light');
    setAlerts(currentAlerts => currentAlerts.filter(alert => alert.id !== id));
  };

  const handleClearSession = () => {
    triggerHaptic('error');
    setSpinHistory([]);
    setAlerts([]);
    localStorage.removeItem(SESSION_STORAGE_KEY);
    setShowClearConfirmation(false);
  };

  const prediction = useMemo<ComplexPrediction | null>(() => {
    if (spinHistory.length < 5) return null;
    const seriesHistory = spinHistory.map(getSeriesType);
    const colorHistory = spinHistory.map(n => NUMBER_COLORS[n]);
    const lastNumber = spinHistory[spinHistory.length - 1];
    const lastFinalDigit = lastNumber % 10;
    const lastSeries = seriesHistory[seriesHistory.length - 1];
    const scores: Map<number, number> = new Map();
    ROULETTE_NUMBERS.forEach(n => scores.set(n, 0));
    const colorMatches: Map<RouletteColor, number> = new Map();
    if (colorHistory.length >= 4) {
        const trigger3 = colorHistory.slice(-3);
        for (let i = 0; i <= colorHistory.length - 4; i++) {
            if (colorHistory.slice(i, i + 3).every((c, idx) => c === trigger3[idx])) {
                const pred = colorHistory[i + 3];
                colorMatches.set(pred, (colorMatches.get(pred) || 0) + 15);
            }
        }
    }
    if (colorHistory.length >= 5) {
        const trigger4 = colorHistory.slice(-4);
        for (let i = 0; i <= colorHistory.length - 5; i++) {
            if (colorHistory.slice(i, i + 4).every((c, idx) => c === trigger4[idx])) {
                const pred = colorHistory[i + 4];
                colorMatches.set(pred, (colorMatches.get(pred) || 0) + 10);
            }
        }
    }
    if (colorHistory.length >= 7) {
        const trigger6 = colorHistory.slice(-6);
        for (let i = 0; i <= colorHistory.length - 7; i++) {
            if (colorHistory.slice(i, i + 6).every((c, idx) => c === trigger6[idx])) {
                const pred = colorHistory[i + 6];
                colorMatches.set(pred, (colorMatches.get(pred) || 0) + 5);
            }
        }
    }
    const last4 = colorHistory.slice(-4);
    const redsInLast4 = last4.filter(c => c === 'red').length;
    const blacksInLast4 = last4.filter(c => c === 'black').length;
    if (redsInLast4 >= 3) colorMatches.set('red', (colorMatches.get('red') || 0) + 8);
    if (blacksInLast4 >= 3) colorMatches.set('black', (colorMatches.get('black') || 0) + 8);
    let likelyColor: RouletteColor | null = null;
    const sortedColors = Array.from(colorMatches.entries()).sort((a, b) => b[1] - a[1]);
    if (sortedColors.length > 0) likelyColor = sortedColors[0][0];
    if (likelyColor) {
        ROULETTE_NUMBERS.forEach(n => {
            if (NUMBER_COLORS[n] === likelyColor) scores.set(n, (scores.get(n) || 0) + 12);
        });
    }
    const digitCounts: Map<number, number> = new Map();
    for (let i = 0; i < spinHistory.length - 1; i++) {
        if (spinHistory[i] % 10 === lastFinalDigit) {
            const nextDigit = spinHistory[i + 1] % 10;
            digitCounts.set(nextDigit, (digitCounts.get(nextDigit) || 0) + 1);
        }
    }
    const eligibleDigits = Array.from(digitCounts.entries())
        .filter(([_, count]) => count >= 2)
        .sort((a, b) => b[1] - a[1]);
    const predictedFinalDigits: number[] = [];
    if (eligibleDigits.length > 0) {
        eligibleDigits.slice(0, 3).forEach(([digit]) => {
            predictedFinalDigits.push(digit);
        });
    }
    if (predictedFinalDigits.length > 0) {
        ROULETTE_NUMBERS.forEach(n => {
            if (predictedFinalDigits.includes(n % 10)) {
                scores.set(n, (scores.get(n) || 0) + 14);
            }
        });
    }
    const seriesVotes: Map<SeriesType, number> = new Map();
    seriesHistory.slice(-12).forEach(s => {
        if (s !== 'none') seriesVotes.set(s, (seriesVotes.get(s) || 0) + 1);
    });
    for (let i = 0; i < seriesHistory.length - 1; i++) {
        if (seriesHistory[i] === lastSeries) {
            const next = seriesHistory[i + 1];
            if (next !== 'none') seriesVotes.set(next, (seriesVotes.get(next) || 0) + 2);
        }
    }
    if (seriesHistory.length >= 6) {
        const triggerSeries5 = seriesHistory.slice(-5);
        for (let i = 0; i <= seriesHistory.length - 6; i++) {
            if (seriesHistory.slice(i, i + 5).every((s, idx) => s === triggerSeries5[idx])) {
                const pred = seriesHistory[i + 5];
                if (pred !== 'none') seriesVotes.set(pred, (seriesVotes.get(pred) || 0) + 8);
            }
        }
    }
    let predictedSeries: SeriesType | null = null;
    const sortedSeries = Array.from(seriesVotes.entries()).sort((a, b) => b[1] - a[1]);
    if (sortedSeries.length > 0) predictedSeries = sortedSeries[0][0];
    if (predictedSeries) {
        ROULETTE_NUMBERS.forEach(n => {
            if (getSeriesType(n) === predictedSeries) scores.set(n, (scores.get(n) || 0) + 15);
        });
    }
    const lastTwo = spinHistory.slice(-2);
    for (let i = 0; i <= spinHistory.length - 3; i++) {
        if (spinHistory[i] === lastTwo[0] && spinHistory[i + 1] === lastTwo[1]) {
            const next = spinHistory[i + 2];
            scores.set(next, (scores.get(next) || 0) + 30);
        }
    }
    const finalTopNumbers = Array.from(scores.entries())
        .sort((a, b) => b[1] - a[1])
        .filter(entry => entry[1] > 0)
        .slice(0, 3)
        .map(([num, score]) => ({
            num,
            confidence: Math.min(99, Math.max(10, Math.round((score / 55) * 100)))
        }));
    return {
        series: predictedSeries,
        topNumbers: finalTopNumbers,
        color: likelyColor,
        finalDigits: predictedFinalDigits
    };
  }, [spinHistory]);

  const switchPage = (page: PageType) => {
    triggerHaptic('light');
    setCurrentPage(page);
  };

  return (
    <div className="min-h-screen text-gray-800 dark:text-gray-200 font-sans selection:bg-gold/30 flex flex-col overflow-hidden">
      {/* Safe Area Header */}
      <header className="bg-white/80 dark:bg-gray-900/80 backdrop-blur-md sticky top-0 z-40 shadow-sm border-b border-gray-200 dark:border-gray-800 pt-[env(safe-area-inset-top)]">
        <div className="container mx-auto px-4 py-3 flex justify-between items-center h-14">
          <h1 className="text-lg md:text-xl font-bold text-gray-900 dark:text-white" style={{fontFamily: "'Playfair Display', serif"}}>
            Roulette <span className="text-gold">Tracker</span>
          </h1>
          <div className="flex items-center space-x-2">
            <button type="button" onClick={() => switchPage('info')} className="p-2 rounded-xl text-gray-500 hover:text-gray-900 dark:text-gray-400 dark:hover:text-white transition-all flex items-center justify-center border border-gray-200 dark:border-gray-700 active:scale-95" title="Help & Info">
              <InfoIcon />
            </button>
            <button type="button" onClick={() => switchPage(currentPage === 'vip' ? 'main' : 'vip')} className={`p-2 rounded-xl transition-all flex items-center space-x-1 border active:scale-95 ${currentPage === 'vip' ? 'bg-gold text-black border-gold' : 'text-gold border-gold/20'}`}>
              <CrownIcon />
              <span className="text-[10px] font-black uppercase tracking-tighter">VIP</span>
            </button>
            <button onClick={toggleTheme} className="p-2 rounded-xl text-gray-600 dark:text-gray-300 border border-gray-200 dark:border-gray-700 active:scale-95">
              {theme === 'light' ? <MoonIcon /> : <SunIcon />}
            </button>
          </div>
        </div>
      </header>

      {/* Main content with safe area at bottom */}
      <main className="flex-1 overflow-y-auto overflow-x-hidden custom-scrollbar pb-[env(safe-area-inset-bottom)]">
        <div className="container mx-auto px-3 py-4 max-w-5xl">
            {currentPage === 'main' ? (
            <div className="flex flex-col gap-4 animate-fade-in">
                <div className="w-full bg-white dark:bg-gray-800 p-4 rounded-2xl shadow-lg border border-gray-100 dark:border-gray-700/50">
                    <NumberGrid onNumberSelect={handleAddSpin} disabled={false} />
                </div>

                <div className="bg-white dark:bg-gray-800 p-3 rounded-2xl shadow-lg border border-gray-100 dark:border-gray-700/50">
                    <div className="flex flex-wrap items-center justify-between gap-2 mb-3 px-1">
                        <h2 className="text-[11px] font-black text-gray-500 dark:text-gray-400 uppercase tracking-widest">Strategy Dashboard</h2>
                        <div className="flex items-center gap-2">
                            <button onClick={() => setIsStrategyEnabled(!isStrategyEnabled)} className={`relative inline-flex items-center h-5 rounded-full w-10 transition-colors ${isStrategyEnabled ? 'bg-roulette-green' : 'bg-gray-400 dark:bg-gray-600'}`}>
                                <span className={`inline-block w-3.5 h-3.5 transform bg-white rounded-full transition-transform ${isStrategyEnabled ? 'translate-x-5.5' : 'translate-x-1'}`} />
                            </button>
                            <div className="flex items-center gap-1">
                                <span className="text-[10px] text-gray-400 font-bold uppercase">Unit:</span>
                                <input type="number" value={unitMultiplierInput} onChange={(e) => {
                                        setUnitMultiplierInput(e.target.value);
                                        const num = parseInt(e.target.value, 10);
                                        if (!isNaN(num) && num > 0) setUnitMultiplier(num);
                                    }} onBlur={() => {
                                        const num = parseInt(unitMultiplierInput, 10);
                                        if (isNaN(num) || num < 1) { setUnitMultiplierInput('1'); setUnitMultiplier(1); }
                                    }} disabled={!isStrategyEnabled} className="w-10 bg-gray-100 dark:bg-gray-700 rounded-lg py-1 px-1 text-center font-black text-xs outline-none disabled:opacity-40" />
                            </div>
                        </div>
                    </div>

                    <div className="flex items-center justify-between gap-2 mb-3 bg-gray-50 dark:bg-gray-900/40 p-1.5 rounded-xl border border-gray-100 dark:border-gray-700/30">
                        <div className="flex items-center gap-1 flex-1">
                            <span className="text-[9px] font-black text-gray-400 uppercase tracking-tighter px-1">Sector Range:</span>
                            <div className="flex bg-white dark:bg-gray-800 rounded-lg p-0.5 shadow-sm border border-gray-200 dark:border-gray-700">
                                <button onClick={() => {triggerHaptic('light'); setNeighbourDepth(3)}} disabled={!isStrategyEnabled} className={`px-2.5 py-1 text-[10px] font-black rounded-md transition-all ${neighbourDepth === 3 ? 'bg-gold text-black shadow-sm' : 'text-gray-500 disabled:opacity-30'}`}>N3</button>
                                <button onClick={() => {triggerHaptic('light'); setNeighbourDepth(5)}} disabled={!isStrategyEnabled} className={`px-2.5 py-1 text-[10px] font-black rounded-md transition-all ${neighbourDepth === 5 ? 'bg-gold text-black shadow-sm' : 'text-gray-500 disabled:opacity-30'}`}>N5</button>
                            </div>
                        </div>
                        <div className="flex items-center gap-1 flex-1 justify-end">
                            <span className="text-[9px] font-black text-gray-400 uppercase tracking-tighter px-1">Weighting:</span>
                            <button onClick={() => {triggerHaptic('light'); setBetStrategyMode(m => m === '235' ? '123' : m === '123' ? '111' : '235')}} disabled={!isStrategyEnabled} className={`px-2.5 py-1 text-[10px] font-black rounded-lg transition-all shadow-sm ${betStrategyMode === '235' ? 'bg-green-600 text-white' : betStrategyMode === '123' ? 'bg-yellow-500 text-black' : 'bg-blue-600 text-white'} disabled:opacity-30`}>{betStrategyMode}</button>
                        </div>
                    </div>

                    {isStrategyEnabled && (
                        <div className="animate-fade-in">
                            {spinHistory.length >= 8 ? (
                                <>
                                    <div className="flex justify-between items-center mb-3 pt-2 border-t border-gray-100 dark:border-gray-700/50">
                                        <div className="text-xs font-black">
                                            <span className="text-gray-400 uppercase tracking-tighter">Profit/Loss: </span>
                                            <span className={balance >= 0 ? 'text-green-500' : 'text-red-500'}>{balance >= 0 ? '+' : ''}{balance}</span>
                                        </div>
                                        {bettingMap.size > 0 && (
                                            <div className="text-xs font-black text-gray-500 dark:text-gray-400 uppercase tracking-tighter">
                                                Total Bet: <span className="text-gold text-base">{totalBaseBetUnits * unitMultiplier}</span>
                                            </div>
                                        )}
                                    </div>
                                    <BettingChart bettingMap={bettingMap} />
                                </>
                            ) : (
                                <div className="border-t border-gray-100 dark:border-gray-700/50 pt-4 pb-2 text-center">
                                    <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest italic animate-pulse">Waiting for more data ({8 - spinHistory.length} spins left)</p>
                                </div>
                            )}
                        </div>
                    )}
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="bg-white dark:bg-gray-800 p-4 rounded-2xl shadow-lg border border-gray-100 dark:border-gray-700/50">
                        <div className="flex justify-between items-center mb-3">
                            <h2 className="text-[11px] font-black uppercase text-gray-400 tracking-widest">Recent Spins ({spinHistory.length})</h2>
                            <PredictionDisplay prediction={prediction} />
                        </div>
                        {spinHistory.length > 0 ? <SpinHistory history={spinHistory} /> : <p className="text-gray-400 text-center py-6 text-[10px] font-black uppercase italic tracking-widest">No data collected</p>}
                    </div>
                    <div className="bg-white dark:bg-gray-800 p-4 rounded-2xl shadow-lg border border-gray-100 dark:border-gray-700/50">
                        <h2 className="text-[11px] font-black uppercase text-gray-400 tracking-widest mb-3">Pattern Alerts</h2>
                        <ToastContainer toasts={alerts} onRemoveToast={handleRemoveAlert} />
                    </div>
                </div>

                <div className="bg-white dark:bg-gray-800 p-3 rounded-2xl shadow-lg border border-gray-100 dark:border-gray-700/50 mt-2 mb-8">
                    <div className="flex items-center justify-between gap-3">
                        <div className="flex items-center gap-3 bg-gray-100 dark:bg-gray-900/50 px-4 py-2.5 rounded-xl flex-1 border border-gray-200 dark:border-gray-700/50">
                            <span className="text-[11px] font-black uppercase tracking-widest text-gray-500">Alerts</span>
                            <button onClick={() => {triggerHaptic('light'); setAlertsEnabled(!alertsEnabled)}} className={`relative inline-flex items-center h-5 rounded-full w-10 transition-colors ${alertsEnabled ? 'bg-roulette-green' : 'bg-gray-400 dark:bg-gray-600'}`}>
                                <span className={`inline-block w-3.5 h-3.5 transform bg-white rounded-full transition-transform ${alertsEnabled ? 'translate-x-5.5' : 'translate-x-1'}`}/>
                            </button>
                        </div>
                        <div className="flex gap-3 flex-1">
                            <button onClick={handleRemoveLastSpin} disabled={spinHistory.length === 0} className="flex-1 bg-yellow-500 text-black font-black py-2.5 rounded-xl hover:bg-yellow-600 disabled:opacity-40 text-[11px] uppercase tracking-widest shadow-md transition-all active:scale-95 active:shadow-inner">Undo</button>
                            <button onClick={() => {triggerHaptic('medium'); setShowClearConfirmation(true)}} className="flex-1 bg-roulette-red text-white font-black py-2.5 rounded-xl hover:bg-red-700 text-[11px] uppercase tracking-widest shadow-md transition-all active:scale-95 active:shadow-inner">Clear</button>
                        </div>
                    </div>
                </div>
            </div>
            ) : currentPage === 'vip' ? (
            <div className="animate-slide-up">
                <VipPage spinHistory={spinHistory} onBack={() => switchPage('main')} prediction={prediction} />
            </div>
            ) : (
            <div className="animate-slide-up">
                <IntroductionPage onBack={() => switchPage('main')} />
            </div>
            )}
        </div>
      </main>
      <ConfirmationModal isOpen={showClearConfirmation} onClose={() => setShowClearConfirmation(false)} onConfirm={handleClearSession} title="Clear Records" message="This will clear all history and patterns. Continue?" />
    </div>
  );
};

const SunIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z" />
    </svg>
);
const MoonIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z" />
    </svg>
);
const CrownIcon = () => (
  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 24 24" fill="currentColor">
    <path d="M5 16L3 5l5.5 5L12 4l3.5 6L21 5l-2 11H5zm14 3c0 .55-.45 1-1 1H6c-.55 0-1-.45-1-1v-1h14v1z"></path>
  </svg>
);
const InfoIcon = () => (
    <div className="w-5 h-5 rounded-lg border-2 border-current flex items-center justify-center font-black text-xs">
        ?
    </div>
);

export default App;

import React from 'react';
import { NUMBER_COLORS } from '../constants';

interface NumberGridProps {
  onNumberSelect: (num: number) => void;
  disabled: boolean;
}

const colorClasses = {
  red: 'bg-roulette-red active:bg-red-800 text-white shadow-[0_3px_0_#9a1f1f] active:shadow-none active:translate-y-[2px]',
  black: 'bg-roulette-black active:bg-gray-900 text-white shadow-[0_3px_0_#000000] active:shadow-none active:translate-y-[2px]',
  green: 'bg-roulette-green active:bg-green-800 text-white shadow-[0_3px_0_#1e5622] active:shadow-none active:translate-y-[2px]',
};

