import React, { useMemo, useRef, useEffect } from 'react';
import { getSeriesType } from '../utils/roulette';
import { SeriesIconDisplay } from './SeriesIconDisplay';
import type { SeriesType } from '../types';

interface SeriesTrackerProps {
  history: number[];
}

const SeriesColumnHeader: React.FC<{ series: SeriesType }> = ({ series }) => {
    const color = series === 'Top' ? 'text-blue-400' : series === 'Middle' ? 'text-purple-400' : 'text-yellow-400';
    const label = series === 'Top' ? 'VOIS' : series === 'Middle' ? 'ORPH' : 'TIER';

    return (
        <div className="flex flex-col items-center mb-1">
            <span className={`text-[8px] font-black uppercase tracking-tighter ${color}`}>{label}</span>
            <div className={`w-1 h-3 rounded-full ${series === 'Top' ? 'bg-blue-400' : series === 'Middle' ? 'bg-purple-400' : 'bg-yellow-400'} opacity-30`}></div>
        </div>
    );
};

interface HistoryItemWithStatus {
    num: number;
    status: 'correct' | 'wrong' | 'none';
    index: number;
}

export const SeriesTracker: React.FC<SeriesTrackerProps> = ({ history }) => {
    const scrollContainerRef = useRef<HTMLDivElement>(null);

    const columns = useMemo(() => {
        if (history.length === 0) return [];

        const seriesHistory = history.map(getSeriesType);
        const processedHistory: HistoryItemWithStatus[] = history.map((num, idx) => {
            let status: 'correct' | 'wrong' | 'none' = 'none';

            if (idx >= 6) {
                const historyBefore = seriesHistory.slice(0, idx);
                const triggerPattern = historyBefore.slice(-5);
                let predictedSeries: SeriesType | null = null;

                for (let j = idx - 6; j >= 0; j--) {
                    const historicalPattern = seriesHistory.slice(j, j + 5);
                    if (historicalPattern.every((val, index) => val === triggerPattern[index])) {
                        const pred = seriesHistory[j + 5];
                        if (pred !== 'none') {
                            predictedSeries = pred;
                        }
                        break;
                    }
                }

                if (predictedSeries) {
                    const actualSeries = seriesHistory[idx];
                    status = (predictedSeries === actualSeries) ? 'correct' : 'wrong';
                }
            }

            return { num, status, index: idx + 1 };
        });

        const cols: { series: SeriesType; items: HistoryItemWithStatus[] }[] = [];
        let currentCol: { series: SeriesType; items: HistoryItemWithStatus[] } | null = null;

        for (const item of processedHistory) {
            const series = getSeriesType(item.num);
            if (series === 'none') continue;

            if (currentCol && currentCol.series === series) {
                currentCol.items.push(item);
            } else {
                currentCol = { series, items: [item] };
                cols.push(currentCol);
            }
        }
        return cols;
    }, [history]);

    useEffect(() => {
        if (scrollContainerRef.current) {
            scrollContainerRef.current.scrollLeft = scrollContainerRef.current.scrollWidth;
        }
    }, [columns]);

    if (columns.length === 0) {
        return <div className="h-full flex flex-col items-center justify-center p-8 bg-gray-50 dark:bg-gray-900/40 rounded-3xl border-2 border-dashed border-gray-200 dark:border-gray-800">
            <div className="w-12 h-12 rounded-full bg-gray-100 dark:bg-gray-800 flex items-center justify-center mb-3">
                <svg className="w-6 h-6 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 17v-2m3 2v-4m3 4v-6m2 10H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                </svg>
            </div>
            <p className="text-center text-gray-400 font-black text-[10px] uppercase tracking-widest">Waiting for Series Data</p>
        </div>;
    }

    return (
        <div className="flex flex-col h-full gap-3">
            <div className="flex items-center justify-between px-1">
                <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
                    <div className="w-1.5 h-1.5 bg-roulette-green rounded-full animate-pulse"></div>
                    Historical Roadway
                </span>
                <span className="text-[9px] font-bold text-gold uppercase tracking-tighter bg-gold/10 px-2 py-0.5 rounded-full border border-gold/20">
                    Scroll Left to Audit History
                </span>
            </div>

            <div 
                ref={scrollContainerRef} 
                className="flex flex-row gap-2 p-3 bg-gray-100 dark:bg-gray-900/50 rounded-2xl overflow-x-auto h-full w-full border border-gray-200 dark:border-gray-800/50"
                style={{ 
                    scrollbarWidth: 'auto', 
                    scrollbarColor: '#FFD700 rgba(0,0,0,0.1)',
                    msOverflowStyle: 'auto'
                }}
            >
                <style>{`
                    .custom-scrollbar-visible::-webkit-scrollbar {
                        height: 6px;
                        display: block;
                    }
                    .custom-scrollbar-visible::-webkit-scrollbar-track {
                        background: rgba(0,0,0,0.05);
                        border-radius: 10px;
                    }
                    .custom-scrollbar-visible::-webkit-scrollbar-thumb {
                        background: #FFD700;
                        border-radius: 10px;
                    }
                `}</style>
                <div className="flex flex-row gap-2 custom-scrollbar-visible">
                    {columns.map((col, colIndex) => (
                        <div key={colIndex} className="flex flex-col items-center gap-1.5 flex-shrink-0 min-w-[36px]">
                            <SeriesColumnHeader series={col.series} />
                            <div className="flex flex-col gap-2">
                                {col.items.map((item, itemIndex) => (
                                    <div key={`${item.num}-${itemIndex}-${colIndex}`} className="relative group">
                                        <SeriesIconDisplay 
                                            num={item.num} 
                                            predictionStatus={item.status}
                                        />
                                        <div className="absolute -top-1 -right-1 bg-white dark:bg-gray-800 text-[8px] font-black px-1 rounded-sm border border-gray-200 dark:border-gray-700 shadow-sm pointer-events-none opacity-80">
                                            #{item.index}
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            <div className="flex justify-center items-center gap-6 text-[9px] font-black uppercase text-gray-500 tracking-widest border-t border-gray-100 dark:border-gray-800/50 pt-2">
                <div className="flex items-center gap-2">
                    <div className="w-2.5 h-2.5 bg-blue-500 rounded-sm"></div>
                    <span>Hit</span>
                </div>
                <div className="flex items-center gap-2">
                    <div className="w-2.5 h-2.5 bg-yellow-400 rounded-sm"></div>
                    <span>Miss</span>
                </div>
                <div className="flex items-center gap-2">
                    <span className="text-gray-400">#N = Spin Index</span>
                </div>
            </div>
        </div>
    );
};

import React from 'react';
