export interface SeriesIconDisplayProps {
  num: number;
  predictionStatus?: 'correct' | 'wrong' | 'none';
}

export const SeriesIconDisplay: React.FC<SeriesIconDisplayProps> = ({ num, predictionStatus = 'none' }) => {
    const series = getSeriesType(num);
    const colorClass = {
        red: 'bg-roulette-red text-white',
        black: 'bg-roulette-black text-white',
        green: 'bg-roulette-green text-white',
    }[NUMBER_COLORS[num]];

    const iconColor = "text-white/20"; 

    const icon = () => {
        if (num === 0) return null; // Don't show a series icon for Zero

        const iconContainerClasses = "absolute inset-0 flex items-center justify-center";
        const svgClasses = "w-3/4 h-3/4";

        switch(series) {
            case 'Top':
                return <div className={iconContainerClasses}><svg viewBox="0 0 100 85" className={svgClasses} fill="currentColor"><polygon points="50,0 100,85 0,85" /></svg></div>;
            case 'Middle':
                return <div className={iconContainerClasses}><svg viewBox="0 0 100 100" className={svgClasses} fill="currentColor"><rect width="100" height="100" rx="8" /></svg></div>;
            case 'Small':
                return <div className={iconContainerClasses}><svg viewBox="0 0 100 85" className={svgClasses} fill="currentColor"><polygon points="0,0 100,0 50,85" /></svg></div>;
            default:
                return null;
        }
    }

    return (
        <div className={`w-9 h-9 rounded-xl flex items-center justify-center font-black text-sm shadow-md flex-shrink-0 relative transition-transform active:scale-90 touch-manipulation ${colorClass} ${iconColor}`}>
            {icon()}
            <span className="relative z-10 text-white drop-shadow-sm">{num}</span>

            {/* Accuracy Dots */}
            {predictionStatus === 'correct' && (
                <div className="absolute -bottom-0.5 -right-0.5 w-3 h-3 bg-blue-500 rounded-full border-2 border-white dark:border-gray-900 z-20 shadow-sm animate-pulse" title="Correct Prediction" />
            )}
            {predictionStatus === 'wrong' && (
                <div className="absolute -bottom-0.5 -right-0.5 w-3 h-3 bg-yellow-400 rounded-full border-2 border-white dark:border-gray-900 z-20 shadow-sm" title="Wrong Prediction" />
            )}
        </div>
    );
};

