import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { NumberGrid } from './components/NumberGrid';
import { SpinHistory } from './components/SpinHistory';
import { BettingChart } from './components/BettingChart';
import { ToastContainer } from './components/Toast';
import { VipPage } from './components/VipPage';
import { IntroductionPage } from './components/IntroductionPage';
import { ConfirmationModal } from './components/ConfirmationModal';
import type { ToastData, SeriesType, ComplexPrediction, RouletteColor } from './types';
import { getNeighbours, getSeriesType } from './utils/roulette';
import { PredictionDisplay } from './components/PredictionDisplay';
import { NUMBER_COLORS, ROULETTE_NUMBERS, EUROPEAN_WHEEL_ORDER } from './constants';

const MIN_SPINS_FOR_PATTERNS = 6;
const SESSION_STORAGE_KEY = 'rouletteSession_v2';
const INPUT_THROTTLE_MS = 400;

type PageType = 'main' | 'vip' | 'info';

export interface HitStatus {
    color: boolean;
    final: boolean;
    series: boolean;
    top: boolean;
}

const App: React.FC = () => {
  const [theme, setTheme] = useState<'light' | 'dark'>('dark');
  const [spinHistory, setSpinHistory] = useState<number[]>([]);
  const [alerts, setAlerts] = useState<ToastData[]>([]);
  const [alertsEnabled, setAlertsEnabled] = useState<boolean>(true);
  const [currentPage, setCurrentPage] = useState<PageType>('main');
  const [showClearConfirmation, setShowClearConfirmation] = useState<boolean>(false);
  const [bettingMap, setBettingMap] = useState<Map<number, number>>(new Map());
  const [balance, setBalance] = useState<number>(0);
  const [lastHitStatus, setLastHitStatus] = useState<HitStatus | null>(null);

  const lastInputTime = useRef<number>(0);

  const [isStrategyEnabled, setIsStrategyEnabled] = useState<boolean>(true);
  const [unitMultiplier, setUnitMultiplier] = useState<number>(1);
  const [unitMultiplierInput, setUnitMultiplierInput] = useState<string>('1');
  const [betStrategyMode, setBetStrategyMode] = useState<'235' | '123' | '111'>('235');
  const [neighbourDepth, setNeighbourDepth] = useState<3 | 5>(3);

  const triggerHaptic = (type: 'light' | 'medium' | 'heavy' | 'error' | 'success') => {
    if (!('vibrate' in navigator)) return;
    switch (type) {
      case 'light': navigator.vibrate(10); break;
      case 'medium': navigator.vibrate(25); break;
      case 'heavy': navigator.vibrate(50); break;
      case 'success': navigator.vibrate([30, 50, 30]); break;
      case 'error': navigator.vibrate([40, 30, 40]); break;
    }
  };

  useEffect(() => {
    const savedData = localStorage.getItem(SESSION_STORAGE_KEY);
    if (savedData) {
        try {
            const parsed = JSON.parse(savedData);
            if (parsed.history) setSpinHistory(parsed.history);
            if (parsed.alerts) setAlerts(parsed.alerts);
            if (parsed.multiplier) {
                setUnitMultiplier(parsed.multiplier);
                setUnitMultiplierInput(parsed.multiplier.toString());
            }
            if (parsed.strategyMode) setBetStrategyMode(parsed.strategyMode);
            if (parsed.depth) setNeighbourDepth(parsed.depth);
            if (parsed.strategyEnabled !== undefined) setIsStrategyEnabled(parsed.strategyEnabled);
            if (parsed.theme) setTheme(parsed.theme);
        } catch (error) {
            console.error("Failed to restore session:", error);
        }
    }
  }, []);

  useEffect(() => {
    const sessionData = {
        history: spinHistory,
        alerts: alerts,
        multiplier: unitMultiplier,
        strategyMode: betStrategyMode,
        depth: neighbourDepth,
        strategyEnabled: isStrategyEnabled,
        theme: theme
    };
    localStorage.setItem(SESSION_STORAGE_KEY, JSON.stringify(sessionData));
  }, [spinHistory, alerts, unitMultiplier, betStrategyMode, neighbourDepth, isStrategyEnabled, theme]);

  const calculateBets = useCallback((history: number[], mode: '235' | '123' | '111', depth: 3 | 5): Map<number, number> => {
    const newBettingMap = new Map<number, number>();
    const uniqueHistoryByRecency = [...new Set([...history].reverse())];
    if (uniqueHistoryByRecency.length < 2) return newBettingMap;
    const masterCandidatePool: number[] = [];
    uniqueHistoryByRecency.forEach(num => {
      if (num !== -1) {
        const depthVal = depth === 5 ? 2 : 1;
        masterCandidatePool.push(...getNeighbours(num, depthVal));
      }
    });
    const finalCandidates = [...new Set(masterCandidatePool)].filter(n => n !== -1);
    if (mode === '111') {
        finalCandidates.slice(0, 20).forEach(candidate => newBettingMap.set(candidate, 1));
        return newBettingMap;
    }
    const bet5 = new Set<number>();
    const bet3 = new Set<number>();
    const bet2 = new Set<number>();
    const alreadyBetOn = new Set<number>();
    for (const candidate of finalCandidates) {
      if (alreadyBetOn.has(candidate)) continue;
      if (bet5.size < 4) bet5.add(candidate);
      else if (bet3.size < 6) bet3.add(candidate);
      else if (bet2.size < 10) bet2.add(candidate);
      alreadyBetOn.add(candidate);
      if (bet2.size >= 10) break;
    }
    const units = mode === '235' ? [5, 3, 2] : [3, 2, 1];
    bet5.forEach(num => newBettingMap.set(num, units[0]));
    bet3.forEach(num => newBettingMap.set(num, units[1]));
    bet2.forEach(num => newBettingMap.set(num, units[2]));
    return newBettingMap;
  }, []);

  useEffect(() => {
      if (spinHistory.length > 0) {
          setBettingMap(calculateBets(spinHistory, betStrategyMode, neighbourDepth));
      } else {
          setBettingMap(new Map());
      }
  }, [spinHistory, betStrategyMode, neighbourDepth, calculateBets]);

  const totalBaseBetUnits = useMemo(() => {
    let total = 0;
    for (const unit of bettingMap.values()) total += unit;
    return total;
  }, [bettingMap]);

  useEffect(() => {
    if (!isStrategyEnabled) {
        setBalance(0);
        return;
    }
    let cumulativeBaseBalance = 0;
    for (let i = 8; i < spinHistory.length; i++) {
        const historySliceForBetting = spinHistory.slice(0, i);
        const winningNumber = spinHistory[i];
        const betsForThisRound = calculateBets(historySliceForBetting, betStrategyMode, neighbourDepth);
        const totalBaseBetForThisRound = (Array.from(betsForThisRound.values()) as number[]).reduce((sum, val) => sum + val, 0);
        if (totalBaseBetForThisRound > 0) {
            const betOnWinningNumber = betsForThisRound.get(winningNumber) || 0;
            const profitOrLoss = betOnWinningNumber > 0 
                ? (betOnWinningNumber * 36) - totalBaseBetForThisRound 
                : -totalBaseBetForThisRound;
            cumulativeBaseBalance += profitOrLoss;
        }
    }
    setBalance(cumulativeBaseBalance * unitMultiplier);
  }, [spinHistory, calculateBets, isStrategyEnabled, unitMultiplier, betStrategyMode, neighbourDepth]);

  useEffect(() => {
    if (theme === 'dark') document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
  }, [theme]);

  const toggleTheme = () => {
    triggerHaptic('light');
    setTheme(prevTheme => (prevTheme === 'light' ? 'dark' : 'light'));
  };

  const checkForAlerts = useCallback((history: number[]): Omit<ToastData, 'id'>[] => {
    if (history.length < MIN_SPINS_FOR_PATTERNS || !alertsEnabled) return [];
    const newAlerts: Omit<ToastData, 'id'>[] = [];
    const lastSpin = history[history.length - 1];
    const predictions = new Map<string, number[]>();
    for (let i = 0; i <= history.length - 3; i++) {
      if (history[i] === lastSpin) {
        const prediction = [history[i + 1], history[i + 2]];
        predictions.set(prediction.join(','), prediction);
      }
    }
     for (let i = 0; i <= history.length - 2; i++) {
        if (history[i] === lastSpin) {
            if (history.length > i + 1 && !predictions.has(`${history[i+1]}`)) {
                 const prediction = [history[i+1]];
                 if(!Array.from(predictions.values()).some(p => p.length === 2 && p[0] === prediction[0])) {
                     predictions.set(prediction.join(','), prediction);
                 }
            }
        }
    }
    if (predictions.size > 0) newAlerts.push({ trigger: [lastSpin], predictions: Array.from(predictions.values()) });
    if (history.length > 1) {
      const lastTwoSpins = history.slice(-2);
      const twoSpinPredictions = new Map<string, number[]>();
      for (let i = 0; i <= history.length - 3; i++) {
        if (history[i] === lastTwoSpins[0] && history[i + 1] === lastTwoSpins[1]) {
          const prediction = [history[i + 2]];
          twoSpinPredictions.set(prediction.join(','), prediction);
        }
      }
      if(twoSpinPredictions.size > 0) newAlerts.push({ trigger: lastTwoSpins, predictions: Array.from(twoSpinPredictions.values()) });
    }
    return newAlerts;
  }, [alertsEnabled]);

  const prediction = useMemo<ComplexPrediction | null>(() => {
    if (spinHistory.length < 5) return null;

    const history = spinHistory;
    const seriesHistory = history.map(getSeriesType);
    const colorHistory = history.map(n => NUMBER_COLORS[n]);
    const lastNumber = history[history.length - 1];
    const lastFinalDigit = lastNumber % 10;
    const lastSeries = seriesHistory[seriesHistory.length - 1];

    const scores: Map<number, number> = new Map();
    ROULETTE_NUMBERS.forEach(n => scores.set(n, 0));

    // 1. ADVANCED COLOR RECOGNITION (Weight 15)
    const colorMatches: Map<RouletteColor, number> = new Map();
    const last3Colors = colorHistory.slice(-3);
    for (let i = 0; i <= colorHistory.length - 4; i++) {
        if (colorHistory[i] === last3Colors[0] && colorHistory[i+1] === last3Colors[1] && colorHistory[i+2] === last3Colors[2]) {
            const next = colorHistory[i+3];
            colorMatches.set(next, (colorMatches.get(next) || 0) + 15);
        }
    }
    const sortedColors = Array.from(colorMatches.entries()).sort((a, b) => b[1] - a[1]);
    const likelyColor = sortedColors.length > 0 ? sortedColors[0][0] : colorHistory.filter((c, idx) => idx > colorHistory.length - 6).sort((a,b) => colorHistory.filter(v => v===a).length - colorHistory.filter(v => v===b).length)[0];

    if (likelyColor) {
        ROULETTE_NUMBERS.forEach(n => {
            if (NUMBER_COLORS[n] === likelyColor) scores.set(n, (scores.get(n) || 0) + 10);
        });
    }

    // 2. FINAL DIGIT TRANSITION (Weight 20)
    const digitTrans: Map<number, number> = new Map();
    for (let i = 0; i < history.length - 1; i++) {
        if (history[i] % 10 === lastFinalDigit) {
            const nextD = history[i+1] % 10;
            digitTrans.set(nextD, (digitTrans.get(nextD) || 0) + 1);
        }
    }
    const predictedFinalDigits = Array.from(digitTrans.entries())
        .filter(([_, count]) => count >= 1)
        .sort((a,b) => b[1] - a[1])
        .slice(0, 3)
        .map(([d]) => d);

    predictedFinalDigits.forEach((d, idx) => {
        ROULETTE_NUMBERS.forEach(n => {
            if (n % 10 === d) scores.set(n, (scores.get(n) || 0) + (20 - idx * 4));
        });
    });

    // 3. SECTOR ARC BIAS (Weight 25)
    const seriesTrans: Map<SeriesType, number> = new Map();
    for (let i = 0; i < seriesHistory.length - 1; i++) {
        if (seriesHistory[i] === lastSeries) {
            const nextS = seriesHistory[i+1];
            if (nextS !== 'none') seriesTrans.set(nextS, (seriesTrans.set(nextS, (seriesTrans.get(nextS) || 0) + 1)));
        }
    }
    const sortedSeries = Array.from(seriesTrans.entries()).sort((a,b) => b[1] - a[1]);
    const predictedSeries = sortedSeries.length > 0 ? sortedSeries[0][0] : lastSeries;

    if (predictedSeries !== 'none') {
        ROULETTE_NUMBERS.forEach(n => {
            if (getSeriesType(n) === predictedSeries) scores.set(n, (scores.get(n) || 0) + 15);
        });
    }

    // 4. NUMBER REPEAT SEQUENCES (Weight 40)
    // Last 2 numbers
    const last2 = history.slice(-2);
    for (let i = 0; i <= history.length - 3; i++) {
        if (history[i] === last2[0] && history[i+1] === last2[1]) {
            const next = history[i+2];
            scores.set(next, (scores.get(next) || 0) + 40);
        }
    }

    // 5. WHEEL GEOMETRY BIAS (GENIUS ADDITION)
    // If a certain area of the wheel is hitting frequently, weight the center of that area
    const wheelIndices = history.slice(-5).map(n => EUROPEAN_WHEEL_ORDER.indexOf(n));
    const avgWheelPos = Math.round(wheelIndices.reduce((a,b) => a+b, 0) / wheelIndices.length);
    const geometryTarget = EUROPEAN_WHEEL_ORDER[avgWheelPos % 37];
    const geometricNeighbors = getNeighbours(geometryTarget, 2);
    geometricNeighbors.forEach(n => scores.set(n, (scores.get(n) || 0) + 12));

    // 6. CONVERGENCE FILTERING
    // Numbers that match multiple criteria get a multiplier
    ROULETTE_NUMBERS.forEach(n => {
        let convergenceBonus = 1;
        if (NUMBER_COLORS[n] === likelyColor) convergenceBonus += 0.2;
        if (predictedFinalDigits.includes(n % 10)) convergenceBonus += 0.3;
        if (getSeriesType(n) === predictedSeries) convergenceBonus += 0.2;
        scores.set(n, (scores.get(n) || 0) * convergenceBonus);
    });

    // Final Sort and Neighbor Expansion for Accuracy
    let rawTop = Array.from(scores.entries())
        .sort((a,b) => b[1] - a[1])
        .filter(e => e[1] > 0)
        .slice(0, 3);

    // If we have a very strong top candidate, ensure its physical wheel neighbors are also considered
    if (rawTop.length > 0 && rawTop[0][1] > 30) {
        const primary = rawTop[0][0];
        const neighbors = getNeighbours(primary, 1);
        neighbors.forEach(n => {
            if (!rawTop.some(e => e[0] === n)) {
                const neighborScore = scores.get(n) || 0;
                scores.set(n, neighborScore + (rawTop[0][1] * 0.4)); // Boost neighbors of king number
            }
        });
        // Re-sort after neighbor boost
        rawTop = Array.from(scores.entries())
            .sort((a,b) => b[1] - a[1])
            .slice(0, 3);
    }

    return {
        series: predictedSeries,
        topNumbers: rawTop.map(([num, score]) => ({
            num,
            confidence: Math.min(99, Math.round((score / 80) * 100))
        })),
        color: likelyColor,
        finalDigits: predictedFinalDigits
    };
  }, [spinHistory]);

  const handleAddSpin = useCallback((num: number) => {
    const now = Date.now();
    if (now - lastInputTime.current < INPUT_THROTTLE_MS) return;
    lastInputTime.current = now;

    // Evaluate last prediction before adding new spin
    if (prediction) {
        const hitData = {
            color: prediction.color === NUMBER_COLORS[num],
            final: prediction.finalDigits.includes(num % 10),
            series: prediction.series === getSeriesType(num),
            top: prediction.topNumbers.some(tn => tn.num === num)
        };
        setLastHitStatus(hitData);
        if (hitData.color || hitData.final || hitData.series || hitData.top) {
            triggerHaptic('success');
        } else {
            triggerHaptic('medium');
        }
    } else {
        triggerHaptic('medium');
    }

    const newHistory = [...spinHistory, num];
    setSpinHistory(newHistory);
    if (newHistory.length >= MIN_SPINS_FOR_PATTERNS) {
        const alertsFromCheck = checkForAlerts(newHistory);
        if (alertsFromCheck.length > 0) {
            const freshAlerts = alertsFromCheck.map((alert, index) => ({ ...alert, id: Date.now() + index })).reverse();
            setAlerts(currentAlerts => [...freshAlerts, ...currentAlerts].slice(0, 5));
        }
    }
  }, [spinHistory, checkForAlerts, prediction]);

  const handleRemoveLastSpin = useCallback(() => {
    if (spinHistory.length === 0) return;
    const now = Date.now();
    if (now - lastInputTime.current < INPUT_THROTTLE_MS) return;
    lastInputTime.current = now;
    triggerHaptic('light');
    const newHistory = spinHistory.slice(0, -1);
    setSpinHistory(newHistory);
    setLastHitStatus(null);
    setAlerts(currentAlerts => currentAlerts.filter(alert => {
        const lastSpin = spinHistory[spinHistory.length - 1];
        const trigger = alert.trigger;
        if (trigger.length === 1 && trigger[0] === lastSpin) return false;
        if (trigger.length === 2 && trigger[1] === lastSpin) return false;
        return true;
    }));
  }, [spinHistory]);

  const handleRemoveAlert = (id: number) => {
    triggerHaptic('light');
    setAlerts(currentAlerts => currentAlerts.filter(alert => alert.id !== id));
  };

  const handleClearSession = () => {
    triggerHaptic('error');
    setSpinHistory([]);
    setAlerts([]);
    setLastHitStatus(null);
    localStorage.removeItem(SESSION_STORAGE_KEY);
    setShowClearConfirmation(false);
  };

  const switchPage = (page: PageType) => {
    triggerHaptic('light');
    setCurrentPage(page);
  };

  return (
    <div className="min-h-screen text-gray-800 dark:text-gray-200 font-sans selection:bg-gold/30 flex flex-col overflow-hidden">
      {/* Safe Area Header */}
      <header className="bg-white/80 dark:bg-gray-900/80 backdrop-blur-md sticky top-0 z-40 shadow-sm border-b border-gray-200 dark:border-gray-800 pt-[env(safe-area-inset-top)]">
        <div className="container mx-auto px-4 py-1.5 flex justify-between items-center h-11">
          <h1 className="text-base font-bold text-gray-900 dark:text-white" style={{fontFamily: "'Playfair Display', serif"}}>
            Roulette <span className="text-gold">Tracker</span>
          </h1>
          <div className="flex items-center space-x-1.5">
            <button type="button" onClick={() => switchPage('info')} className="p-1 rounded-lg text-gray-500 border border-gray-200 dark:border-gray-700 active:scale-95" title="Help & Info">
              <InfoIcon />
            </button>
            <button type="button" onClick={() => switchPage(currentPage === 'vip' ? 'main' : 'vip')} className={`p-1 rounded-lg transition-all flex items-center space-x-1 border active:scale-95 ${currentPage === 'vip' ? 'bg-gold text-black border-gold' : 'text-gold border-gold/20'}`}>
              <CrownIcon />
              <span className="text-[10px] font-black uppercase tracking-tighter">VIP</span>
            </button>
            <button onClick={toggleTheme} className="p-1 rounded-lg text-gray-600 dark:text-gray-300 border border-gray-200 dark:border-gray-700 active:scale-95">
              {theme === 'light' ? <MoonIcon /> : <SunIcon />}
            </button>
          </div>
        </div>
      </header>

      {/* Main content */}
      <main className="flex-1 overflow-y-auto overflow-x-hidden custom-scrollbar pb-[env(safe-area-inset-bottom)]">
        <div className="container mx-auto px-1.5 py-2 max-w-5xl">
            {currentPage === 'main' ? (
            <div className="flex flex-col gap-1.5 animate-fade-in">
                <div className="w-full bg-white dark:bg-gray-800 p-2 rounded-xl shadow-md border border-gray-100 dark:border-gray-700/50">
                    <NumberGrid onNumberSelect={handleAddSpin} disabled={false} />
                </div>

                {/* Compact Strategy Dashboard */}
                <div className="bg-white dark:bg-gray-800 p-1.5 rounded-xl shadow-md border border-gray-100 dark:border-gray-700/50">
                    <div className="flex flex-wrap items-center justify-between gap-x-3 gap-y-1 mb-1 px-1">
                        <div className="flex items-center gap-2">
                            <h2 className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Strategy</h2>
                            <button onClick={() => setIsStrategyEnabled(!isStrategyEnabled)} className={`relative inline-flex items-center h-3.5 rounded-full w-7 transition-colors ${isStrategyEnabled ? 'bg-roulette-green' : 'bg-gray-400 dark:bg-gray-600'}`}>
                                <span className={`inline-block w-2.5 h-2.5 transform bg-white rounded-full transition-transform ${isStrategyEnabled ? 'translate-x-3.5' : 'translate-x-1'}`} />
                            </button>
                        </div>

                        <div className="flex items-center gap-2">
                             <div className="flex items-center gap-1 bg-gray-50 dark:bg-gray-900/40 p-0.5 px-1.5 rounded-lg border border-gray-100 dark:border-gray-700/30">
                                <span className="text-[9px] font-black text-gray-400 uppercase tracking-tighter">Unit:</span>
                                <input type="number" value={unitMultiplierInput} onChange={(e) => {
                                        setUnitMultiplierInput(e.target.value);
                                        const num = parseInt(e.target.value, 10);
                                        if (!isNaN(num) && num > 0) setUnitMultiplier(num);
                                    }} onBlur={() => {
                                        const num = parseInt(unitMultiplierInput, 10);
                                        if (isNaN(num) || num < 1) { setUnitMultiplierInput('1'); setUnitMultiplier(1); }
                                    }} disabled={!isStrategyEnabled} className="w-8 bg-transparent text-center font-black text-[11px] outline-none disabled:opacity-40" />
                            </div>

                            <div className="flex bg-gray-50 dark:bg-gray-900/40 rounded-lg p-0.5 border border-gray-100 dark:border-gray-700/30">
                                <button onClick={() => {triggerHaptic('light'); setNeighbourDepth(3)}} disabled={!isStrategyEnabled} className={`px-2 py-0.5 text-[9px] font-black rounded ${neighbourDepth === 3 ? 'bg-gold text-black' : 'text-gray-500'}`}>N3</button>
                                <button onClick={() => {triggerHaptic('light'); setNeighbourDepth(5)}} disabled={!isStrategyEnabled} className={`px-2 py-0.5 text-[9px] font-black rounded ${neighbourDepth === 5 ? 'bg-gold text-black' : 'text-gray-500'}`}>N5</button>
                            </div>

                            <button onClick={() => {triggerHaptic('light'); setBetStrategyMode(m => m === '235' ? '123' : m === '123' ? '111' : '235')}} disabled={!isStrategyEnabled} className={`px-2 py-0.5 text-[9px] font-black rounded transition-all shadow-sm ${betStrategyMode === '235' ? 'bg-green-600 text-white' : betStrategyMode === '123' ? 'bg-yellow-500 text-black' : 'bg-blue-600 text-white'} disabled:opacity-30`}>{betStrategyMode}</button>
                        </div>
                    </div>

                    {isStrategyEnabled && (
                        <div className="animate-fade-in space-y-1.5">
                            {spinHistory.length >= 8 ? (
                                <>
                                    <div className="flex justify-between items-center py-1 border-t border-gray-100 dark:border-gray-700/50">
                                        <div className="text-[10px] font-black uppercase tracking-tighter">
                                            <span className="text-gray-400">P/L: </span>
                                            <span className={balance >= 0 ? 'text-green-500' : 'text-red-500'}>{balance >= 0 ? '+' : ''}{balance}</span>
                                        </div>
                                        {bettingMap.size > 0 && (
                                            <div className="text-[10px] font-black text-gray-500 dark:text-gray-400 uppercase tracking-tighter">
                                                Bet: <span className="text-gold text-xs">{totalBaseBetUnits * unitMultiplier}</span>
                                            </div>
                                        )}
                                    </div>
                                    <BettingChart bettingMap={bettingMap} />
                                </>
                            ) : (
                                <div className="border-t border-gray-100 dark:border-gray-700/50 pt-1.5 pb-0.5 text-center">
                                    <p className="text-[9px] text-gray-400 font-bold uppercase tracking-widest italic animate-pulse">Waiting ({8 - spinHistory.length})</p>
                                </div>
                            )}
                        </div>
                    )}
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-1.5">
                    <div className="bg-white dark:bg-gray-800 p-2 rounded-xl shadow-md border border-gray-100 dark:border-gray-700/50">
                        <div className="flex justify-between items-center mb-1.5">
                            <h2 className="text-[10px] font-black uppercase text-gray-400 tracking-widest">History ({spinHistory.length})</h2>
                            <PredictionDisplay prediction={prediction} lastHitStatus={lastHitStatus} />
                        </div>
                        {spinHistory.length > 0 ? <SpinHistory history={spinHistory} /> : <p className="text-gray-400 text-center py-4 text-[9px] font-black uppercase italic tracking-widest">Empty</p>}
                    </div>
                    <div className="bg-white dark:bg-gray-800 p-2 rounded-xl shadow-md border border-gray-100 dark:border-gray-700/50">
                        <h2 className="text-[10px] font-black uppercase text-gray-400 tracking-widest mb-1.5">Alerts</h2>
                        <ToastContainer toasts={alerts} onRemoveToast={handleRemoveAlert} />
                    </div>
                </div>

                <div className="bg-white dark:bg-gray-800 p-2 rounded-xl shadow-md border border-gray-100 dark:border-gray-700/50 mt-0.5 mb-2">
                    <div className="flex items-center justify-between gap-1.5">
                        <div className="flex items-center gap-2 bg-gray-100 dark:bg-gray-900/50 px-2 py-1.5 rounded-lg flex-1 border border-gray-200 dark:border-gray-700/50">
                            <span className="text-[10px] font-black uppercase tracking-widest text-gray-500">Alerts</span>
                            <button onClick={() => {triggerHaptic('light'); setAlertsEnabled(!alertsEnabled)}} className={`relative inline-flex items-center h-3.5 rounded-full w-7 transition-colors ${alertsEnabled ? 'bg-roulette-green' : 'bg-gray-400 dark:bg-gray-600'}`}>
                                <span className={`inline-block w-2.5 h-2.5 transform bg-white rounded-full transition-transform ${alertsEnabled ? 'translate-x-3.5' : 'translate-x-1'}`}/>
                            </button>
                        </div>
                        <div className="flex gap-1.5 flex-1">
                            <button onClick={handleRemoveLastSpin} disabled={spinHistory.length === 0} className="flex-1 bg-yellow-500 text-black font-black py-1.5 rounded-lg hover:bg-yellow-600 disabled:opacity-40 text-[10px] uppercase tracking-widest transition-all active:scale-95">Undo</button>
                            <button onClick={() => {triggerHaptic('medium'); setShowClearConfirmation(true)}} className="flex-1 bg-roulette-red text-white font-black py-1.5 rounded-lg hover:bg-red-700 text-[10px] uppercase tracking-widest transition-all active:scale-95">Clear</button>
                        </div>
                    </div>
                </div>
            </div>
            ) : currentPage === 'vip' ? (
            <div className="animate-slide-up">
                <VipPage spinHistory={spinHistory} onBack={() => switchPage('main')} prediction={prediction} />
            </div>
            ) : (
            <div className="animate-slide-up">
                <IntroductionPage onBack={() => switchPage('main')} />
            </div>
            )}
        </div>
      </main>
      <ConfirmationModal isOpen={showClearConfirmation} onClose={() => setShowClearConfirmation(false)} onConfirm={handleClearSession} title="Clear Records" message="This will clear all history and patterns. Continue?" />
    </div>
  );
};

const SunIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z" />
    </svg>
);
const MoonIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z" />
    </svg>
);
const CrownIcon = () => (
  <svg xmlns="http://www.w3.org/2000/svg" className="h-3.5 w-3.5" viewBox="0 0 24 24" fill="currentColor">
    <path d="M5 16L3 5l5.5 5L12 4l3.5 6L21 5l-2 11H5zm14 3c0 .55-.45 1-1 1H6c-.55 0-1-.45-1-1v-1h14v1z"></path>
  </svg>
);
const InfoIcon = () => (
    <div className="w-3.5 h-3.5 rounded border-2 border-current flex items-center justify-center font-black text-[9px]">
        ?
    </div>
);

export default App;

import React, { useMemo } from 'react';
import { NUMBER_COLORS, ROULETTE_NUMBERS, EUROPEAN_WHEEL_ORDER } from '../constants';
import { SeriesTracker } from './SeriesTracker';
import { getSeriesType, getNeighbours } from '../utils/roulette';
import type { SeriesType, ComplexPrediction, RouletteColor } from '../types';
import { FinalNumberMatrix } from './FinalNumberMatrix';

const BackIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M15 19l-7-7 7-7" />
    </svg>
);

const HotNumbers: React.FC<{ history: number[] }> = ({ history }) => {
    const hotNumbers = useMemo(() => {
        if (history.length === 0) return [];
        const counts = new Map<number, number>();
        history.forEach(num => counts.set(num, (counts.get(num) || 0) + 1));
        return Array.from(counts.entries()).sort((a, b) => b[1] - a[1]).slice(0, 5);
    }, [history]);

    if (hotNumbers.length === 0) {
        return <div className="flex items-center justify-center h-16"><p className="text-center text-gray-500 dark:text-gray-400 font-bold text-xs uppercase tracking-widest italic">Insufficient data</p></div>;
    }

    const colorClasses = {
        red: 'bg-roulette-red text-white',
        black: 'bg-roulette-black text-white',
        green: 'bg-roulette-green text-white',
    };

    return (
        <div className="flex justify-start items-start text-center gap-4 py-2 custom-scrollbar overflow-x-auto">
            {hotNumbers.map(([num, count], index) => (
                <div key={num} className="flex flex-col items-center flex-shrink-0">
                    <span className="font-black text-[9px] text-gold mb-1 uppercase tracking-tighter">Rank {index + 1}</span>
                    <div className={`w-9 h-9 rounded-2xl flex items-center justify-center font-black text-sm shadow-md ${colorClasses[NUMBER_COLORS[num]]}`}>
                        {num}
                    </div>
                    <div className="mt-1.5 text-[10px] font-black text-gray-700 dark:text-gray-300 uppercase tracking-tighter">{count} Hits</div>
                </div>
            ))}
        </div>
    );
};

interface StatReportCardProps {
    label: string;
    wins: number;
    total: number;
}

const StatReportCard: React.FC<StatReportCardProps> = ({ label, wins, total }) => {
    const rate = total > 0 ? Math.round((wins / total) * 100) : 0;
    return (
        <div className="bg-white dark:bg-gray-800/40 border border-gray-100 dark:border-gray-700 p-3 rounded-2xl flex flex-col items-center shadow-sm">
            <span className="text-[10px] font-black uppercase text-gold mb-1 tracking-widest">{label}</span>
            <div className="flex flex-col items-center">
                <div className="text-[9px] font-bold text-gray-400 uppercase tracking-tighter flex gap-2">
                    <span>In: {total}</span>
                    <span>Hit: {wins}</span>
                </div>
                <div className={`text-lg font-black mt-1 ${rate >= 50 ? 'text-green-500' : 'text-gray-400'}`}>
                    {rate}%
                </div>
            </div>
        </div>
    );
};

interface VipPageProps {
    spinHistory: number[];
    onBack: () => void;
    prediction: ComplexPrediction | null;
}

export const VipPage: React.FC<VipPageProps> = ({ spinHistory, onBack, prediction }) => {
    const reportStats = useMemo(() => {
        const stats = {
            color: { offered: 0, wins: 0 },
            final: { offered: 0, wins: 0 },
            series: { offered: 0, wins: 0 },
            top: { offered: 0, wins: 0 }
        };
        if (spinHistory.length < 10) return stats;

        for (let j = 8; j < spinHistory.length; j++) {
            const h = spinHistory.slice(0, j);
            const winner = spinHistory[j];
            const winnerColor = NUMBER_COLORS[winner];
            const winnerFinal = winner % 10;
            const winnerSeries = getSeriesType(winner);

            const colorHistory = h.map(n => NUMBER_COLORS[n]);
            const seriesHistory = h.map(getSeriesType);
            const lastNum = h[h.length - 1];
            const lastFinal = lastNum % 10;
            const lastSeries = seriesHistory[seriesHistory.length - 1];

            // COLOR PREDICTION
            const colorMatches: Map<RouletteColor, number> = new Map();
            const last3Colors = colorHistory.slice(-3);
            for (let i = 0; i <= colorHistory.length - 4; i++) {
                if (colorHistory[i] === last3Colors[0] && colorHistory[i+1] === last3Colors[1] && colorHistory[i+2] === last3Colors[2]) {
                    const next = colorHistory[i+3];
                    colorMatches.set(next, (colorMatches.get(next) || 0) + 1);
                }
            }
            const sortedColors = Array.from(colorMatches.entries()).sort((a,b) => b[1] - a[1]);
            const predColor = sortedColors.length > 0 ? sortedColors[0][0] : null;
            if (predColor) {
                stats.color.offered++;
                if (predColor === winnerColor) stats.color.wins++;
            }

            // FINAL DIGIT PREDICTION
            const digitTrans: Map<number, number> = new Map();
            for (let i = 0; i < h.length - 1; i++) {
                if (h[i] % 10 === lastFinal) {
                    const nextD = h[i+1] % 10;
                    digitTrans.set(nextD, (digitTrans.get(nextD) || 0) + 1);
                }
            }
            const predFinals = Array.from(digitTrans.entries())
                .sort((a,b) => b[1] - a[1])
                .slice(0, 3)
                .map(([d]) => d);
            if (predFinals.length > 0) {
                stats.final.offered++;
                if (predFinals.includes(winnerFinal)) stats.final.wins++;
            }

            // SERIES PREDICTION
            const seriesTrans: Map<SeriesType, number> = new Map();
            for (let i = 0; i < seriesHistory.length - 1; i++) {
                if (seriesHistory[i] === lastSeries) {
                    const nextS = seriesHistory[i+1];
                    if (nextS !== 'none') seriesTrans.set(nextS, (seriesTrans.get(nextS) || 0) + 1);
                }
            }
            const sortedSeries = Array.from(seriesTrans.entries()).sort((a,b) => b[1] - a[1]);
            const predSeries = sortedSeries.length > 0 ? sortedSeries[0][0] : null;
            if (predSeries && predSeries !== 'none') {
                stats.series.offered++;
                if (predSeries === winnerSeries) stats.series.wins++;
            }

            // GENIUS TOP NUMBER PREDICTION RE-IMPLEMENTATION
            const scores: Map<number, number> = new Map();
            ROULETTE_NUMBERS.forEach(n => scores.set(n, 0));

            if (predColor) ROULETTE_NUMBERS.forEach(n => { if (NUMBER_COLORS[n] === predColor) scores.set(n, (scores.get(n) || 0) + 10); });
            predFinals.forEach((d, idx) => { ROULETTE_NUMBERS.forEach(n => { if (n % 10 === d) scores.set(n, (scores.get(n) || 0) + (20 - idx * 4)); }); });
            if (predSeries && predSeries !== 'none') ROULETTE_NUMBERS.forEach(n => { if (getSeriesType(n) === predSeries) scores.set(n, (scores.get(n) || 0) + 15); });
            const last2 = h.slice(-2);
            for (let i = 0; i <= h.length - 3; i++) {
                if (h[i] === last2[0] && h[i+1] === last2[1]) scores.set(h[i+2], (scores.get(h[i+2]) || 0) + 40);
            }

            // Convergence bonus
            ROULETTE_NUMBERS.forEach(n => {
                let conv = 1;
                if (predColor && NUMBER_COLORS[n] === predColor) conv += 0.2;
                if (predFinals.includes(n % 10)) conv += 0.3;
                if (predSeries && getSeriesType(n) === predSeries) conv += 0.2;
                scores.set(n, (scores.get(n) || 0) * conv);
            });

            const topSorted = Array.from(scores.entries()).sort((a,b) => b[1] - a[1]);
            if (topSorted.length > 0) {
                // Check neighbors of the top pick too for "hit" accounting
                const primaryPick = topSorted[0][0];
                const secondaryPicks = topSorted.slice(1, 3).map(e => e[0]);
                stats.top.offered++;
                if (primaryPick === winner || secondaryPicks.includes(winner)) {
                    stats.top.wins++;
                }
            }
        }
        return stats;
    }, [spinHistory]);

    return (
        <div className="animate-fade-in pb-12">
            <div className="flex items-center mb-6 mt-2">
                <button onClick={onBack} className="p-2.5 rounded-2xl bg-white dark:bg-gray-800 shadow-md hover:bg-gray-100 dark:hover:bg-gray-700 active:scale-95 transition-all mr-4 border border-gray-100 dark:border-gray-700" aria-label="Back">
                    <BackIcon />
                </button>
                <h2 className="text-2xl font-black" style={{fontFamily: "'Playfair Display', serif"}}>
                    VIP <span className="text-gold">Intelligence</span>
                </h2>
            </div>

            <div className="flex flex-col gap-6">
                <div className="bg-white dark:bg-gray-800 p-5 rounded-3xl shadow-xl border border-gray-100 dark:border-gray-700/50">
                    <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-widest mb-4">Sector Heatmap Tracking</h3>
                    <div className="h-64 sm:h-80">
                        <SeriesTracker history={spinHistory} />
                    </div>
                </div>

                <div className="bg-white dark:bg-gray-800 p-5 rounded-3xl shadow-xl border border-gray-100 dark:border-gray-700/50">
                    <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-widest mb-4">Final Digit Frequency Matrix</h3>
                    <FinalNumberMatrix history={spinHistory} />
                </div>

                <div className="bg-white dark:bg-gray-800 p-5 rounded-3xl shadow-xl border border-gray-100 dark:border-gray-700/50">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                        <div>
                            <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-widest mb-4">Hot Number Ranking</h3>
                            <HotNumbers history={spinHistory} />
                        </div>

                        <div className="flex flex-col">
                            <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-3">
                                Accuracy Performance
                                <div className="h-[1px] flex-1 bg-gray-100 dark:bg-gray-700/50"></div>
                            </h3>

                            <div className="grid grid-cols-2 gap-3">
                                <StatReportCard label="Color" wins={reportStats.color.wins} total={reportStats.color.offered} />
                                <StatReportCard label="Finals" wins={reportStats.final.wins} total={reportStats.final.offered} />
                                <StatReportCard label="Series" wins={reportStats.series.wins} total={reportStats.series.offered} />
                                <StatReportCard label="Top Number" wins={reportStats.top.wins} total={reportStats.top.offered} />
                            </div>

                            {spinHistory.length < 10 && (
                                <div className="mt-4 bg-gray-50 dark:bg-gray-900/30 p-3 rounded-2xl border border-dashed border-gray-200 dark:border-gray-700">
                                    <p className="text-[10px] font-black text-gray-400 italic text-center uppercase tracking-widest">
                                        Data gathering in progress...
                                    </p>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { NumberGrid } from './components/NumberGrid';
import { SpinHistory } from './components/SpinHistory';
import { BettingChart } from './components/BettingChart';
import { ToastContainer } from './components/Toast';
import { VipPage } from './components/VipPage';
import { IntroductionPage } from './components/IntroductionPage';
import { ConfirmationModal } from './components/ConfirmationModal';
import type { ToastData, SeriesType, ComplexPrediction, RouletteColor } from './types';
import { getNeighbours, getSeriesType } from './utils/roulette';
import { PredictionDisplay } from './components/PredictionDisplay';
import { NUMBER_COLORS, ROULETTE_NUMBERS, EUROPEAN_WHEEL_ORDER } from './constants';

const MIN_SPINS_FOR_PATTERNS = 6;
const SESSION_STORAGE_KEY = 'rouletteSession_v2';
const INPUT_THROTTLE_MS = 400;

type PageType = 'main' | 'vip' | 'info';

export interface HitStatus {
    color: boolean;
    final: boolean;
    series: boolean;
    top: boolean;
}

const App: React.FC = () => {
  const [theme, setTheme] = useState<'light' | 'dark'>('dark');
  const [spinHistory, setSpinHistory] = useState<number[]>([]);
  const [alerts, setAlerts] = useState<ToastData[]>([]);
  const [alertsEnabled, setAlertsEnabled] = useState<boolean>(true);
  const [currentPage, setCurrentPage] = useState<PageType>('main');
  const [showClearConfirmation, setShowClearConfirmation] = useState<boolean>(false);
  const [bettingMap, setBettingMap] = useState<Map<number, number>>(new Map());
  const [balance, setBalance] = useState<number>(0);
  const [lastHitStatus, setLastHitStatus] = useState<HitStatus | null>(null);

  const lastInputTime = useRef<number>(0);

  const [isStrategyEnabled, setIsStrategyEnabled] = useState<boolean>(true);
  const [unitMultiplier, setUnitMultiplier] = useState<number>(1);
  const [unitMultiplierInput, setUnitMultiplierInput] = useState<string>('1');
  const [betStrategyMode, setBetStrategyMode] = useState<'235' | '123' | '111'>('235');
  const [neighbourDepth, setNeighbourDepth] = useState<3 | 5>(3);

  const triggerHaptic = (type: 'light' | 'medium' | 'heavy' | 'error' | 'success') => {
    if (!('vibrate' in navigator)) return;
    switch (type) {
      case 'light': navigator.vibrate(10); break;
      case 'medium': navigator.vibrate(25); break;
      case 'heavy': navigator.vibrate(50); break;
      case 'success': navigator.vibrate([30, 50, 30]); break;
      case 'error': navigator.vibrate([40, 30, 40]); break;
    }
  };

  useEffect(() => {
    const savedData = localStorage.getItem(SESSION_STORAGE_KEY);
    if (savedData) {
        try {
            const parsed = JSON.parse(savedData);
            if (parsed.history) setSpinHistory(parsed.history);
            if (parsed.alerts) setAlerts(parsed.alerts);
            if (parsed.multiplier) {
                setUnitMultiplier(parsed.multiplier);
                setUnitMultiplierInput(parsed.multiplier.toString());
            }
            if (parsed.strategyMode) setBetStrategyMode(parsed.strategyMode);
            if (parsed.depth) setNeighbourDepth(parsed.depth);
            if (parsed.strategyEnabled !== undefined) setIsStrategyEnabled(parsed.strategyEnabled);
            if (parsed.theme) setTheme(parsed.theme);
        } catch (error) {
            console.error("Failed to restore session:", error);
        }
    }
  }, []);

  useEffect(() => {
    const sessionData = {
        history: spinHistory,
        alerts: alerts,
        multiplier: unitMultiplier,
        strategyMode: betStrategyMode,
        depth: neighbourDepth,
        strategyEnabled: isStrategyEnabled,
        theme: theme
    };
    localStorage.setItem(SESSION_STORAGE_KEY, JSON.stringify(sessionData));
  }, [spinHistory, alerts, unitMultiplier, betStrategyMode, neighbourDepth, isStrategyEnabled, theme]);

  const calculateBets = useCallback((history: number[], mode: '235' | '123' | '111', depth: 3 | 5): Map<number, number> => {
    const newBettingMap = new Map<number, number>();
    const uniqueHistoryByRecency = [...new Set([...history].reverse())];
    if (uniqueHistoryByRecency.length < 2) return newBettingMap;
    const masterCandidatePool: number[] = [];
    uniqueHistoryByRecency.forEach(num => {
      if (num !== -1) {
        const depthVal = depth === 5 ? 2 : 1;
        masterCandidatePool.push(...getNeighbours(num, depthVal));
      }
    });
    const finalCandidates = [...new Set(masterCandidatePool)].filter(n => n !== -1);
    if (mode === '111') {
        finalCandidates.slice(0, 20).forEach(candidate => newBettingMap.set(candidate, 1));
        return newBettingMap;
    }
    const bet5 = new Set<number>();
    const bet3 = new Set<number>();
    const bet2 = new Set<number>();
    const alreadyBetOn = new Set<number>();
    for (const candidate of finalCandidates) {
      if (alreadyBetOn.has(candidate)) continue;
      if (bet5.size < 4) bet5.add(candidate);
      else if (bet3.size < 6) bet3.add(candidate);
      else if (bet2.size < 10) bet2.add(candidate);
      alreadyBetOn.add(candidate);
      if (bet2.size >= 10) break;
    }
    const units = mode === '235' ? [5, 3, 2] : [3, 2, 1];
    bet5.forEach(num => newBettingMap.set(num, units[0]));
    bet3.forEach(num => newBettingMap.set(num, units[1]));
    bet2.forEach(num => newBettingMap.set(num, units[2]));
    return newBettingMap;
  }, []);

  useEffect(() => {
      if (spinHistory.length > 0) {
          setBettingMap(calculateBets(spinHistory, betStrategyMode, neighbourDepth));
      } else {
          setBettingMap(new Map());
      }
  }, [spinHistory, betStrategyMode, neighbourDepth, calculateBets]);

  const totalBaseBetUnits = useMemo(() => {
    let total = 0;
    for (const unit of bettingMap.values()) total += unit;
    return total;
  }, [bettingMap]);

  useEffect(() => {
    if (!isStrategyEnabled) {
        setBalance(0);
        return;
    }
    let cumulativeBaseBalance = 0;
    for (let i = 8; i < spinHistory.length; i++) {
        const historySliceForBetting = spinHistory.slice(0, i);
        const winningNumber = spinHistory[i];
        const betsForThisRound = calculateBets(historySliceForBetting, betStrategyMode, neighbourDepth);
        const totalBaseBetForThisRound = (Array.from(betsForThisRound.values()) as number[]).reduce((sum, val) => sum + val, 0);
        if (totalBaseBetForThisRound > 0) {
            const betOnWinningNumber = betsForThisRound.get(winningNumber) || 0;
            const profitOrLoss = betOnWinningNumber > 0 
                ? (betOnWinningNumber * 36) - totalBaseBetForThisRound 
                : -totalBaseBetForThisRound;
            cumulativeBaseBalance += profitOrLoss;
        }
    }
    setBalance(cumulativeBaseBalance * unitMultiplier);
  }, [spinHistory, calculateBets, isStrategyEnabled, unitMultiplier, betStrategyMode, neighbourDepth]);

  useEffect(() => {
    if (theme === 'dark') document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
  }, [theme]);

  const toggleTheme = () => {
    triggerHaptic('light');
    setTheme(prevTheme => (prevTheme === 'light' ? 'dark' : 'light'));
  };

  const checkForAlerts = useCallback((history: number[]): Omit<ToastData, 'id'>[] => {
    if (history.length < MIN_SPINS_FOR_PATTERNS || !alertsEnabled) return [];
    const newAlerts: Omit<ToastData, 'id'>[] = [];
    const lastSpin = history[history.length - 1];
    const predictions = new Map<string, number[]>();
    for (let i = 0; i <= history.length - 3; i++) {
      if (history[i] === lastSpin) {
        const prediction = [history[i + 1], history[i + 2]];
        predictions.set(prediction.join(','), prediction);
      }
    }
     for (let i = 0; i <= history.length - 2; i++) {
        if (history[i] === lastSpin) {
            if (history.length > i + 1 && !predictions.has(`${history[i+1]}`)) {
                 const prediction = [history[i+1]];
                 if(!Array.from(predictions.values()).some(p => p.length === 2 && p[0] === prediction[0])) {
                     predictions.set(prediction.join(','), prediction);
                 }
            }
        }
    }
    if (predictions.size > 0) newAlerts.push({ trigger: [lastSpin], predictions: Array.from(predictions.values()) });
    if (history.length > 1) {
      const lastTwoSpins = history.slice(-2);
      const twoSpinPredictions = new Map<string, number[]>();
      for (let i = 0; i <= history.length - 3; i++) {
        if (history[i] === lastTwoSpins[0] && history[i + 1] === lastTwoSpins[1]) {
          const prediction = [history[i + 2]];
          twoSpinPredictions.set(prediction.join(','), prediction);
        }
      }
      if(twoSpinPredictions.size > 0) newAlerts.push({ trigger: lastTwoSpins, predictions: Array.from(twoSpinPredictions.values()) });
    }
    return newAlerts;
  }, [alertsEnabled]);

  const prediction = useMemo<ComplexPrediction | null>(() => {
    if (spinHistory.length < 5) return null;

    const history = spinHistory;
    const seriesHistory = history.map(getSeriesType);
    const colorHistory = history.map(n => NUMBER_COLORS[n]);
    const lastNumber = history[history.length - 1];
    const lastFinalDigit = lastNumber % 10;
    const lastSeries = seriesHistory[seriesHistory.length - 1];

    const scores: Map<number, number> = new Map();
    ROULETTE_NUMBERS.forEach(n => scores.set(n, 0));

    // 1. ADVANCED COLOR RECOGNITION (Weight 15)
    const colorMatches: Map<RouletteColor, number> = new Map();
    const last3Colors = colorHistory.slice(-3);
    for (let i = 0; i <= colorHistory.length - 4; i++) {
        if (colorHistory[i] === last3Colors[0] && colorHistory[i+1] === last3Colors[1] && colorHistory[i+2] === last3Colors[2]) {
            const next = colorHistory[i+3];
            colorMatches.set(next, (colorMatches.get(next) || 0) + 15);
        }
    }
    const sortedColors = Array.from(colorMatches.entries()).sort((a, b) => b[1] - a[1]);
    const likelyColor = sortedColors.length > 0 ? sortedColors[0][0] : colorHistory.filter((c, idx) => idx > colorHistory.length - 6).sort((a,b) => colorHistory.filter(v => v===a).length - colorHistory.filter(v => v===b).length)[0];

    if (likelyColor) {
        ROULETTE_NUMBERS.forEach(n => {
            if (NUMBER_COLORS[n] === likelyColor) scores.set(n, (scores.get(n) || 0) + 10);
        });
    }

    // 2. FINAL DIGIT TRANSITION (Weight 20)
    const digitTrans: Map<number, number> = new Map();
    for (let i = 0; i < history.length - 1; i++) {
        if (history[i] % 10 === lastFinalDigit) {
            const nextD = history[i+1] % 10;
            digitTrans.set(nextD, (digitTrans.get(nextD) || 0) + 1);
        }
    }
    const predictedFinalDigits = Array.from(digitTrans.entries())
        .filter(([_, count]) => count >= 1)
        .sort((a,b) => b[1] - a[1])
        .slice(0, 3)
        .map(([d]) => d);

    predictedFinalDigits.forEach((d, idx) => {
        ROULETTE_NUMBERS.forEach(n => {
            if (n % 10 === d) scores.set(n, (scores.get(n) || 0) + (20 - idx * 4));
        });
    });

    // 3. SECTOR ARC BIAS (Weight 25)
    const seriesTrans: Map<SeriesType, number> = new Map();
    for (let i = 0; i < seriesHistory.length - 1; i++) {
        if (seriesHistory[i] === lastSeries) {
            const nextS = seriesHistory[i+1];
            // Fix: remove nested Map.set call that was passing a Map instead of a number
            if (nextS !== 'none') seriesTrans.set(nextS, (seriesTrans.get(nextS) || 0) + 1);
        }
    }
    const sortedSeries = Array.from(seriesTrans.entries()).sort((a,b) => b[1] - a[1]);
    const predictedSeries = sortedSeries.length > 0 ? sortedSeries[0][0] : lastSeries;

    if (predictedSeries !== 'none') {
        ROULETTE_NUMBERS.forEach(n => {
            if (getSeriesType(n) === predictedSeries) scores.set(n, (scores.get(n) || 0) + 15);
        });
    }

    // 4. NUMBER REPEAT SEQUENCES (Weight 40)
    // Last 2 numbers
    const last2 = history.slice(-2);
    for (let i = 0; i <= history.length - 3; i++) {
        if (history[i] === last2[0] && history[i+1] === last2[1]) {
            const next = history[i+2];
            scores.set(next, (scores.get(next) || 0) + 40);
        }
    }

    // 5. WHEEL GEOMETRY BIAS (GENIUS ADDITION)
    // If a certain area of the wheel is hitting frequently, weight the center of that area
    const wheelIndices = history.slice(-5).map(n => EUROPEAN_WHEEL_ORDER.indexOf(n));
    const avgWheelPos = Math.round(wheelIndices.reduce((a,b) => a+b, 0) / wheelIndices.length);
    const geometryTarget = EUROPEAN_WHEEL_ORDER[avgWheelPos % 37];
    const geometricNeighbors = getNeighbours(geometryTarget, 2);
    geometricNeighbors.forEach(n => scores.set(n, (scores.get(n) || 0) + 12));

    // 6. CONVERGENCE FILTERING
    // Numbers that match multiple criteria get a multiplier
    ROULETTE_NUMBERS.forEach(n => {
        let convergenceBonus = 1;
        if (NUMBER_COLORS[n] === likelyColor) convergenceBonus += 0.2;
        if (predictedFinalDigits.includes(n % 10)) convergenceBonus += 0.3;
        if (getSeriesType(n) === predictedSeries) convergenceBonus += 0.2;
        scores.set(n, (scores.get(n) || 0) * convergenceBonus);
    });

    // Final Sort and Neighbor Expansion for Accuracy
    let rawTop = Array.from(scores.entries())
        .sort((a,b) => b[1] - a[1])
        .filter(e => e[1] > 0)
        .slice(0, 3);

    // If we have a very strong top candidate, ensure its physical wheel neighbors are also considered
    if (rawTop.length > 0 && rawTop[0][1] > 30) {
        const primary = rawTop[0][0];
        const neighbors = getNeighbours(primary, 1);
        neighbors.forEach(n => {
            if (!rawTop.some(e => e[0] === n)) {
                const neighborScore = scores.get(n) || 0;
                scores.set(n, neighborScore + (rawTop[0][1] * 0.4)); // Boost neighbors of king number
            }
        });
        // Re-sort after neighbor boost
        rawTop = Array.from(scores.entries())
            .sort((a,b) => b[1] - a[1])
            .slice(0, 3);
    }

    return {
        series: predictedSeries,
        topNumbers: rawTop.map(([num, score]) => ({
            num,
            confidence: Math.min(99, Math.round((score / 80) * 100))
        })),
        color: likelyColor,
        finalDigits: predictedFinalDigits
    };
  }, [spinHistory]);

  const handleAddSpin = useCallback((num: number) => {
    const now = Date.now();
    if (now - lastInputTime.current < INPUT_THROTTLE_MS) return;
    lastInputTime.current = now;

    // Evaluate last prediction before adding new spin
    if (prediction) {
        const hitData = {
            color: prediction.color === NUMBER_COLORS[num],
            final: prediction.finalDigits.includes(num % 10),
            series: prediction.series === getSeriesType(num),
            top: prediction.topNumbers.some(tn => tn.num === num)
        };
        setLastHitStatus(hitData);
        if (hitData.color || hitData.final || hitData.series || hitData.top) {
            triggerHaptic('success');
        } else {
            triggerHaptic('medium');
        }
    } else {
        triggerHaptic('medium');
    }

    const newHistory = [...spinHistory, num];
    setSpinHistory(newHistory);
    if (newHistory.length >= MIN_SPINS_FOR_PATTERNS) {
        const alertsFromCheck = checkForAlerts(newHistory);
        if (alertsFromCheck.length > 0) {
            const freshAlerts = alertsFromCheck.map((alert, index) => ({ ...alert, id: Date.now() + index })).reverse();
            setAlerts(currentAlerts => [...freshAlerts, ...currentAlerts].slice(0, 5));
        }
    }
  }, [spinHistory, checkForAlerts, prediction]);

  const handleRemoveLastSpin = useCallback(() => {
    if (spinHistory.length === 0) return;
    const now = Date.now();
    if (now - lastInputTime.current < INPUT_THROTTLE_MS) return;
    lastInputTime.current = now;
    triggerHaptic('light');
    const newHistory = spinHistory.slice(0, -1);
    setSpinHistory(newHistory);
    setLastHitStatus(null);
    setAlerts(currentAlerts => currentAlerts.filter(alert => {
        const lastSpin = spinHistory[spinHistory.length - 1];
        const trigger = alert.trigger;
        if (trigger.length === 1 && trigger[0] === lastSpin) return false;
        if (trigger.length === 2 && trigger[1] === lastSpin) return false;
        return true;
    }));
  }, [spinHistory]);

  const handleRemoveAlert = (id: number) => {
    triggerHaptic('light');
    setAlerts(currentAlerts => currentAlerts.filter(alert => alert.id !== id));
  };

  const handleClearSession = () => {
    triggerHaptic('error');
    setSpinHistory([]);
    setAlerts([]);
    setLastHitStatus(null);
    localStorage.removeItem(SESSION_STORAGE_KEY);
    setShowClearConfirmation(false);
  };

  const switchPage = (page: PageType) => {
    triggerHaptic('light');
    setCurrentPage(page);
  };

  return (
    <div className="min-h-screen text-gray-800 dark:text-gray-200 font-sans selection:bg-gold/30 flex flex-col overflow-hidden">
      {/* Safe Area Header */}
      <header className="bg-white/80 dark:bg-gray-900/80 backdrop-blur-md sticky top-0 z-40 shadow-sm border-b border-gray-200 dark:border-gray-800 pt-[env(safe-area-inset-top)]">
        <div className="container mx-auto px-4 py-1.5 flex justify-between items-center h-11">
          <h1 className="text-base font-bold text-gray-900 dark:text-white" style={{fontFamily: "'Playfair Display', serif"}}>
            Roulette <span className="text-gold">Tracker</span>
          </h1>
          <div className="flex items-center space-x-1.5">
            <button type="button" onClick={() => switchPage('info')} className="p-1 rounded-lg text-gray-500 border border-gray-200 dark:border-gray-700 active:scale-95" title="Help & Info">
              <InfoIcon />
            </button>
            <button type="button" onClick={() => switchPage(currentPage === 'vip' ? 'main' : 'vip')} className={`p-1 rounded-lg transition-all flex items-center space-x-1 border active:scale-95 ${currentPage === 'vip' ? 'bg-gold text-black border-gold' : 'text-gold border-gold/20'}`}>
              <CrownIcon />
              <span className="text-[10px] font-black uppercase tracking-tighter">VIP</span>
            </button>
            <button onClick={toggleTheme} className="p-1 rounded-lg text-gray-600 dark:text-gray-300 border border-gray-200 dark:border-gray-700 active:scale-95">
              {theme === 'light' ? <MoonIcon /> : <SunIcon />}
            </button>
          </div>
        </div>
      </header>

      {/* Main content */}
      <main className="flex-1 overflow-y-auto overflow-x-hidden custom-scrollbar pb-[env(safe-area-inset-bottom)]">
        <div className="container mx-auto px-1.5 py-2 max-w-5xl">
            {currentPage === 'main' ? (
            <div className="flex flex-col gap-1.5 animate-fade-in">
                <div className="w-full bg-white dark:bg-gray-800 p-2 rounded-xl shadow-md border border-gray-100 dark:border-gray-700/50">
                    <NumberGrid onNumberSelect={handleAddSpin} disabled={false} />
                </div>

                {/* Compact Strategy Dashboard */}
                <div className="bg-white dark:bg-gray-800 p-1.5 rounded-xl shadow-md border border-gray-100 dark:border-gray-700/50">
                    <div className="flex flex-wrap items-center justify-between gap-x-3 gap-y-1 mb-1 px-1">
                        <div className="flex items-center gap-2">
                            <h2 className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Strategy</h2>
                            <button onClick={() => setIsStrategyEnabled(!isStrategyEnabled)} className={`relative inline-flex items-center h-3.5 rounded-full w-7 transition-colors ${isStrategyEnabled ? 'bg-roulette-green' : 'bg-gray-400 dark:bg-gray-600'}`}>
                                <span className={`inline-block w-2.5 h-2.5 transform bg-white rounded-full transition-transform ${isStrategyEnabled ? 'translate-x-3.5' : 'translate-x-1'}`} />
                            </button>
                        </div>

                        <div className="flex items-center gap-2">
                             <div className="flex items-center gap-1 bg-gray-50 dark:bg-gray-900/40 p-0.5 px-1.5 rounded-lg border border-gray-100 dark:border-gray-700/30">
                                <span className="text-[9px] font-black text-gray-400 uppercase tracking-tighter">Unit:</span>
                                <input type="number" value={unitMultiplierInput} onChange={(e) => {
                                        setUnitMultiplierInput(e.target.value);
                                        const num = parseInt(e.target.value, 10);
                                        if (!isNaN(num) && num > 0) setUnitMultiplier(num);
                                    }} onBlur={() => {
                                        const num = parseInt(unitMultiplierInput, 10);
                                        if (isNaN(num) || num < 1) { setUnitMultiplierInput('1'); setUnitMultiplier(1); }
                                    }} disabled={!isStrategyEnabled} className="w-8 bg-transparent text-center font-black text-[11px] outline-none disabled:opacity-40" />
                            </div>

                            <div className="flex bg-gray-50 dark:bg-gray-900/40 rounded-lg p-0.5 border border-gray-100 dark:border-gray-700/30">
                                <button onClick={() => {triggerHaptic('light'); setNeighbourDepth(3)}} disabled={!isStrategyEnabled} className={`px-2 py-0.5 text-[9px] font-black rounded ${neighbourDepth === 3 ? 'bg-gold text-black' : 'text-gray-500'}`}>N3</button>
                                <button onClick={() => {triggerHaptic('light'); setNeighbourDepth(5)}} disabled={!isStrategyEnabled} className={`px-2 py-0.5 text-[9px] font-black rounded ${neighbourDepth === 5 ? 'bg-gold text-black' : 'text-gray-500'}`}>N5</button>
                            </div>

                            <button onClick={() => {triggerHaptic('light'); setBetStrategyMode(m => m === '235' ? '123' : m === '123' ? '111' : '235')}} disabled={!isStrategyEnabled} className={`px-2 py-0.5 text-[9px] font-black rounded transition-all shadow-sm ${betStrategyMode === '235' ? 'bg-green-600 text-white' : betStrategyMode === '123' ? 'bg-yellow-500 text-black' : 'bg-blue-600 text-white'} disabled:opacity-30`}>{betStrategyMode}</button>
                        </div>
                    </div>

                    {isStrategyEnabled && (
                        <div className="animate-fade-in space-y-1.5">
                            {spinHistory.length >= 8 ? (
                                <>
                                    <div className="flex justify-between items-center py-1 border-t border-gray-100 dark:border-gray-700/50">
                                        <div className="text-[10px] font-black uppercase tracking-tighter">
                                            <span className="text-gray-400">P/L: </span>
                                            <span className={balance >= 0 ? 'text-green-500' : 'text-red-500'}>{balance >= 0 ? '+' : ''}{balance}</span>
                                        </div>
                                        {bettingMap.size > 0 && (
                                            <div className="text-[10px] font-black text-gray-500 dark:text-gray-400 uppercase tracking-tighter">
                                                Bet: <span className="text-gold text-xs">{totalBaseBetUnits * unitMultiplier}</span>
                                            </div>
                                        )}
                                    </div>
                                    <BettingChart bettingMap={bettingMap} />
                                </>
                            ) : (
                                <div className="border-t border-gray-100 dark:border-gray-700/50 pt-1.5 pb-0.5 text-center">
                                    <p className="text-[9px] text-gray-400 font-bold uppercase tracking-widest italic animate-pulse">Waiting ({8 - spinHistory.length})</p>
                                </div>
                            )}
                        </div>
                    )}
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-1.5">
                    <div className="bg-white dark:bg-gray-800 p-2 rounded-xl shadow-md border border-gray-100 dark:border-gray-700/50">
                        <div className="flex justify-between items-center mb-1.5">
                            <h2 className="text-[10px] font-black uppercase text-gray-400 tracking-widest">History ({spinHistory.length})</h2>
                            <PredictionDisplay prediction={prediction} lastHitStatus={lastHitStatus} />
                        </div>
                        {spinHistory.length > 0 ? <SpinHistory history={spinHistory} /> : <p className="text-gray-400 text-center py-4 text-[9px] font-black uppercase italic tracking-widest">Empty</p>}
                    </div>
                    <div className="bg-white dark:bg-gray-800 p-2 rounded-xl shadow-md border border-gray-100 dark:border-gray-700/50">
                        <h2 className="text-[10px] font-black uppercase text-gray-400 tracking-widest mb-1.5">Alerts</h2>
                        <ToastContainer toasts={alerts} onRemoveToast={handleRemoveAlert} />
                    </div>
                </div>

                <div className="bg-white dark:bg-gray-800 p-2 rounded-xl shadow-md border border-gray-100 dark:border-gray-700/50 mt-0.5 mb-2">
                    <div className="flex items-center justify-between gap-1.5">
                        <div className="flex items-center gap-2 bg-gray-100 dark:bg-gray-900/50 px-2 py-1.5 rounded-lg flex-1 border border-gray-200 dark:border-gray-700/50">
                            <span className="text-[10px] font-black uppercase tracking-widest text-gray-500">Alerts</span>
                            <button onClick={() => {triggerHaptic('light'); setAlertsEnabled(!alertsEnabled)}} className={`relative inline-flex items-center h-3.5 rounded-full w-7 transition-colors ${alertsEnabled ? 'bg-roulette-green' : 'bg-gray-400 dark:bg-gray-600'}`}>
                                <span className={`inline-block w-2.5 h-2.5 transform bg-white rounded-full transition-transform ${alertsEnabled ? 'translate-x-3.5' : 'translate-x-1'}`}/>
                            </button>
                        </div>
                        <div className="flex gap-1.5 flex-1">
                            <button onClick={handleRemoveLastSpin} disabled={spinHistory.length === 0} className="flex-1 bg-yellow-500 text-black font-black py-1.5 rounded-lg hover:bg-yellow-600 disabled:opacity-40 text-[10px] uppercase tracking-widest transition-all active:scale-95">Undo</button>
                            <button onClick={() => {triggerHaptic('medium'); setShowClearConfirmation(true)}} className="flex-1 bg-roulette-red text-white font-black py-1.5 rounded-lg hover:bg-red-700 text-[10px] uppercase tracking-widest transition-all active:scale-95">Clear</button>
                        </div>
                    </div>
                </div>
            </div>
            ) : currentPage === 'vip' ? (
            <div className="animate-slide-up">
                <VipPage spinHistory={spinHistory} onBack={() => switchPage('main')} prediction={prediction} />
            </div>
            ) : (
            <div className="animate-slide-up">
                <IntroductionPage onBack={() => switchPage('main')} />
            </div>
            )}
        </div>
      </main>
      <ConfirmationModal isOpen={showClearConfirmation} onClose={() => setShowClearConfirmation(false)} onConfirm={handleClearSession} title="Clear Records" message="This will clear all history and patterns. Continue?" />
    </div>
  );
};

const SunIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z" />
    </svg>
);
const MoonIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z" />
    </svg>
);
const CrownIcon = () => (
  <svg xmlns="http://www.w3.org/2000/svg" className="h-3.5 w-3.5" viewBox="0 0 24 24" fill="currentColor">
    <path d="M5 16L3 5l5.5 5L12 4l3.5 6L21 5l-2 11H5zm14 3c0 .55-.45 1-1 1H6c-.55 0-1-.45-1-1v-1h14v1z"></path>
  </svg>
);
const InfoIcon = () => (
    <div className="w-3.5 h-3.5 rounded border-2 border-current flex items-center justify-center font-black text-[9px]">
        ?
    </div>
);

export default App;

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { NumberGrid } from './components/NumberGrid';
import { SpinHistory } from './components/SpinHistory';
import { BettingChart } from './components/BettingChart';
import { ToastContainer } from './components/Toast';
import { VipPage } from './components/VipPage';
import { IntroductionPage } from './components/IntroductionPage';
import { ConfirmationModal } from './components/ConfirmationModal';
import type { ToastData, SeriesType, ComplexPrediction, RouletteColor } from './types';
import { getNeighbours, getSeriesType } from './utils/roulette';
import { PredictionDisplay } from './components/PredictionDisplay';
import { NUMBER_COLORS, ROULETTE_NUMBERS, EUROPEAN_WHEEL_ORDER } from './constants';

const MIN_SPINS_FOR_PATTERNS = 6;
const SESSION_STORAGE_KEY = 'rouletteSession_v3';
const INPUT_THROTTLE_MS = 400;

type PageType = 'main' | 'vip' | 'info';

export interface HitStatus {
    color: boolean;
    final: boolean;
    series: boolean;
    top: boolean;
}

const App: React.FC = () => {
  const [theme, setTheme] = useState<'light' | 'dark'>('dark');
  const [spinHistory, setSpinHistory] = useState<number[]>([]);
  const [alerts, setAlerts] = useState<ToastData[]>([]);
  const [alertsEnabled, setAlertsEnabled] = useState<boolean>(true);
  const [currentPage, setCurrentPage] = useState<PageType>('main');
  const [showClearConfirmation, setShowClearConfirmation] = useState<boolean>(false);
  const [bettingMap, setBettingMap] = useState<Map<number, number>>(new Map());
  const [balance, setBalance] = useState<number>(0);
  const [lastHitStatus, setLastHitStatus] = useState<HitStatus | null>(null);

  const lastInputTime = useRef<number>(0);

  const [isStrategyEnabled, setIsStrategyEnabled] = useState<boolean>(true);
  const [unitMultiplier, setUnitMultiplier] = useState<number>(1);
  const [unitMultiplierInput, setUnitMultiplierInput] = useState<string>('1');
  const [betStrategyMode, setBetStrategyMode] = useState<'235' | '123' | '111'>('235');
  const [neighbourDepth, setNeighbourDepth] = useState<3 | 5>(3);

  const triggerHaptic = (type: 'light' | 'medium' | 'heavy' | 'error' | 'success') => {
    if (!('vibrate' in navigator)) return;
    switch (type) {
      case 'light': navigator.vibrate(10); break;
      case 'medium': navigator.vibrate(25); break;
      case 'heavy': navigator.vibrate(50); break;
      case 'success': navigator.vibrate([30, 50, 30]); break;
      case 'error': navigator.vibrate([40, 30, 40]); break;
    }
  };

  useEffect(() => {
    const savedData = localStorage.getItem(SESSION_STORAGE_KEY);
    if (savedData) {
        try {
            const parsed = JSON.parse(savedData);
            if (parsed.history) setSpinHistory(parsed.history);
            if (parsed.alerts) setAlerts(parsed.alerts);
            if (parsed.multiplier) {
                setUnitMultiplier(parsed.multiplier);
                setUnitMultiplierInput(parsed.multiplier.toString());
            }
            if (parsed.strategyMode) setBetStrategyMode(parsed.strategyMode);
            if (parsed.depth) setNeighbourDepth(parsed.depth);
            if (parsed.strategyEnabled !== undefined) setIsStrategyEnabled(parsed.strategyEnabled);
            if (parsed.theme) setTheme(parsed.theme);
        } catch (error) {
            console.error("Failed to restore session:", error);
        }
    }
  }, []);

  useEffect(() => {
    const sessionData = {
        history: spinHistory,
        alerts: alerts,
        multiplier: unitMultiplier,
        strategyMode: betStrategyMode,
        depth: neighbourDepth,
        strategyEnabled: isStrategyEnabled,
        theme: theme
    };
    localStorage.setItem(SESSION_STORAGE_KEY, JSON.stringify(sessionData));
  }, [spinHistory, alerts, unitMultiplier, betStrategyMode, neighbourDepth, isStrategyEnabled, theme]);

  const calculateBets = useCallback((history: number[], mode: '235' | '123' | '111', depth: 3 | 5): Map<number, number> => {
    const newBettingMap = new Map<number, number>();
    const uniqueHistoryByRecency = [...new Set([...history].reverse())];
    if (uniqueHistoryByRecency.length < 2) return newBettingMap;
    const masterCandidatePool: number[] = [];
    uniqueHistoryByRecency.forEach(num => {
      if (num !== -1) {
        const depthVal = depth === 5 ? 2 : 1;
        masterCandidatePool.push(...getNeighbours(num, depthVal));
      }
    });
    const finalCandidates = [...new Set(masterCandidatePool)].filter(n => n !== -1);
    if (mode === '111') {
        finalCandidates.slice(0, 20).forEach(candidate => newBettingMap.set(candidate, 1));
        return newBettingMap;
    }
    const bet5 = new Set<number>();
    const bet3 = new Set<number>();
    const bet2 = new Set<number>();
    const alreadyBetOn = new Set<number>();
    for (const candidate of finalCandidates) {
      if (alreadyBetOn.has(candidate)) continue;
      if (bet5.size < 4) bet5.add(candidate);
      else if (bet3.size < 6) bet3.add(candidate);
      else if (bet2.size < 10) bet2.add(candidate);
      alreadyBetOn.add(candidate);
      if (bet2.size >= 10) break;
    }
    const units = mode === '235' ? [5, 3, 2] : [3, 2, 1];
    bet5.forEach(num => newBettingMap.set(num, units[0]));
    bet3.forEach(num => newBettingMap.set(num, units[1]));
    bet2.forEach(num => newBettingMap.set(num, units[2]));
    return newBettingMap;
  }, []);

  useEffect(() => {
      if (spinHistory.length > 0) {
          setBettingMap(calculateBets(spinHistory, betStrategyMode, neighbourDepth));
      } else {
          setBettingMap(new Map());
      }
  }, [spinHistory, betStrategyMode, neighbourDepth, calculateBets]);

  const totalBaseBetUnits = useMemo(() => {
    let total = 0;
    for (const unit of bettingMap.values()) total += unit;
    return total;
  }, [bettingMap]);

  useEffect(() => {
    if (!isStrategyEnabled) {
        setBalance(0);
        return;
    }
    let cumulativeBaseBalance = 0;
    for (let i = 8; i < spinHistory.length; i++) {
        const historySliceForBetting = spinHistory.slice(0, i);
        const winningNumber = spinHistory[i];
        const betsForThisRound = calculateBets(historySliceForBetting, betStrategyMode, neighbourDepth);
        const totalBaseBetForThisRound = (Array.from(betsForThisRound.values()) as number[]).reduce((sum, val) => sum + val, 0);
        if (totalBaseBetForThisRound > 0) {
            const betOnWinningNumber = betsForThisRound.get(winningNumber) || 0;
            const profitOrLoss = betOnWinningNumber > 0 
                ? (betOnWinningNumber * 36) - totalBaseBetForThisRound 
                : -totalBaseBetForThisRound;
            cumulativeBaseBalance += profitOrLoss;
        }
    }
    setBalance(cumulativeBaseBalance * unitMultiplier);
  }, [spinHistory, calculateBets, isStrategyEnabled, unitMultiplier, betStrategyMode, neighbourDepth]);

  useEffect(() => {
    if (theme === 'dark') document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
  }, [theme]);

  const toggleTheme = () => {
    triggerHaptic('light');
    setTheme(prevTheme => (prevTheme === 'light' ? 'dark' : 'light'));
  };

  const checkForAlerts = useCallback((history: number[]): Omit<ToastData, 'id'>[] => {
    if (history.length < MIN_SPINS_FOR_PATTERNS || !alertsEnabled) return [];
    const newAlerts: Omit<ToastData, 'id'>[] = [];
    const lastSpin = history[history.length - 1];
    const predictions = new Map<string, number[]>();
    for (let i = 0; i <= history.length - 3; i++) {
      if (history[i] === lastSpin) {
        const prediction = [history[i + 1], history[i + 2]];
        predictions.set(prediction.join(','), prediction);
      }
    }
     for (let i = 0; i <= history.length - 2; i++) {
        if (history[i] === lastSpin) {
            if (history.length > i + 1 && !predictions.has(`${history[i+1]}`)) {
                 const prediction = [history[i+1]];
                 if(!Array.from(predictions.values()).some(p => p.length === 2 && p[0] === prediction[0])) {
                     predictions.set(prediction.join(','), prediction);
                 }
            }
        }
    }
    if (predictions.size > 0) newAlerts.push({ trigger: [lastSpin], predictions: Array.from(predictions.values()) });
    if (history.length > 1) {
      const lastTwoSpins = history.slice(-2);
      const twoSpinPredictions = new Map<string, number[]>();
      for (let i = 0; i <= history.length - 3; i++) {
        if (history[i] === lastTwoSpins[0] && history[i + 1] === lastTwoSpins[1]) {
          const prediction = [history[i + 2]];
          twoSpinPredictions.set(prediction.join(','), prediction);
        }
      }
      if(twoSpinPredictions.size > 0) newAlerts.push({ trigger: lastTwoSpins, predictions: Array.from(twoSpinPredictions.values()) });
    }
    return newAlerts;
  }, [alertsEnabled]);

  const prediction = useMemo<ComplexPrediction | null>(() => {
    if (spinHistory.length < 5) return null;

    const history = spinHistory;
    const seriesHistory = history.map(getSeriesType);
    const colorHistory = history.map(n => NUMBER_COLORS[n]);
    const lastNumber = history[history.length - 1];
    const lastFinalDigit = lastNumber % 10;
    const lastSeries = seriesHistory[seriesHistory.length - 1];

    const scores: Map<number, number> = new Map();
    ROULETTE_NUMBERS.forEach(n => scores.set(n, 0));

    // 1. GENIUS COLOR ANALYSIS (Weight 15)
    const colorVotes: Map<RouletteColor, number> = new Map();
    const colorString = colorHistory.join(',');
    const last3Colors = colorHistory.slice(-3).join(',');

    // Find color sequence matches
    for (let i = 0; i <= colorHistory.length - 4; i++) {
        if (colorHistory.slice(i, i+3).join(',') === last3Colors) {
            const next = colorHistory[i+3];
            colorVotes.set(next, (colorVotes.get(next) || 0) + 15);
        }
    }
    const likelyColor = Array.from(colorVotes.entries()).sort((a,b) => b[1]-a[1])[0]?.[0] || 
                      (colorHistory.slice(-5).filter(c => c === 'red').length > 3 ? 'black' : 
                       colorHistory.slice(-5).filter(c => c === 'black').length > 3 ? 'red' : null);

    // 2. GENIUS FINAL DIGIT TRANSITIONS (Weight 25)
    const digitVotes: Map<number, number> = new Map();
    for (let i = 0; i < history.length - 1; i++) {
        if (history[i] % 10 === lastFinalDigit) {
            const nextDigit = history[i+1] % 10;
            digitVotes.set(nextDigit, (digitVotes.get(nextDigit) || 0) + 10);
        }
    }
    // Add "Neighbor Digits" (e.g., if 3 is hot, 2 and 4 get a small boost)
    const sortedDigits = Array.from(digitVotes.entries()).sort((a,b) => b[1]-a[1]);
    const topFinals = sortedDigits.slice(0, 3).map(d => d[0]);

    // 3. GENIUS SECTOR ARC FLOW (Weight 20)
    const sectorVotes: Map<SeriesType, number> = new Map();
    for (let i = 0; i < seriesHistory.length - 1; i++) {
        if (seriesHistory[i] === lastSeries) {
            const nextSeries = seriesHistory[i+1];
            if (nextSeries !== 'none') sectorVotes.set(nextSeries, (sectorVotes.get(nextSeries) || 0) + 10);
        }
    }
    const likelySeries = Array.from(sectorVotes.entries()).sort((a,b) => b[1]-a[1])[0]?.[0] || lastSeries;

    // 4. GENIUS WHEEL ARC CLUSTERING
    // Find the arc the ball is favoring physically
    const wheelPositions = history.slice(-5).map(n => EUROPEAN_WHEEL_ORDER.indexOf(n));
    const avgPos = Math.round(wheelPositions.reduce((a,b) => a+b, 0) / wheelPositions.length);
    const hotArcCenter = EUROPEAN_WHEEL_ORDER[avgPos % 37];
    const arcNumbers = getNeighbours(hotArcCenter, 3); // N7 Arc

    // 5. MASTER CONVERGENCE SCORING
    ROULETTE_NUMBERS.forEach(n => {
        let nScore = 0;

        // Base matches
        if (likelyColor && NUMBER_COLORS[n] === likelyColor) nScore += 5;
        if (topFinals.includes(n % 10)) nScore += 15;
        if (getSeriesType(n) === likelySeries) nScore += 10;
        if (arcNumbers.includes(n)) nScore += 10;

        // Pattern match (Golden sequence)
        const last2 = history.slice(-2);
        for (let i = 0; i <= history.length - 3; i++) {
            if (history[i] === last2[0] && history[i+1] === last2[1] && history[i+2] === n) {
                nScore += 40; // Massive weight for sequence repetition
            }
        }

        // GENIUS MULTIPLIER: If it hits multiple major criteria, boost it exponentially
        let comboCount = 0;
        if (topFinals.includes(n % 10)) comboCount++;
        if (getSeriesType(n) === likelySeries) comboCount++;
        if (arcNumbers.includes(n)) comboCount++;

        if (comboCount >= 2) nScore *= 1.5;
        if (comboCount >= 3) nScore *= 2.0;

        scores.set(n, nScore);
    });

    // 6. NEAR-MISS NEIGHBOR BOOST
    // If we have a very strong candidate, its pocket neighbors are statistically more likely
    const tempSorted = Array.from(scores.entries()).sort((a,b) => b[1]-a[1]);
    if (tempSorted[0] && tempSorted[0][1] > 20) {
        const primary = tempSorted[0][0];
        const wheelNeighbors = getNeighbours(primary, 1); // Immediate neighbors
        wheelNeighbors.forEach(nb => {
            scores.set(nb, (scores.get(nb) || 0) + (tempSorted[0][1] * 0.4));
        });
    }

    const finalTop = Array.from(scores.entries())
        .sort((a,b) => b[1]-a[1])
        .slice(0, 3)
        .map(([num, score]) => ({
            num,
            confidence: Math.min(99, Math.max(10, Math.round((score / 85) * 100)))
        }));

    return {
        series: likelySeries,
        topNumbers: finalTop,
        color: likelyColor,
        finalDigits: topFinals
    };
  }, [spinHistory]);

  const handleAddSpin = useCallback((num: number) => {
    const now = Date.now();
    if (now - lastInputTime.current < INPUT_THROTTLE_MS) return;
    lastInputTime.current = now;

    if (prediction) {
        setLastHitStatus({
            color: prediction.color === NUMBER_COLORS[num],
            final: prediction.finalDigits.includes(num % 10),
            series: prediction.series === getSeriesType(num),
            top: prediction.topNumbers.some(tn => tn.num === num)
        });
    }

    const newHistory = [...spinHistory, num];
    setSpinHistory(newHistory);
    triggerHaptic(prediction?.topNumbers.some(t => t.num === num) ? 'success' : 'medium');

    if (newHistory.length >= MIN_SPINS_FOR_PATTERNS) {
        const alertsFromCheck = checkForAlerts(newHistory);
        if (alertsFromCheck.length > 0) {
            const freshAlerts = alertsFromCheck.map((alert, index) => ({ ...alert, id: Date.now() + index })).reverse();
            setAlerts(currentAlerts => [...freshAlerts, ...currentAlerts].slice(0, 5));
        }
    }
