                    </div>
                    <div className="bg-white dark:bg-gray-800 p-2 rounded-xl shadow-md border border-gray-100 dark:border-gray-700/50">
                        <h2 className="text-[10px] font-black uppercase text-gray-400 tracking-widest mb-1.5">Alerts</h2>
                        <ToastContainer toasts={alerts} onRemoveToast={handleRemoveAlert} />
                    </div>
                </div>

                <div className="bg-white dark:bg-gray-800 p-2 rounded-xl shadow-md border border-gray-100 dark:border-gray-700/50 mt-0.5 mb-2">
                    <div className="flex items-center justify-between gap-1.5">
                        <div className="flex items-center gap-2 bg-gray-100 dark:bg-gray-900/50 px-2 py-1.5 rounded-lg flex-1 border border-gray-200 dark:border-gray-700/50">
                            <span className="text-[10px] font-black uppercase tracking-widest text-gray-500">Alerts</span>
                            <button onClick={() => {triggerHaptic('light'); setAlertsEnabled(!alertsEnabled)}} className={`relative inline-flex items-center h-3.5 rounded-full w-7 transition-colors ${alertsEnabled ? 'bg-roulette-green' : 'bg-gray-400 dark:bg-gray-600'}`}>
                                <span className={`inline-block w-2.5 h-2.5 transform bg-white rounded-full transition-transform ${alertsEnabled ? 'translate-x-3.5' : 'translate-x-1'}`}/>
                            </button>
                        </div>
                        <div className="flex gap-1.5 flex-1">
                            <button onClick={handleRemoveLastSpin} disabled={spinHistory.length === 0} className="flex-1 bg-yellow-500 text-black font-black py-1.5 rounded-lg hover:bg-yellow-600 disabled:opacity-40 text-[10px] uppercase tracking-widest transition-all active:scale-95">Undo</button>
                            <button onClick={() => {triggerHaptic('medium'); setShowClearConfirmation(true)}} className="flex-1 bg-roulette-red text-white font-black py-1.5 rounded-lg hover:bg-red-700 text-[10px] uppercase tracking-widest transition-all active:scale-95">Clear</button>
                        </div>
                    </div>
                </div>
            </div>
            ) : currentPage === 'vip' ? (
            <div className="animate-slide-up">
                <VipPage spinHistory={spinHistory} onBack={() => switchPage('main')} prediction={prediction} />
            </div>
            ) : (
            <div className="animate-slide-up">
                <IntroductionPage onBack={() => switchPage('main')} />
            </div>
            )}
        </div>
      </main>
      <ConfirmationModal isOpen={showClearConfirmation} onClose={() => setShowClearConfirmation(false)} onConfirm={handleClearSession} title="Clear Records" message="This will clear all history and patterns. Continue?" />
    </div>
  );
};

