    </svg>
);

const HotNumbers: React.FC<{ history: number[] }> = ({ history }) => {
    const hotNumbers = useMemo(() => {
        if (history.length === 0) return [];
        const counts = new Map<number, number>();
        history.forEach(num => counts.set(num, (counts.get(num) || 0) + 1));
        return Array.from(counts.entries()).sort((a, b) => b[1] - a[1]).slice(0, 5);
    }, [history]);

    if (hotNumbers.length === 0) {
        return <div className="flex items-center justify-center h-16"><p className="text-center text-gray-500 dark:text-gray-400 font-bold text-xs uppercase tracking-widest italic">Insufficient data</p></div>;
    }

    const colorClasses = {
        red: 'bg-roulette-red text-white',
        black: 'bg-roulette-black text-white',
        green: 'bg-roulette-green text-white',
    };

    return (
        <div className="flex justify-start items-start text-center gap-4 py-2 custom-scrollbar overflow-x-auto">
            {hotNumbers.map(([num, count], index) => (
                <div key={num} className="flex flex-col items-center flex-shrink-0">
                    <span className="font-black text-[9px] text-gold mb-1 uppercase tracking-tighter">Rank {index + 1}</span>
                    <div className={`w-9 h-9 rounded-2xl flex items-center justify-center font-black text-sm shadow-md ${colorClasses[NUMBER_COLORS[num]]}`}>
                        {num}
                    </div>
                    <div className="mt-1.5 text-[10px] font-black text-gray-700 dark:text-gray-300 uppercase tracking-tighter">{count} Hits</div>
                </div>
            ))}
        </div>
    );
};

