interface VipPageProps {
    spinHistory: number[];
    onBack: () => void;
    prediction: ComplexPrediction | null;
}

export const VipPage: React.FC<VipPageProps> = ({ spinHistory, onBack, prediction }) => {
    const reportStats = useMemo(() => {
        const stats = {
            color: { offered: 0, wins: 0 },
            final: { offered: 0, wins: 0 },
            series: { offered: 0, wins: 0 },
            top: { offered: 0, wins: 0 }
        };
        if (spinHistory.length < 10) return stats;

        for (let j = 8; j < spinHistory.length; j++) {
            const h = spinHistory.slice(0, j);
            const winner = spinHistory[j];
            const lastN = h[h.length - 1];

            // Consensus layers matching App.tsx
            const colorHistory = h.map(n => NUMBER_COLORS[n]);
            const seriesHistory = h.map(getSeriesType);

            // 1. Color Logic
            const cVotes: Map<RouletteColor, number> = new Map();
            const last3C = colorHistory.slice(-3).join(',');
            for (let i = 0; i <= colorHistory.length - 4; i++) {
                if (colorHistory.slice(i, i+3).join(',') === last3C) {
                    cVotes.set(colorHistory[i+3], (cVotes.get(colorHistory[i+3]) || 0) + 1);
                }
            }
            const pColor = Array.from(cVotes.entries()).sort((a,b) => b[1]-a[1])[0]?.[0];
            if (pColor) {
                stats.color.offered++;
                if (pColor === NUMBER_COLORS[winner]) stats.color.wins++;
            }

            // 2. Final Logic (2+ hits rule)
            const dVotes: Map<number, number> = new Map();
            const lastFD = lastN % 10;
            for (let i = 0; i < h.length - 1; i++) {
                if (h[i] % 10 === lastFD) {
                    const next = h[i+1] % 10;
                    dVotes.set(next, (dVotes.get(next) || 0) + 1);
                }
            }
            const pFinals = Array.from(dVotes.entries()).filter(([_, c]) => c >= 2).map(e => e[0]);
            if (pFinals.length > 0) {
                stats.final.offered++;
                if (pFinals.includes(winner % 10)) stats.final.wins++;
            }

            // 3. Series Logic
            const sVotes: Map<SeriesType, number> = new Map();
            const lastS = seriesHistory[seriesHistory.length-1];
            for (let i = 0; i < seriesHistory.length - 1; i++) {
                if (seriesHistory[i] === lastS) {
                    const next = seriesHistory[i+1];
                    if (next !== 'none') sVotes.set(next, (sVotes.get(next) || 0) + 1);
                }
            }
            const pSeries = Array.from(sVotes.entries()).sort((a,b) => b[1]-a[1])[0]?.[0];
            if (pSeries && pSeries !== 'none') {
                stats.series.offered++;
                if (pSeries === getSeriesType(winner)) stats.series.wins++;
            }

            // 4. Consensus Top Engine
            const scores: Map<number, number> = new Map();
            const startIdx = EUROPEAN_WHEEL_ORDER.indexOf(h[h.length-2] || 0);
            const endIdx = EUROPEAN_WHEEL_ORDER.indexOf(lastN);
            const disp = (endIdx - startIdx + 37) % 37;
            const targetIdx = (EUROPEAN_WHEEL_ORDER.indexOf(lastN) + disp) % 37;

            ROULETTE_NUMBERS.forEach(n => {
                let s = 0;
                const nIdx = EUROPEAN_WHEEL_ORDER.indexOf(n);
                if (pColor && NUMBER_COLORS[n] === pColor) s += 10;
                if (pFinals.includes(n % 10)) s += 30;
                if (pSeries && getSeriesType(n) === pSeries) s += 20;
                if (nIdx === targetIdx) s += 40;

                let overlaps = 0;
                if (pFinals.includes(n % 10)) overlaps++;
                if (pSeries && getSeriesType(n) === pSeries) overlaps++;
                if (nIdx === targetIdx) overlaps++;

                if (overlaps >= 2) s *= 1.8;
                scores.set(n, s);
            });

            const topPicks = Array.from(scores.entries()).sort((a,b) => b[1]-a[1]).slice(0, 3).map(e => e[0]);
            if (topPicks.length > 0) {
                stats.top.offered++;
                if (topPicks.includes(winner)) stats.top.wins++;
            }
        }
        return stats;
    }, [spinHistory]);

    return (
        <div className="animate-fade-in pb-12">
            <div className="flex items-center mb-6 mt-2">
                <button onClick={onBack} className="p-2.5 rounded-2xl bg-white dark:bg-gray-800 shadow-md hover:bg-gray-100 dark:hover:bg-gray-700 active:scale-95 transition-all mr-4 border border-gray-100 dark:border-gray-700" aria-label="Back">
                    <BackIcon />
                </button>
                <h2 className="text-2xl font-black" style={{fontFamily: "'Playfair Display', serif"}}>
                    VIP <span className="text-gold">Intelligence</span>
                </h2>
            </div>

            <div className="flex flex-col gap-6">
                <div className="bg-white dark:bg-gray-800 p-5 rounded-3xl shadow-xl border border-gray-100 dark:border-gray-700/50">
                    <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-widest mb-4">Sector Heatmap Tracking</h3>
                    <div className="h-64 sm:h-80">
                        <SeriesTracker history={spinHistory} />
                    </div>
                </div>

                <div className="bg-white dark:bg-gray-800 p-5 rounded-3xl shadow-xl border border-gray-100 dark:border-gray-700/50">
                    <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-widest mb-4">Final Digit Frequency Matrix</h3>
                    <FinalNumberMatrix history={spinHistory} />
                </div>

                <div className="bg-white dark:bg-gray-800 p-5 rounded-3xl shadow-xl border border-gray-100 dark:border-gray-700/50">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                        <div>
                            <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-widest mb-4">Hot Number Ranking</h3>
                            <HotNumbers history={spinHistory} />
                        </div>

                        <div className="flex flex-col">
                            <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-3">
                                High-Accuracy Consensus Performance
                                <div className="h-[1px] flex-1 bg-gray-100 dark:bg-gray-700/50"></div>
                            </h3>

                            <div className="grid grid-cols-2 gap-3">
                                <StatReportCard label="Color" wins={reportStats.color.wins} total={reportStats.color.offered} />
                                <StatReportCard label="Finals" wins={reportStats.final.wins} total={reportStats.final.offered} />
                                <StatReportCard label="Series" wins={reportStats.series.wins} total={reportStats.series.offered} />
                                <StatReportCard label="Top Number" wins={reportStats.top.wins} total={reportStats.top.offered} />
                            </div>

                            {spinHistory.length < 15 && (
                                <div className="mt-4 bg-gray-50 dark:bg-gray-900/30 p-3 rounded-2xl border border-dashed border-gray-200 dark:border-gray-700">
                                    <p className="text-[10px] font-black text-gray-400 italic text-center uppercase tracking-widest">
                                        Triangulating Wheel Arcs... (Need {15 - spinHistory.length} spins)
                                    </p>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { NumberGrid } from './components/NumberGrid';
import { SpinHistory } from './components/SpinHistory';
import { BettingChart } from './components/BettingChart';
import { ToastContainer } from './components/Toast';
import { VipPage } from './components/VipPage';
import { IntroductionPage } from './components/IntroductionPage';
import { ConfirmationModal } from './components/ConfirmationModal';
import type { ToastData, SeriesType, ComplexPrediction, RouletteColor } from './types';
import { getNeighbours, getSeriesType } from './utils/roulette';
import { PredictionDisplay } from './components/PredictionDisplay';
import { NUMBER_COLORS, ROULETTE_NUMBERS, EUROPEAN_WHEEL_ORDER } from './constants';

const MIN_SPINS_FOR_PATTERNS = 6;
const SESSION_STORAGE_KEY = 'rouletteSession_v6';
const INPUT_THROTTLE_MS = 400;

type PageType = 'main' | 'vip' | 'info';

export interface HitStatus {
    color: boolean;
    final: boolean;
    series: boolean;
    top: boolean;
}

const App: React.FC = () => {
  const [theme, setTheme] = useState<'light' | 'dark'>('dark');
  const [spinHistory, setSpinHistory] = useState<number[]>([]);
  const [alerts, setAlerts] = useState<ToastData[]>([]);
  const [alertsEnabled, setAlertsEnabled] = useState<boolean>(true);
  const [currentPage, setCurrentPage] = useState<PageType>('main');
  const [showClearConfirmation, setShowClearConfirmation] = useState<boolean>(false);
  const [bettingMap, setBettingMap] = useState<Map<number, number>>(new Map());
  const [balance, setBalance] = useState<number>(0);
  const [lastHitStatus, setLastHitStatus] = useState<HitStatus | null>(null);

  const lastInputTime = useRef<number>(0);

  const [isStrategyEnabled, setIsStrategyEnabled] = useState<boolean>(true);
  const [unitMultiplier, setUnitMultiplier] = useState<number>(1);
  const [unitMultiplierInput, setUnitMultiplierInput] = useState<string>('1');
  const [betStrategyMode, setBetStrategyMode] = useState<'235' | '123' | '111'>('235');
  const [neighbourDepth, setNeighbourDepth] = useState<3 | 5>(3);

  const triggerHaptic = (type: 'light' | 'medium' | 'heavy' | 'error' | 'success') => {
    if (!('vibrate' in navigator)) return;
    switch (type) {
      case 'light': navigator.vibrate(10); break;
      case 'medium': navigator.vibrate(25); break;
      case 'heavy': navigator.vibrate(50); break;
      case 'success': navigator.vibrate([30, 50, 30]); break;
      case 'error': navigator.vibrate([40, 30, 40]); break;
    }
  };

  useEffect(() => {
    const savedData = localStorage.getItem(SESSION_STORAGE_KEY);
    if (savedData) {
        try {
            const parsed = JSON.parse(savedData);
            if (parsed.history) setSpinHistory(parsed.history);
            if (parsed.alerts) setAlerts(parsed.alerts);
            if (parsed.multiplier) {
                setUnitMultiplier(parsed.multiplier);
                setUnitMultiplierInput(parsed.multiplier.toString());
            }
            if (parsed.strategyMode) setBetStrategyMode(parsed.strategyMode);
            if (parsed.depth) setNeighbourDepth(parsed.depth);
            if (parsed.strategyEnabled !== undefined) setIsStrategyEnabled(parsed.strategyEnabled);
            if (parsed.theme) setTheme(parsed.theme);
        } catch (error) {
            console.error("Failed to restore session:", error);
        }
    }
  }, []);

  useEffect(() => {
    const sessionData = {
        history: spinHistory,
        alerts: alerts,
        multiplier: unitMultiplier,
        strategyMode: betStrategyMode,
        depth: neighbourDepth,
        strategyEnabled: isStrategyEnabled,
        theme: theme
    };
    localStorage.setItem(SESSION_STORAGE_KEY, JSON.stringify(sessionData));
  }, [spinHistory, alerts, unitMultiplier, betStrategyMode, neighbourDepth, isStrategyEnabled, theme]);

  const calculateBets = useCallback((history: number[], mode: '235' | '123' | '111', depth: 3 | 5): Map<number, number> => {
    const newBettingMap = new Map<number, number>();
    const uniqueHistoryByRecency = [...new Set([...history].reverse())];
    if (uniqueHistoryByRecency.length < 2) return newBettingMap;
    const masterCandidatePool: number[] = [];
    uniqueHistoryByRecency.forEach(num => {
      if (num !== -1) {
        const depthVal = depth === 5 ? 2 : 1;
        masterCandidatePool.push(...getNeighbours(num, depthVal));
      }
    });
    const finalCandidates = [...new Set(masterCandidatePool)].filter(n => n !== -1);
    if (mode === '111') {
        finalCandidates.slice(0, 20).forEach(candidate => newBettingMap.set(candidate, 1));
        return newBettingMap;
    }
    const bet5 = new Set<number>();
    const bet3 = new Set<number>();
    const bet2 = new Set<number>();
    const alreadyBetOn = new Set<number>();
    for (const candidate of finalCandidates) {
      if (alreadyBetOn.has(candidate)) continue;
      if (bet5.size < 4) bet5.add(candidate);
      else if (bet3.size < 6) bet3.add(candidate);
      else if (bet2.size < 10) bet2.add(candidate);
      alreadyBetOn.add(candidate);
      if (bet2.size >= 10) break;
    }
    const units = mode === '235' ? [5, 3, 2] : [3, 2, 1];
    bet5.forEach(num => newBettingMap.set(num, units[0]));
    bet3.forEach(num => newBettingMap.set(num, units[1]));
    bet2.forEach(num => newBettingMap.set(num, units[2]));
    return newBettingMap;
  }, []);

  useEffect(() => {
      if (spinHistory.length > 0) {
          setBettingMap(calculateBets(spinHistory, betStrategyMode, neighbourDepth));
      } else {
          setBettingMap(new Map());
      }
  }, [spinHistory, betStrategyMode, neighbourDepth, calculateBets]);

  const totalBaseBetUnits = useMemo(() => {
    let total = 0;
    for (const unit of bettingMap.values()) total += unit;
    return total;
  }, [bettingMap]);

  useEffect(() => {
    if (!isStrategyEnabled) {
        setBalance(0);
        return;
    }
    let cumulativeBaseBalance = 0;
    for (let i = 8; i < spinHistory.length; i++) {
        const historySliceForBetting = spinHistory.slice(0, i);
        const winningNumber = spinHistory[i];
        const betsForThisRound = calculateBets(historySliceForBetting, betStrategyMode, neighbourDepth);
        const totalBaseBetForThisRound = (Array.from(betsForThisRound.values()) as number[]).reduce((sum, val) => sum + val, 0);
        if (totalBaseBetForThisRound > 0) {
            const betOnWinningNumber = betsForThisRound.get(winningNumber) || 0;
            const profitOrLoss = betOnWinningNumber > 0 
                ? (betOnWinningNumber * 36) - totalBaseBetForThisRound 
                : -totalBaseBetForThisRound;
            cumulativeBaseBalance += profitOrLoss;
        }
    }
    setBalance(cumulativeBaseBalance * unitMultiplier);
  }, [spinHistory, calculateBets, isStrategyEnabled, unitMultiplier, betStrategyMode, neighbourDepth]);

  useEffect(() => {
    if (theme === 'dark') document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
  }, [theme]);

  const toggleTheme = () => {
    triggerHaptic('light');
    setTheme(prevTheme => (prevTheme === 'light' ? 'dark' : 'light'));
  };

  const checkForAlerts = useCallback((history: number[]): Omit<ToastData, 'id'>[] => {
    if (history.length < MIN_SPINS_FOR_PATTERNS || !alertsEnabled) return [];
    const newAlerts: Omit<ToastData, 'id'>[] = [];
    const lastSpin = history[history.length - 1];
    const predictions = new Map<string, number[]>();
    for (let i = 0; i <= history.length - 3; i++) {
      if (history[i] === lastSpin) {
        const prediction = [history[i + 1], history[i + 2]];
        predictions.set(prediction.join(','), prediction);
      }
    }
    if (predictions.size > 0) newAlerts.push({ trigger: [lastSpin], predictions: Array.from(predictions.values()) });
    return newAlerts;
  }, [alertsEnabled]);

  const prediction = useMemo<ComplexPrediction | null>(() => {
    if (spinHistory.length < 5) return null;

    const history = spinHistory;
    const seriesHistory = history.map(getSeriesType);
    const lastNumber = history[history.length - 1];
    const lastFinalDigit = lastNumber % 10;
    const lastSeries = seriesHistory[seriesHistory.length - 1];

    const scores: Map<number, number> = new Map();
    ROULETTE_NUMBERS.forEach(n => scores.set(n, 0));

    // 1. IMPROVED SERIES PREDICTION (Target 50%+)
    // Uses Markov Chains + Clumping vs Alternation Detection
    const sTransitions: Map<SeriesType, number> = new Map();
    let isAlternating = false;
    if (seriesHistory.length >= 4) {
        const last4 = seriesHistory.slice(-4);
        if (last4[0] !== last4[1] && last4[1] !== last4[2] && last4[2] !== last4[3]) {
            isAlternating = true;
        }
    }

    for (let i = 0; i < seriesHistory.length - 1; i++) {
        if (seriesHistory[i] === lastSeries) {
            const next = seriesHistory[i+1];
            if (next !== 'none') sTransitions.set(next, (sTransitions.get(next) || 0) + 1);
        }
    }
    let likelySeries = Array.from(sTransitions.entries()).sort((a,b) => b[1]-a[1])[0]?.[0] || lastSeries;

    // If alternating, flip the prediction to the "other" most likely transition
    if (isAlternating) {
        const alternatives = Array.from(sTransitions.entries()).filter(e => e[0] !== lastSeries);
        if (alternatives.length > 0) likelySeries = alternatives.sort((a,b) => b[1]-a[1])[0][0];
    }

    // 2. STRICT FINAL DIGIT (Weight 35) - Request: Only if 2 times or above
    const dTransitions: Map<number, number> = new Map();
    for (let i = 0; i < history.length - 1; i++) {
        if (history[i] % 10 === lastFinalDigit) {
            const nextDigit = history[i+1] % 10;
            dTransitions.set(nextDigit, (dTransitions.get(nextDigit) || 0) + 1);
        }
    }
    const predictedFinalDigits = Array.from(dTransitions.entries())
        .filter(([_, count]) => count >= 2) // STRICT GENIUS FILTER
        .sort((a,b) => b[1]-a[1])
        .slice(0, 3)
        .map(([d]) => d);

    // 3. WHEEL DISPLACEMENT TRACKING (DEALER SIGNATURE)
    // Tracks the physical arc distance consistently hit by this dealer
    const displacements: number[] = [];
    for (let i = 0; i < history.length - 1; i++) {
        const start = EUROPEAN_WHEEL_ORDER.indexOf(history[i]);
        const end = EUROPEAN_WHEEL_ORDER.indexOf(history[i+1]);
        displacements.push((end - start + 37) % 37);
    }

    const freqDisplacements: Map<number, number> = new Map();
    displacements.forEach(d => freqDisplacements.set(d, (freqDisplacements.get(d) || 0) + 1));
    const topDisps = Array.from(freqDisplacements.entries())
        .filter(e => e[1] >= 2)
        .sort((a,b) => b[1]-a[1])
        .slice(0, 2);

    const targetIndices = topDisps.map(([d]) => (EUROPEAN_WHEEL_ORDER.indexOf(lastNumber) + d) % 37);

    // 4. TRIANGULATION ENGINE (Top Number Accuracy 60%+)
    ROULETTE_NUMBERS.forEach(n => {
        let score = 0;
        const nIdx = EUROPEAN_WHEEL_ORDER.indexOf(n);
        const nFinal = n % 10;
        const nSeries = getSeriesType(n);

        // Layers of evidence
        if (predictedFinalDigits.includes(nFinal)) score += 40;
        if (likelySeries && nSeries === likelySeries) score += 20;
        if (targetIndices.includes(nIdx)) score += 50;

        // Sequence Pattern Boost
        const last2 = history.slice(-2);
        for (let i = 0; i <= history.length - 3; i++) {
            if (history[i] === last2[0] && history[i+1] === last2[1] && history[i+2] === n) {
                score += 100; // Dealer Signature Peak
            }
        }

        // Convergence Multiplier
        let overlaps = 0;
        if (predictedFinalDigits.includes(nFinal)) overlaps++;
        if (likelySeries && nSeries === likelySeries) overlaps++;
        if (targetIndices.includes(nIdx)) overlaps++;

        if (overlaps >= 2) score *= 2.0;
        if (overlaps >= 3) score *= 3.0;

        scores.set(n, score);
    });

    // Neighborhood smoothing
    const rawPicks = Array.from(scores.entries()).sort((a,b) => b[1]-a[1]);
    if (rawPicks[0] && rawPicks[0][1] > 20) {
        const king = rawPicks[0][0];
        getNeighbours(king, 1).forEach(nb => {
            scores.set(nb, (scores.get(nb) || 0) + (rawPicks[0][1] * 0.4));
        });
    }

    const finalTop = Array.from(scores.entries())
        .sort((a,b) => b[1]-a[1])
        .slice(0, 3)
        .filter(e => e[1] > 10)
        .map(([num, score]) => ({
            num,
            confidence: Math.min(99, Math.round((score / 250) * 100))
        }));

    return {
        series: likelySeries,
        topNumbers: finalTop,
        color: NUMBER_COLORS[finalTop[0]?.num] || null,
        finalDigits: predictedFinalDigits
    };
  }, [spinHistory]);

  const handleAddSpin = useCallback((num: number) => {
    const now = Date.now();
    if (now - lastInputTime.current < INPUT_THROTTLE_MS) return;
    lastInputTime.current = now;

    if (prediction) {
        setLastHitStatus({
            color: prediction.color === NUMBER_COLORS[num],
            final: prediction.finalDigits.includes(num % 10),
            series: prediction.series === getSeriesType(num),
            top: prediction.topNumbers.some(tn => tn.num === num)
        });
    }

    const newHistory = [...spinHistory, num];
    setSpinHistory(newHistory);
    triggerHaptic(prediction?.topNumbers.some(t => t.num === num) ? 'success' : 'medium');

    if (newHistory.length >= MIN_SPINS_FOR_PATTERNS) {
        const alertsFromCheck = checkForAlerts(newHistory);
        if (alertsFromCheck.length > 0) {
            const freshAlerts = alertsFromCheck.map((alert, index) => ({ ...alert, id: Date.now() + index })).reverse();
            setAlerts(currentAlerts => [...freshAlerts, ...currentAlerts].slice(0, 5));
        }
    }
  }, [spinHistory, checkForAlerts, prediction]);

  const handleRemoveLastSpin = useCallback(() => {
    if (spinHistory.length === 0) return;
    triggerHaptic('light');
    setSpinHistory(prev => prev.slice(0, -1));
    setLastHitStatus(null);
  }, [spinHistory]);

  const handleRemoveAlert = (id: number) => {
    triggerHaptic('light');
    setAlerts(currentAlerts => currentAlerts.filter(alert => alert.id !== id));
  };

  const handleClearSession = () => {
    triggerHaptic('error');
    setSpinHistory([]);
    setAlerts([]);
    setLastHitStatus(null);
    localStorage.removeItem(SESSION_STORAGE_KEY);
    setShowClearConfirmation(false);
  };

  const switchPage = (page: PageType) => {
    triggerHaptic('light');
    setCurrentPage(page);
  };

  return (
    <div className="min-h-screen text-gray-800 dark:text-gray-200 font-sans selection:bg-gold/30 flex flex-col overflow-hidden">
      <header className="bg-white/80 dark:bg-gray-900/80 backdrop-blur-md sticky top-0 z-40 shadow-sm border-b border-gray-200 dark:border-gray-800 pt-[env(safe-area-inset-top)]">
        <div className="container mx-auto px-4 py-1.5 flex justify-between items-center h-11">
          <h1 className="text-base font-bold text-gray-900 dark:text-white" style={{fontFamily: "'Playfair Display', serif"}}>
            Roulette <span className="text-gold">Tracker</span>
          </h1>
          <div className="flex items-center space-x-1.5">
            <button type="button" onClick={() => switchPage('info')} className="p-1 rounded-lg text-gray-500 border border-gray-200 dark:border-gray-700 active:scale-95" title="Help & Info">
                <div className="w-3.5 h-3.5 rounded border-2 border-current flex items-center justify-center font-black text-[9px]">?</div>
            </button>
            <button type="button" onClick={() => switchPage(currentPage === 'vip' ? 'main' : 'vip')} className={`p-1 rounded-lg transition-all flex items-center space-x-1 border active:scale-95 ${currentPage === 'vip' ? 'bg-gold text-black border-gold' : 'text-gold border-gold/20'}`}>
              <CrownIcon />
              <span className="text-[10px] font-black uppercase tracking-tighter">VIP</span>
            </button>
            <button onClick={toggleTheme} className="p-1 rounded-lg text-gray-600 dark:text-gray-300 border border-gray-200 dark:border-gray-700 active:scale-95">
              {theme === 'light' ? <MoonIcon /> : <SunIcon />}
            </button>
          </div>
        </div>
      </header>

      <main className="flex-1 overflow-y-auto overflow-x-hidden custom-scrollbar pb-[env(safe-area-inset-bottom)]">
        <div className="container mx-auto px-1.5 py-2 max-w-5xl">
            {currentPage === 'main' ? (
            <div className="flex flex-col gap-1.5 animate-fade-in">
                <div className="w-full bg-white dark:bg-gray-800 p-2 rounded-xl shadow-md border border-gray-100 dark:border-gray-700/50">
                    <NumberGrid onNumberSelect={handleAddSpin} disabled={false} />
                </div>

                <div className="bg-white dark:bg-gray-800 p-1.5 rounded-xl shadow-md border border-gray-100 dark:border-gray-700/50">
                    <div className="flex flex-wrap items-center justify-between gap-x-3 gap-y-1 mb-1 px-1">
                        <div className="flex items-center gap-2">
                            <h2 className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Strategy</h2>
                            <button onClick={() => setIsStrategyEnabled(!isStrategyEnabled)} className={`relative inline-flex items-center h-3.5 rounded-full w-7 transition-colors ${isStrategyEnabled ? 'bg-roulette-green' : 'bg-gray-400 dark:bg-gray-600'}`}>
                                <span className={`inline-block w-2.5 h-2.5 transform bg-white rounded-full transition-transform ${isStrategyEnabled ? 'translate-x-3.5' : 'translate-x-1'}`} />
                            </button>
                        </div>

                        <div className="flex items-center gap-2">
                             <div className="flex items-center gap-1 bg-gray-50 dark:bg-gray-900/40 p-0.5 px-1.5 rounded-lg border border-gray-100 dark:border-gray-700/30">
                                <span className="text-[9px] font-black text-gray-400 uppercase tracking-tighter">Unit:</span>
                                <input type="number" value={unitMultiplierInput} onChange={(e) => {
                                        setUnitMultiplierInput(e.target.value);
                                        const num = parseInt(e.target.value, 10);
                                        if (!isNaN(num) && num > 0) setUnitMultiplier(num);
                                    }} onBlur={() => {
                                        const num = parseInt(unitMultiplierInput, 10);
                                        if (isNaN(num) || num < 1) { setUnitMultiplierInput('1'); setUnitMultiplier(1); }
                                    }} disabled={!isStrategyEnabled} className="w-8 bg-transparent text-center font-black text-[11px] outline-none disabled:opacity-40" />
                            </div>

                            <div className="flex bg-gray-50 dark:bg-gray-900/40 rounded-lg p-0.5 border border-gray-100 dark:border-gray-700/30">
                                <button onClick={() => {triggerHaptic('light'); setNeighbourDepth(3)}} disabled={!isStrategyEnabled} className={`px-2 py-0.5 text-[9px] font-black rounded ${neighbourDepth === 3 ? 'bg-gold text-black' : 'text-gray-500'}`}>N3</button>
                                <button onClick={() => {triggerHaptic('light'); setNeighbourDepth(5)}} disabled={!isStrategyEnabled} className={`px-2 py-0.5 text-[9px] font-black rounded ${neighbourDepth === 5 ? 'bg-gold text-black' : 'text-gray-500'}`}>N5</button>
                            </div>

                            <button onClick={() => {triggerHaptic('light'); setBetStrategyMode(m => m === '235' ? '123' : m === '123' ? '111' : '235')}} disabled={!isStrategyEnabled} className={`px-2 py-0.5 text-[9px] font-black rounded transition-all shadow-sm ${betStrategyMode === '235' ? 'bg-green-600 text-white' : betStrategyMode === '123' ? 'bg-yellow-500 text-black' : 'bg-blue-600 text-white'} disabled:opacity-30`}>{betStrategyMode}</button>
                        </div>
                    </div>

                    {isStrategyEnabled && (
                        <div className="animate-fade-in space-y-1.5">
                            {spinHistory.length >= 8 ? (
                                <>
                                    <div className="flex justify-between items-center py-1 border-t border-gray-100 dark:border-gray-700/50">
                                        <div className="text-[10px] font-black uppercase tracking-tighter">
                                            <span className="text-gray-400">P/L: </span>
                                            <span className={balance >= 0 ? 'text-green-500' : 'text-red-500'}>{balance >= 0 ? '+' : ''}{balance}</span>
                                        </div>
                                        {bettingMap.size > 0 && (
                                            <div className="text-[10px] font-black text-gray-500 dark:text-gray-400 uppercase tracking-tighter">
                                                Bet: <span className="text-gold text-xs">{totalBaseBetUnits * unitMultiplier}</span>
                                            </div>
                                        )}
                                    </div>
                                    <BettingChart bettingMap={bettingMap} />
                                </>
                            ) : (
                                <div className="border-t border-gray-100 dark:border-gray-700/50 pt-1.5 pb-0.5 text-center">
                                    <p className="text-[9px] text-gray-400 font-bold uppercase tracking-widest italic animate-pulse">Waiting ({8 - spinHistory.length})</p>
                                </div>
                            )}
                        </div>
                    )}
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-1.5">
                    <div className="bg-white dark:bg-gray-800 p-2 rounded-xl shadow-md border border-gray-100 dark:border-gray-700/50">
                        <div className="flex justify-between items-center mb-1.5">
                            <h2 className="text-[10px] font-black uppercase text-gray-400 tracking-widest">History ({spinHistory.length})</h2>
                            <PredictionDisplay prediction={prediction} lastHitStatus={lastHitStatus} />
                        </div>
                        {spinHistory.length > 0 ? <SpinHistory history={spinHistory} /> : <p className="text-gray-400 text-center py-4 text-[9px] font-black uppercase italic tracking-widest">Empty</p>}
                    </div>
                    <div className="bg-white dark:bg-gray-800 p-2 rounded-xl shadow-md border border-gray-100 dark:border-gray-700/50">
                        <h2 className="text-[10px] font-black uppercase text-gray-400 tracking-widest mb-1.5">Alerts</h2>
                        <ToastContainer toasts={alerts} onRemoveToast={handleRemoveAlert} />
                    </div>
                </div>

                <div className="bg-white dark:bg-gray-800 p-2 rounded-xl shadow-md border border-gray-100 dark:border-gray-700/50 mt-0.5 mb-2">
                    <div className="flex items-center justify-between gap-1.5">
                        <div className="flex items-center gap-2 bg-gray-100 dark:bg-gray-900/50 px-2 py-1.5 rounded-lg flex-1 border border-gray-200 dark:border-gray-700/50">
